    },
    [11870894] = {
        ["english"] = { [1] = "What bug comes before the lords of the Council?  A bug, no doubt, wishing to be squashed!" },
        ["text"] = "Яка комаха постала перед лордами Ради? Без сумніву, комаха, яка просить, щоб її розчавили!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3892877146] = {
        ["english"] = { [1] = "We may operate in the shadows of polite society, but out here on the battlefront our powers are properly respected at last." },
        ["text"] = "Ми можемо діяти в тіні пристойного суспільства, але тут, на передовій, наші сили нарешті належно цінують.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1374669555] = {
        ["english"] = { [1] = "Welcome to Camp Oneqwah." },
        ["text"] = "Ласкаво просимо до табору Унква.",
        ["npcs"] = {},
