    },
    [2356328080] = {
        ["english"] = { [1] = "Welcome to SI:7 headquarters, $N." },
        ["text"] = "Ласкаво просимо до штабу ШРУ:7, $N.",
        ["npcs"] = { [1] = 332 },
        ["roles"] = { ["greeting"] = true },
    },
    [1580652653] = {
        ["english"] = { [1] = "Vira Younghoof keeps her practice inside the long house on the west side of the village." },
        ["text"] = "Віра Молоде Копито приймає у довгому будинку на західному боці селища.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [3211487541] = {
        ["english"] = { [1] = "We plant the vegetables.  Our vegetables are eaten by the rabbit.  The rabbit is devoured by the wolf.  The wolf is slain by us.  We take the meat and hide from the wolf's corpse.  It's that Magic Circle of life, or whatever you call it.  \010\010Now go see Telonis in the Cenarion Enclave to get started and let me return to my duties." },
        ["text"] = "Ми садимо овочі. Овочі їсть кролик. Кролика пожирає вовк. Вовка вбиваємо ми. З тіла вовка беремо м'ясо й шкуру. Це там те ваше магічне Коло життя чи як ви його називаєте.  \010\010А тепер іди до Телоніса в Кенарійський Анклав, щоб почати, а мені дай повернутися до обов'язків.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [2205967543] = {
        ["english"] = { [1] = "Welcome to the Farstrider Lodge, $N!" },
        ["text"] = "Ласкаво просимо до Пристанища далекоходців, $N!",
        ["npcs"] = { [1] = 1156 },
        ["roles"] = { ["greeting"] = true },
    },
    [3336679215] = {
        ["english"] = { [1] = "We did this for about six months and watched as the house went through horrifying changes. Foul monsters roamed through the manor at will. Dark cultists populated every inch with various paraphernalia relating to rituals and sacrifices. We knew that we could not hide much longer.$B$BAs expected, we were found and captured. They stripped us of all our clothes and laid us out inside a circle of blood. We sat there for days, naked and terrified." },
        ["text"] = "Так тривало близько шести місяців, і ми спостерігали, як із домом відбуваються жахливі зміни. Огидні чудовиська вільно блукали маєтком. Темні культисти заповнили кожен закуток різним приладдям для ритуалів і жертвоприношень. Ми знали, що довго ховатися не зможемо.$B$BЯк і слід було чекати, нас знайшли й схопили. З нас зірвали весь одяг і поклали всередині кола крові. Ми просиділи там кілька днів — голі й нажахані.",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["greeting"] = true },
    },
    [3928320013] = {
        ["english"] = { [1] = "What is it that you do exactly, Rohan?" },
        ["text"] = "Чим саме ти займаєшся, Рогане?",
        ["npcs"] = { [1] = 16131 },
        ["roles"] = { ["reply"] = true },
    },
    [2333221586] = {
        ["english"] = { [1] = "Why have you come here, $c?" },
        ["text"] = "Навіщо ти прийшов сюди, $c?",
        ["npcs"] = { [1] = 10304 },
        ["roles"] = { ["greeting"] = true },
    },
    [12571664] = {
        ["english"] = { [1] = "Unfortunately, there is little I can teach someone with your experience, my friend. Seek out the night elf Sylvanna Forestmoon, who resides in the Craftsmen's Terrace of Darnassus." },
        ["text"] = "На жаль, з твоїм досвідом я мало чого зможу тебе навчити, друже. Знайди нічну ельфійку Сильванну Лісомісячну, яка мешкає на Терасі Ремісників у Дарнасі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1898715642] = {
        ["english"] = { [1] = "Wushoolay, the Storm Witch.$B$BHer power is the power of the sky, the rain, and the shattered earth.  May she once again reign mother to the Gurubashi.  $B$BWushoolay now dwells far from here.  One day, she may return..." },
        ["text"] = "Вушулай, Відьма Бурі.$B$BЇї сила — це сила неба, дощу й розколотої землі. Нехай вона знову стане матір'ю-правителькою Ґурубаші. $B$BТепер Вушулай живе далеко звідси. Одного дня вона може повернутися...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1879992697] = {
        ["english"] = { [1] = "We don't have any easy path before us. If you've got a strong arm on you, stick around until one of my squads is ready to ascend to Ymirheim. They could use all the help they can get." },
        ["text"] = "Легкого шляху попереду немає. Якщо рука в тебе міцна, зачекай, доки один із моїх загонів буде готовий піднятися до Іміргайму. Їм знадобиться будь-яка допомога.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2293843257] = {
        ["english"] = { [1] = "What can this insignificant servant do for you, $N? Training perhaps?" },
        ["text"] = "Що цей нікчемний слуга може зробити для тебе, $N? Можливо, тренування?",
        ["npcs"] = { [1] = 2123, [2] = 2129, [3] = 3044, [4] = 3045, [5] = 3046, [6] = 4606, [7] = 4607, [8] = 4608 },
        ["roles"] = { ["greeting"] = true },
    },
    [2872790671] = {
        ["english"] = { [1] = "We stand together with the Alliance, $r. An evil, so old that the world has forgotten it, seeks to engulf us all; first on Kalimdor and then the rest of Azeroth. It is driven by a hatred of all things born of the great Shapers: The eternal Titans.$B$BWe are all that stand in the way of C'Thun's armies. We will strike first and bring down the forces of Ahn'Qiraj. Let all of Azeroth quake at the combined might of the Horde and Alliance.$B$BThe war effort needs you!" },
        ["text"] = "Ми стоїмо пліч-о-пліч з Альянсом, $r. Зло, настільки давнє, що світ уже забув про нього, прагне поглинути всіх нас — спершу Калімдор, а потім і решту Азероту. Ним рухає ненависть до всього, що створили великі Творці — вічні титани.$B$BМи — єдина перешкода на шляху армій К'Туна. Ми вдаримо першими й розіб'ємо сили Ан'Кіражу. Нехай увесь Азерот здригнеться перед об'єднаною могуттю Орди й Альянсу.$B$BВійськові зусилля потребують тебе!",
        ["npcs"] = { [1] = 15539, [2] = 15700 },
        ["roles"] = { ["greeting"] = true },
    },
    [1368356642] = {
        ["english"] = { [1] = "Welcome to me shop. What can I do for ye'?" },
        ["text"] = "Ласкаво просимо до моєї крамниці. Чим можу допомогти?",
        ["npcs"] = { [1] = 1703 },
        ["roles"] = { ["greeting"] = true },
    },
    [3373216700] = {
        ["english"] = { [1] = "We're miners, farmers and craftsmen - not soldiers.  But we'll defend our land with our bare fists if we must." },
        ["text"] = "Ми шахтарі, фермери й ремісники — не солдати. Але якщо доведеться, захищатимемо свою землю голими кулаками.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3110341507] = {
        ["english"] = { [1] = "Where is Elder Moonwarden?" },
        ["text"] = "Де старійшина Місячний Вартовий?",
        ["npcs"] = { [1] = 15572, [2] = 15575, [3] = 15582, [4] = 15588, [5] = 15604 },
        ["roles"] = { ["reply"] = true },
    },
    [2844980423] = {
        ["english"] = { [1] = "Welcome friend! What would you like to see?" },
        ["text"] = "Вітаю, друже! Що бажаєш подивитися?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [257287603] = {
        ["english"] = { [1] = "What is your business here, $c?" },
        ["text"] = "Яка в тебе тут справа, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1784136587] = {
        ["english"] = { [1] = "When Ahune surfaces, will we be ready?" },
        ["text"] = "Коли Агун з'явиться на поверхні, чи будемо ми готові?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2349993694] = {
        ["english"] = { [1] = "Tread carefully, $r.$b$bThese corpses here are all that remain of my best men." },
        ["text"] = "Ступай обережно, $r.$b$bЦі тіла — все, що залишилося від моїх найкращих воїнів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1940397795] = {
        ["english"] = { [1] = "We have barely any supplies.  If we want to send a ground assault into the Field of Strife, then we'll need a lot more!" },
        ["text"] = "У нас майже немає припасів. Якщо хочемо відправити наземний наступ на Поле Чвар, нам знадобиться набагато більше!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3582530695] = {
        ["english"] = { [1] = "Us see balloon north of ruins up above.  It take you to far off places." },
        ["text"] = "Ми бачимо повітряну кулю на північ від руїн, високо вгорі. Вона відвезе тебе в далекі місця.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2439012089] = {
        ["english"] = { [1] = "What can I do at an inn?" },
        ["text"] = "Що можна робити в таверні?",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 2352, [4] = 2388, [5] = 5688, [6] = 5814, [7] = 6727, [8] = 6734, [9] = 6736, [10] = 6737, [11] = 6739, [12] = 6741, [13] = 6747, [14] = 6790, [15] = 6928, [16] = 6929, [17] = 6930, [18] = 7731, [19] = 9356, [20] = 12196, [21] = 14731, [22] = 16256 },
        ["roles"] = { ["reply"] = true },
    },
    [290862472] = {
        ["english"] = { [1] = "Where is Elder Wildmane?" },
        ["text"] = "Де старійшина Дикогривий?",
        ["npcs"] = { [1] = 15573, [2] = 15583, [3] = 15584, [4] = 15586 },
        ["roles"] = { ["reply"] = true },
    },
    [4262373533] = {
        ["english"] = { [1] = "Well met master of Rod and Reel!   If you be willing to test your skills against the best fisher-folk in the lands then listen up!   On this very Sunday there be a contest in Stranglethorn where the master angler will be chosen!\010\010" },
        ["text"] = "Вітаю, майстре вудки й волосіні! Якщо готовий випробувати свої вміння проти найкращих рибалок цих земель — слухай уважно! Цієї самої неділі в Тернистій долині відбудеться змагання, де оберуть Майстра Вудки!\010\010",
        ["npcs"] = { [1] = 15119 },
        ["roles"] = { ["greeting"] = true },
    },
    [739548228] = {
        ["english"] = { [1] = "What battleground you want?" },
        ["text"] = "На яке поле бою хочеш?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [110308090] = {
        ["english"] = { [1] = "Watch your back, stranger." },
        ["text"] = "Стережися, незнайомцю.",
        ["npcs"] = { [1] = 6766 },
        ["roles"] = { ["greeting"] = true },
    },
    [2072680912] = {
        ["english"] = { [1] = "We're in over our heads, $r! Watch your back!" },
        ["text"] = "Ми втрапили по самі вуха, $r! Стережи спину!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1979412983] = {
        ["english"] = { [1] = "Tower Point East holds the pass between the Field of Strife and Horde territories to the south.$B$BIt is controlled by the Horde.The East Frostwolf Tower protects the gate between Frostwolf Village and Frostwolf Keep.$B$BIt is controlled by the Horde." },
        ["text"] = "Східна Вежова точка утримує прохід між Полем Чвар і територіями Орди на півдні.$B$BЇї контролює Орда.Східна Вежа Морозного Вовка захищає браму між селищем Морозного Вовка та фортецею Морозного Вовка.$B$BЇї контролює Орда.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2914944438] = {
        ["english"] = { [1] = "Well then! A mounted Charge is about more than just kickin' yer mount ta full speed an' hollerin' yer lungs out... though that IS the fun part, heh! But the Charge Target will teach ye the finer points.$B$BA good Charge is all about distance and timing. Ye can't be TOO close, or ye won't get enough speed. But ye can't be too far away either or yer mount will tire! As for timin'...$B$BYe'll want ta make sure the Charge Target doesn't have a layer o' Defend up before ye rush in. If it does, use yer Shield Breaker ta make it vulnerable, and THEN Charge in!$B$BSame goes for the real thing: Try ta drop yer opponent defenses before ye Charge!" },
        ["text"] = "Ну що ж! Ривок верхи — це не просто розігнати скакуна на повну й кричати на все горло... хоча це НАЙВЕСЕЛІША частина, хе-хе! Але мішень для ривка навчить тебе тонкощів.$B$BХороший ривок — це відстань і час. Не можна бути НАДТО близько, бо не набереш швидкості. Але й надто далеко не можна, бо скакун втомиться! А щодо часу...$B$BПеред ривком переконайся, що на мішені немає шару «Захисту». Якщо є — використай «Розбивач щита», щоб зробити її вразливою, а ВЖЕ ТОДІ рвися вперед!$B$BТак само й у справжньому бою: спершу спробуй зняти захист супротивника, а потім атакуй ривком!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2613206497] = {
        ["english"] = { [1] = "What do you have for sale?" },
        ["text"] = "Що в тебе на продаж?",
        ["npcs"] = { [1] = 14846 },
        ["roles"] = { ["reply"] = true },
    },
    [4039414787] = {
        ["english"] = { [1] = "We must first craft a prison to confine the beast, if you wish to progress further." },
        ["text"] = "Якщо хочеш просунутися далі, спершу треба створити в'язницю, здатну втримати звіра.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [79040106] = {
        ["english"] = { [1] = "Weapons Trainer" },
        ["text"] = "Наставник зброї",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 4262, [5] = 5595, [6] = 6272, [7] = 6740, [8] = 8931 },
        ["roles"] = { ["reply"] = true },
    },
    [3734944415] = {
        ["english"] = { [1] = "What can I do with these gifts?" },
        ["text"] = "Що можна зробити з цими подарунками?",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [3883895341] = {
        ["english"] = { [1] = "Who is Talon King Ikiss?" },
        ["text"] = "Хто такий Король Кігтів Ікісс?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2210074941] = {
        ["english"] = { [1] = "What is the Brotherhood of the Light? Well... We are all members of the Argent Dawn at the core - members of the Argent Dawn that aren't held in check by morals, guilt and useless human emotion. Consider us Scarlet Crusade minus the stupidity, lack of leadership, and blind zealotry.$B$BDon't let the Scarlet Commander tell you otherwise.$B$BAnd don't let Tyrosus know I said that... It would be a terrible shame if I had to brutally maim him should a brawl break out.\010" },
        ["text"] = "Що таке Братство Світла? Ну... По суті, ми всі члени Сріблястого Світанку — ті його члени, яких не стримують мораль, провина й марні людські емоції. Вважай нас Багряним Походом без дурості, бездарного керівництва й сліпого фанатизму.$B$BНе дозволяй Багряному командиру переконати тебе в іншому.$B$BІ не кажи Тіросусу, що я це сказав... Було б страшенно прикро, якби під час бійки мені довелося жорстоко його покалічити.\010",
        ["npcs"] = { [1] = 16112 },
        ["roles"] = { ["greeting"] = true },
    },
    [1553644943] = {
        ["english"] = { [1] = "Without knowledge of the incantations required to unite the two parts, Lord Vyletongue was unable to use the scepter. However, now that I am free of the curse of Vyletongue's corruption, I will be able to assist you, if you'd like to bring me the two parts -- both the head and the rod of the scepter." },
        ["text"] = "Не знаючи заклять, потрібних для з'єднання двох частин, лорд Злоязик не міг використати скіпетр. Але тепер, коли я звільнився від прокляття його скверни, зможу допомогти, якщо принесеш мені обидві частини — і навершя, і стрижень скіпетра.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [266520009] = {
        ["english"] = { [1] = "What plants are in Felwood that might be corrupted?" },
        ["text"] = "Які рослини в Скверноліссі могли бути осквернені?",
        ["npcs"] = { [1] = 9528, [2] = 9529 },
        ["roles"] = { ["reply"] = true },
    },
    [693674883] = {
        ["english"] = { [1] = "With all the Siege Engines nearly complete, I'm getting a bit bored!$B$B$B$BYou're not an engineer, are you? Care to compare blueprints...?" },
        ["text"] = "Коли майже всі облогові машини готові, мені стає нудно!$B$B$B$BТи часом не інженер? Хочеш порівняти креслення...?",
        ["npcs"] = { [1] = 4941 },
        ["roles"] = { ["greeting"] = true },
    },
    [932747938] = {
        ["english"] = { [1] = "Wanted DEAD for treason and other treacherous acts against the Horde!$B$BAll bounties paid by Captain Gort." },
        ["text"] = "РОЗШУКУЄТЬСЯ МЕРТВИМ за зраду та інші підступні злочини проти Орди!$B$BУсі нагороди виплачує капітан Ґорт.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1786520210] = {
        ["english"] = { [1] = "Where can I find crypt fiend parts, Leopold?" },
        ["text"] = "Де знайти частини склепового павука, Леопольде?",
        ["npcs"] = { [1] = 16132 },
        ["roles"] = { ["reply"] = true },
    },
    [3941478918] = {
        ["english"] = { [1] = "Watch your step, stranger. We do not allow miscreants in our town." },
        ["text"] = "Дивися під ноги, незнайомцю. Ми не терпимо негідників у нашому місті.",
        ["npcs"] = { [1] = 11279, [2] = 11281 },
        ["roles"] = { ["greeting"] = true },
    },
    [677144230] = {
        ["english"] = { [1] = "Transcript the Tablet" },
        ["text"] = "Зробити копію таблички",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2307812369] = {
        ["english"] = { [1] = "Would you believe that in my darkest hour, at the apex of my being, I failed.$B$BAs I fled from the wanton destruction of the forces that overwhelmed us, the only sounds I could hear were the screams of my soldiers and the rapid beat of my own heart.$B$BA short while later, I returned to the Blasted Lands in hopes of rescuing my men and restoring my honor. Instead I was captured and beaten until dead.$B$BWhat I found out during my inquisition and subsequent torture was horrifying." },
        ["text"] = "Повірив би ти, що в мою найтемнішу годину, на вершині моєї сили, я зазнав поразки.$B$BКоли я тікав від безглуздого руйнування, яке вчинили сили, що нас переважили, чув лише крики своїх солдатів і шалений стукіт власного серця.$B$BНевдовзі я повернувся до Спустошених земель, сподіваючись урятувати людей і відновити честь. Натомість мене схопили й били до смерті.$B$BТе, що я дізнався під час допиту й подальших тортур, було жахливим.",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["greeting"] = true },
    },
    [3050888999] = {
        ["english"] = { [1] = "Ye're beyond my skill to teach, $N. Go pester Tally Berryfizz; she's a gnome living in Tinker Town of Ironforge. Oh, and since you're headed up anyway, give Kali my love." },
        ["text"] = "Ти перевершив мою майстерність наставника, $N. Іди докучай Таллі Ягодошипучці; вона гномка й живе в Місті Механіків у Стальгорні. І раз уже піднімаєшся туди, передай Калі моє кохання.",
        ["npcs"] = { [1] = 1470 },
        ["roles"] = { ["greeting"] = true },
    },
    [1501417333] = {
        ["english"] = { [1] = "Yeah, I've heard through the grapevine that I might be seeing you sooner or later. But I don't just take on anyone, I need to make sure you have what it takes first. You willing to take my little test and find out?" },
        ["text"] = "Ага, чутки вже донесли, що рано чи пізно я тебе побачу. Але я не беру кого завгодно — спершу треба переконатися, що ти справді здатний. Готовий пройти маленьке випробування й дізнатися?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1785591332] = {
        ["english"] = { [1] = "Unlike most ogres, I do know what an outhouse is for - giving you a swirlie.  Now beat it." },
        ["text"] = "На відміну від більшості огрів, я знаю, для чого потрібен нужник — щоб занурювати туди твою голову. А тепер забирайся.",
        ["npcs"] = { [1] = 14827 },
        ["roles"] = { ["greeting"] = true },
    },
    [4043007727] = {
        ["english"] = { [1] = "Where is Elder Dawnstrider?" },
        ["text"] = "Де старійшина Світанковий Мандрівник?",
        ["npcs"] = { [1] = 15557 },
        ["roles"] = { ["reply"] = true },
    },
    [3186047180] = {
        ["english"] = { [1] = "Yeah, I need to drop off some things myself.  Find it by heading north up the road to Orgrimmar and then ask one of the grunts there." },
        ["text"] = "Так, мені теж треба дещо віднести. Іди дорогою на північ до Орґріммара, а там запитай когось із рубак.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [838594097] = {
        ["english"] = { [1] = "Time is running out for me... for us all..." },
        ["text"] = "Мій час спливає... наш спільний час...",
        ["npcs"] = { [1] = 10778 },
        ["roles"] = { ["greeting"] = true },
    },
    [2477532168] = {
        ["english"] = { [1] = "We hope you'll be able to ease our headaches.  You try having ten sons, all of them wanting to do something they weren't meant for!$B$BStill, as a father, we do what we must." },
        ["text"] = "Сподіваємося, ти зможеш полегшити наш головний біль. Спробуй сам мати десятьох синів, і кожен хоче займатися тим, для чого зовсім не створений!$B$BТа як батько, мусиш робити те, що мусиш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2476438582] = {
        ["english"] = { [1] = "Um... sorry to bother you, but could I see Goodsteel's ledger again... if you're not using it." },
        ["text"] = "Ем... вибач, що турбую, але чи можна мені ще раз поглянути на книгу обліку Ґудстіла... якщо вона тобі зараз не потрібна.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [311775698] = {
        ["english"] = { [1] = "Where can I get Enchanted Thorium?" },
        ["text"] = "Де можна дістати зачарований торій?",
        ["npcs"] = { [1] = 10304 },
        ["roles"] = { ["reply"] = true },
    },
    [2701168667] = {
        ["english"] = { [1] = "With your help, we might be able to win this thing!" },
        ["text"] = "З твоєю допомогою ми, можливо, зможемо перемогти!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [901283542] = {
        ["english"] = { [1] = "Welcome to Steelgrill's Depot!" },
        ["text"] = "Ласкаво просимо до складу Сталерешітки!",
        ["npcs"] = { [1] = 1694 },
        ["roles"] = { ["greeting"] = true },
    },
    [3491900434] = {
        ["english"] = { [1] = "Ye've got a little skill on ye. Enough to learn ye a few things I wager. Let's see what I can teach ye, shall we?" },
        ["text"] = "Трохи майстерності в тебе є. Думаю, достатньо, щоб навчити кількох речей. Подивімося, чого я можу тебе навчити, гаразд?",
        ["npcs"] = { [1] = 6299, [2] = 10277 },
        ["roles"] = { ["greeting"] = true },
    },
    [4175792991] = {
        ["english"] = { [1] = "We've lost a few good people up here already. I'm beginning to doubt that this place is worth our attention." },
        ["text"] = "Ми вже втратили тут кількох добрих людей. Я починаю сумніватися, що це місце варте нашої уваги.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1581072160] = {
        ["english"] = { [1] = "UDB Missing text" },
        ["text"] = "UDB: текст відсутній",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4147483514] = {
        ["english"] = { [1] = "Tips are always graciously accepted, friend." },
        ["text"] = "Чайові завжди приймаються з вдячністю, друже.",
        ["npcs"] = { [1] = 14844 },
        ["roles"] = { ["greeting"] = true },
    },
    [1462994844] = {
        ["english"] = { [1] = "When the work of a blacksmith reaches your level of expert craftsmanship, I present them with a choice.$B$BWhile you are not required to make a choice, it is recommended that you do - after all, do you want to be a neophyte forever? It is the artisan armorsmiths and weaponsmiths that supply our armies, win our wars and garner acclaim!$B$BBe warned, $N. Once a choice is made and the tasks required completed - there is no going back. One can only walk down one path." },
        ["text"] = "Коли майстерність коваля досягає твого експертного рівня, я ставлю його перед вибором.$B$BТи не зобов'язаний обирати, але я настійно раджу це зробити — хіба хочеш назавжди лишитися новачком? Саме майстри-бронники й майстри-зброярі забезпечують наші армії, виграють війни й здобувають славу!$B$BАле май на увазі, $N: коли зробиш вибір і виконаєш потрібні завдання — дороги назад не буде. Можна йти лише одним шляхом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1686060607] = {
        ["english"] = { [1] = "Yeah, no problem, $N! Sorry... thought you were done with it already." },
        ["text"] = "Так, без проблем, $N! Вибач... думав, ти вже закінчив із цим.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1001905829] = {
        ["english"] = { [1] = "Very well.  I'll take part in this competition." },
        ["text"] = "Гаразд. Я візьму участь у цьому змаганні.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [344572065] = {
        ["english"] = { [1] = "What do you think they're up to?" },
        ["text"] = "Як думаєш, що вони задумали?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [4168649552] = {
        ["english"] = { [1] = "Ye're a fine enchanter indeed! Now it's time fer ye to move on. I want ye to talk to Gimble Thistlefuzz, upstairs. He's a bit of a character, but he'll steer ye in the right direction from here on out!" },
        ["text"] = "Ти справді чудовий заклинач! Тепер час рухатися далі. Хочу, щоб ти поговорив із Ґімблом Будякопухом нагорі. Він трохи дивакуватий, але відтепер направить тебе правильним шляхом!",
        ["npcs"] = { [1] = 11065 },
        ["roles"] = { ["greeting"] = true },
    },
    [940841369] = {
        ["english"] = { [1] = "Ye'll surely find Maxan Anvol tossin' back a few in the Thunderbrew Distillery.  Why don't ye go have yerself a pint and see if he'll teach ye something new." },
        ["text"] = "Максан Анвол точно перехиляє кухоль-другий у броварні Громоварів. Чому б не випити пінту й не попросити його навчити тебе чогось нового.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [1447422231] = {
        ["english"] = { [1] = "We need to figure out what this shadowy group is doing here at Grangol'var Village!" },
        ["text"] = "Треба з'ясувати, що ця таємнича група робить тут, у селищі Ґранґол'вар!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3208264694] = {
        ["english"] = { [1] = "Whitereach Post is something of an unintended stop for me, to put it mildly. My clients are counting on me to deliver my wares and I'm starting to wonder if I'm going to make it in time with all the delays involved." },
        ["text"] = "Застава Білого Плесу стала для мене, м'яко кажучи, незапланованою зупинкою. Клієнти чекають на товар, і через усі ці затримки я вже починаю сумніватися, що встигну вчасно.",
        ["npcs"] = { [1] = 10941 },
        ["roles"] = { ["greeting"] = true },
    },
    [412836623] = {
        ["english"] = { [1] = "Ye won't find a gryphon master just anywhere around Dun Morogh, $glad : lass;.  Ye're going to have to go to Ironforge if ye want to take a gryphon somewhere." },
        ["text"] = "Доглядача грифонів не знайдеш де завгодно в Дун-Морозі, $gхлопче : дівчино;. Якщо хочеш кудись летіти на грифоні, доведеться йти до Стальгорна.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [3216410304] = {
        ["english"] = { [1] = "Where is Elder Bronzebeard?" },
        ["text"] = "Де старійшина Бронзобородий?",
        ["npcs"] = { [1] = 15562, [2] = 15567, [3] = 15569, [4] = 15598 },
        ["roles"] = { ["reply"] = true },
    },
    [3557106780] = {
        ["english"] = { [1] = "Wildhammer dwarves might have fast steeds, but can those Aerie Peak gryphons stand the heat of The Great Forge?  I think not!" },
        ["text"] = "Дворфи Дикого Молота можуть мати швидких скакунів, але чи витримають грифони Орлиного Піку жар Великої Кузні? Не думаю!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4204128967] = {
        ["english"] = { [1] = "Ye sure ye don't want to learn to be a warrior?  Well, it's yer hide on the battlefield.  If ye really want to learn to waggle yer finger, ye best talk to Magis Sparkmantle in the Thunderbrew Distillery." },
        ["text"] = "Точно не хочеш стати воїном? Ну, це твоя шкура на полі бою. Якщо справді хочеш махати пальцями, поговори з Маґісом Іскромантієм у броварні Громоварів.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2776247551] = {
        ["english"] = { [1] = "Ye should take a look in Ironforge if ye have yer mind set on enchanting.  I think I saw a shop over by the gryphon master last time I was up there." },
        ["text"] = "Якщо серйозно хочеш навчитися зачаруванню, зазирни до Стальгорна. Здається, минулого разу я бачив крамницю біля доглядача грифонів.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [100252428] = {
        ["english"] = { [1] = "WHY is he in Blackrock Depths?" },
        ["text"] = "ЧОМУ він у Глибинах Чорнокамінної гори?",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["reply"] = true },
    },
    [1119916052] = {
        ["english"] = { [1] = "What happened then?" },
        ["text"] = "І що сталося потім?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1312505010] = {
        ["english"] = { [1] = "While the focus of the Sha'tar remains on Shadowmoon Valley and Illidan, we cannot ignore the threat that Kael'thas Sunstrider presents." },
        ["text"] = "Хоч увага Ша'тар зосереджена на Долині Тіньового Місяця та Іллідані, ми не можемо ігнорувати загрозу від Кель'таса Сонячного Блукача.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1125950731] = {
        ["english"] = { [1] = "Where is Elder Bloodhoof?" },
        ["text"] = "Де старійшина Криваве Копито?",
        ["npcs"] = { [1] = 15580, [2] = 15582, [3] = 15588, [4] = 15597 },
        ["roles"] = { ["reply"] = true },
    },
    [2324558912] = {
        ["english"] = { [1] = "To reach the Rut'theran Ferry, you will need to travel to Darnassus and take the portal to Rut'theran Village at the base of Teldrassil." },
        ["text"] = "Щоб дістатися до порома Рут'теран, вирушай у Дарнас і скористайся порталом до селища Рут'теран біля підніжжя Тельдрассіля.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [3063168248] = {
        ["english"] = { [1] = "Why is it that there's never a gyrochronatom lying around when you need one?" },
        ["text"] = "Чому, коли потрібен гірохронатом, його ніколи немає поруч?",
        ["npcs"] = { [1] = 10305 },
        ["roles"] = { ["greeting"] = true },
    },
    [4040294617] = {
        ["english"] = { [1] = "Welcome to the Undercity Guild Registry. What do you want?" },
        ["text"] = "Ласкаво просимо до реєстрації гільдій Підмістя. Чого тобі?",
        ["npcs"] = { [1] = 4613 },
        ["roles"] = { ["greeting"] = true },
    },
    [1072845782] = {
        ["english"] = { [1] = "Well hello again, $N!  I don't know how much longer I'm going to keep on trying to set up a shop out in the middle of nowhere.  Still, since you've helped me out in the past, I'll show you some stuff you may find interesting!" },
        ["text"] = "О, знову привіт, $N! Не знаю, скільки ще намагатимуся відкрити крамницю посеред нічого. Та оскільки ти вже допомагав мені раніше, покажу кілька речей, які можуть тебе зацікавити!",
        ["npcs"] = { [1] = 14637 },
        ["roles"] = { ["greeting"] = true },
    },
    [185732656] = {
        ["english"] = { [1] = "Ye might not know it, but in addition to being a skilled tailor, Jormund is also a slayer of giants!  Why he must have overheard a few of us sharing stories when he shouted that he'd killed seven with one blow!  \010\010Ye should pay him a visit at his store on the north side of The Great Forge an' see if he'll tell ye the tale!" },
        ["text"] = "Може, ти й не знаєш, але Джормунд не лише вправний кравець, а ще й убивця велетнів! Мабуть, підслухав, як ми ділилися історіями, бо раптом вигукнув, що одним ударом убив сімох!  \010\010Навідайся до нього в крамницю на північному боці Великої Кузні й попроси розповісти цю історію!",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [1079310121] = {
        ["english"] = { [1] = "What, you can't port there?  Go to the Darkbriar Lodge next to the lake in the Valley of Spirits, up above and to the west of the Valley of Strength." },
        ["text"] = "Що, не можеш відкрити туди портал? Іди до хижі Темноожини біля озера в Долині Духів — нагору й на захід від Долини Сили.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [986808416] = {
        ["english"] = { [1] = "Want to be a smith? Want to forge blades to gut your foe? Hammers to crush his skull? Aye I can help, and gladly too if there is blood to be shed from it." },
        ["text"] = "Хочеш стати ковалем? Хочеш кувати клинки, щоб потрошити ворогів? Молоти, щоб трощити їм черепи? Атож, я допоможу, і залюбки, якщо завдяки цьому проллється кров.",
        ["npcs"] = { [1] = 4596 },
        ["roles"] = { ["greeting"] = true },
    },
    [1941527259] = {
        ["english"] = { [1] = "Who are you?  I feel... so... cold." },
        ["text"] = "Хто ти? Мені... так... холодно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2684820646] = {
        ["english"] = { [1] = "We have been sent here from Darnassus to aid the Stormpike in their time of need." },
        ["text"] = "Нас прислали сюди з Дарнаса, щоб допомогти Грозовій Вершині в скрутний час.",
        ["npcs"] = { [1] = 13443 },
        ["roles"] = { ["greeting"] = true },
    },
    [3669165569] = {
        ["english"] = { [1] = "What is the Ahn'Qiraj war effort?" },
        ["text"] = "Що таке військові приготування до Ан'Кіражу?",
        ["npcs"] = { [1] = 15458, [2] = 15539, [3] = 15700, [4] = 15701 },
        ["roles"] = { ["reply"] = true },
    },
    [2887788963] = {
        ["english"] = { [1] = "Welcome to the Great Forge $g lad : lass;. It may be cold outside but we keep it nice and hot down 'ere. Grab a hammer, strike that anvil and show me ye've got what it takes to be a Blacksmith of the Great Forge!" },
        ["text"] = "Ласкаво просимо до Великої Кузні, $g хлопче : дівчино;. Надворі може бути холодно, але тут унизу ми тримаємо добрячу спеку. Бери молот, бий по ковадлу й покажи, що гідний бути ковалем Великої Кузні!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1236041986] = {
        ["english"] = { [1] = "Why now, $r? I just do not understand it. So much work to be done..." },
        ["text"] = "Чому саме зараз, $r? Я просто не розумію. Стільки роботи попереду...",
        ["npcs"] = { [1] = 15181 },
        ["roles"] = { ["greeting"] = true },
    },
    [316869251] = {
        ["english"] = { [1] = "Why have you done such horrible things?", [2] = "Why have you done such horrible things?\010" },
        ["text"] = "Чому ти робив такі жахливі речі?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1517583245] = {
        ["english"] = { [1] = "Ye learn fast $g lad : lass;, much faster than I can keep up with. If ye want ta continue yer training, I suggest ye see my teacher. His name's Rotgath, Rotgath Stonebeard and ye'll find him in Ironforge at The Great Forge." },
        ["text"] = "Швидко вчишся, $g хлопче : дівчино;, швидше, ніж я встигаю. Якщо хочеш продовжити навчання, раджу звернутися до мого наставника. Його звати Ротґат Кам'янобородий, знайдеш його в Стальгорні, у Великій Кузні.",
        ["npcs"] = { [1] = 1241 },
        ["roles"] = { ["greeting"] = true },
    },
    [783062122] = {
        ["english"] = { [1] = "Ye know more than I do, that's a certainty. Tell ye what though, go talk with me da'. He'll want ye ta prove yerself, but he is a fine teacher indeed. His name's Rotgath, and ye'll find him near the anvils workin steel for ol' Bengus." },
        ["text"] = "Ти знаєш більше за мене, це точно. Ось що: поговори з моїм татом. Він захоче, щоб ти довів свою майстерність, але наставник він чудовий. Його звати Ротґат, знайдеш його біля ковадел — працює зі сталлю для старого Бенґуса.",
        ["npcs"] = { [1] = 10277 },
        ["roles"] = { ["greeting"] = true },
    },
    [3670449677] = {
        ["english"] = { [1] = "Where did the grand admiral go?" },
        ["text"] = "Куди пішов великий адмірал?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3741502929] = {
        ["english"] = { [1] = "We've done it, $g lad : lass;! The Alliance and the Horde have completed gathering everything that we think we'll need for the Ahn'Qiraj War. Right now the final goods are being taken over to Cenarion Hold in Silithus and the last of it will arrive within a day. After that, some brave $g hero : heroine; is going to need to ring the Scarab Gong with the Scepter of the Shifting Sands to open the gates to Ahn'Qiraj. When those gates open, the war begins!" },
        ["text"] = "Ми це зробили, $g хлопче : дівчино;! Альянс і Орда зібрали все, що, на нашу думку, знадобиться для війни за Ан'Кіраж. Просто зараз останні вантажі перевозять до Кенарійської цитаделі в Силітусі, і останній із них прибуде протягом дня. Після цього якомусь відважному $g героєві : героїні; доведеться вдарити Скіпетром Мінливих Пісків у Гонг Скарабея, щоб відчинити брами Ан'Кіражу. Коли брами відчиняться — почнеться війна!",
        ["npcs"] = { [1] = 15701 },
        ["roles"] = { ["greeting"] = true },
    },
    [1074003832] = {
        ["english"] = { [1] = "Ya man, you be wantin Jandi's Arboretum.  Did I just say that?  Glok'tar I must be tired!  Follow the wooden steps behind Asoran's Market in the Valley of Wisdom up into The Drag and you'll find Jandi's there on the upper level." },
        ["text"] = "Так, мон, тобі потрібен Дендрарій Джанді. Я справді це сказав? Ґлок'тар, мабуть, я втомився! Підіймайся дерев'яними сходами за ринком Асорана в Долині Мудрості до Хитрого провулка — Джанді буде там, на верхньому рівні.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [382236911] = {
        ["english"] = { [1] = "Turn the key to start the machine." },
        ["text"] = "Поверни ключ, щоб запустити машину.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3540283218] = {
        ["english"] = { [1] = "Ye have some skill about ye with hammer and anvil, but not enough. Go speak to Dane Lindgren, he'll get ye ready to learn what I have to teach ye." },
        ["text"] = "Дещо ти вмієш робити молотом і біля ковадла, але цього замало. Поговори з Дейном Ліндґреном — він підготує тебе до того, чого я можу навчити.",
        ["npcs"] = { [1] = 5511 },
        ["roles"] = { ["greeting"] = true },
    },
    [3438157858] = {
        ["english"] = { [1] = "Welcome to my shop, $c. What is it the Goodstitch brothers can do for you?" },
        ["text"] = "Ласкаво просимо до моєї крамниці, $c. Чим брати Добростібки можуть тобі допомогти?",
        ["npcs"] = { [1] = 2670 },
        ["roles"] = { ["greeting"] = true },
    },
    [1196975597] = {
        ["english"] = { [1] = "UDB Missing US text", [2] = "UDB missing US text" },
        ["text"] = "UDB: текст США відсутній",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1522242540] = {
        ["english"] = { [1] = "Tor'gash believes he can see the future in the entrails of birds, or by tossing the knucklebones of his ancestors. Really, all you need to do is ask the spirits. But don't try telling him that, $N. He's very stubborn." },
        ["text"] = "Тор'ґаш вірить, що бачить майбутнє в пташиних нутрощах або коли кидає кісточки пальців своїх предків. Насправді достатньо просто запитати духів. Але не намагайся йому це пояснити, $N. Він страшенно впертий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [889732640] = {
        ["english"] = { [1] = "Ye have my approval $N, ye can forge blades better than any I've trained in years. If ye want to make a real weapon though, ye need to talk with Myolor Sunderfury. That Dwarf will set ya on the right path." },
        ["text"] = "Маєш моє схвалення, $N: ти куєш клинки краще за всіх, кого я навчав за останні роки. Але якщо хочеш створити справжню зброю, поговори з Міолором Люторубом. Цей дворф направить тебе на правильний шлях.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4121502425] = {
        ["english"] = { [1] = "What do you know about the magical gates at the Sunwell Plateau being brought down?" },
        ["text"] = "Що ти знаєш про руйнування магічних брам на плато Сонячного Колодязя?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1261912572] = {
        ["english"] = { [1] = "We wouldn't have crashed if Hemet could learn how to avoid shooting through the ailerons when he's trying to bag game on the ground!$B$BNo worries though, I'll have her fixed up quick enough." },
        ["text"] = "Ми б не розбилися, якби Гемет навчився не стріляти крізь елерони, коли полює на дичину на землі!$B$BТа не хвилюйся, я швидко все полагоджу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [960306598] = {
        ["english"] = { [1] = "With Algernon to keep me supplied, I can do all my work here without hunting for a single herb. If I never have to see the wonders of nature again, it won't be too soon." },
        ["text"] = "Поки Алджернон постачає мені все потрібне, я можу виконувати всю роботу тут і не шукати жодної травинки. Якщо мені ніколи більше не доведеться бачити дива природи — буде не зарано.",
        ["npcs"] = { [1] = 4609 },
        ["roles"] = { ["greeting"] = true },
    },
    [859114595] = {
        ["english"] = { [1] = "Ye can probably hear Tognus beating away on the anvil when yer in Kharanos.  Although, if ye haven't cleared the wax out of yer ears recently, then why don't ye just have a look in the smithy." },
        ["text"] = "У Караносі, мабуть, і звідси чути, як Тоґнус гатить по ковадлу. А якщо давно не чистив віск із вух, просто зазирни до кузні.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2654703546] = {
        ["english"] = { [1] = "Well now $N, let's get to work on those cauldrons!  If you're going to collect the components we need, then get a vitreous focuser from me.  You'll need to have it on you to identify the necessary resources found on the Scourge that will turn those cauldrons.$B$BYou'll also need a dose of arcane quickener for the cauldrons.  It's not cheap, nor is it stable.  Once you have it, you'll only have thirty minutes to use it before it expires on you; be smart about buying it." },
        ["text"] = "Ну що, $N, час братися за ті котли! Якщо збираєшся добувати потрібні компоненти, візьми в мене склоподібний фокусатор. Він має бути при тобі, щоб розпізнавати необхідні ресурси на Скарі, які дозволять обернути ті котли проти них.$B$BТакож знадобиться доза арканічного прискорювача для котлів. Він недешевий і нестабільний. Після купівлі матимеш лише тридцять хвилин, щоб його використати, перш ніж він зіпсується; купуй із розумом.",
        ["npcs"] = { [1] = 11056, [2] = 11057 },
        ["roles"] = { ["greeting"] = true },
    },
    [419584606] = {
        ["english"] = { [1] = "We already have a winner for our contest, but Jang is willing to purchase any Tastyfish that you have fished up!\010\010There is always next Sunday for you to show your Angling skill!" },
        ["text"] = "У нашому змаганні вже є переможець, але Джанґ охоче купить будь-яку Смачну Рибу, яку тобі вдалося впіймати!\010\010Наступної неділі знову зможеш показати свою рибальську майстерність!",
        ["npcs"] = { [1] = 15077 },
        ["roles"] = { ["greeting"] = true },
    },
    [2143476346] = {
        ["english"] = { [1] = "What? You want to train under me, $c? You better be ready to work." },
        ["text"] = "Що? Хочеш тренуватися в мене, $c? Тоді будь готовий працювати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3489349812] = {
        ["english"] = { [1] = "Unbelievable! How dare they??" },
        ["text"] = "Неймовірно! Як вони посміли??",
        ["npcs"] = { [1] = 8879 },
        ["roles"] = { ["reply"] = true },
    },
    [799167212] = {
        ["english"] = { [1] = "Yaw Sharpmane awaits you on the north edge of the village.  He can teach you the ways of the Hunter." },
        ["text"] = "Яв Гострогривий чекає на північному краю селища. Він навчить тебе шляху мисливця.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [2468417297] = {
        ["english"] = { [1] = "What I offer to you now is one such blade, unfired, unheated, untreated - the most raw and basic form.$B$BNow you merely need to find a dragon that will willingly enchant the blade.$B$BIf you had an eternity to live, this might be a possibility; but since you are mortal and could very likely cease to exist at any moment, might I recommend trying to persuade one of the lesser dragons to do your bidding. " },
        ["text"] = "Тепер я пропоную тобі саме такий клинок — необпалений, ненагрітий, необроблений, у найсирішій і найпростішій формі.$B$BТепер тобі лише треба знайти дракона, який добровільно зачарує цей клинок.$B$BЯкби ти жив вічність, це могло б бути цілком реально; але ти смертний і будь-якої миті можеш припинити існування, тому раджу спробувати переконати когось із молодших драконів виконати твою волю. ",
        ["npcs"] = { [1] = 14368 },
        ["roles"] = { ["greeting"] = true },
    },
    [3939402297] = {
        ["english"] = { [1] = "We must ensure the survival of this camp at all costs, $c!  Our enemies must not be given any quarter, for they would surely give us none were we to need it." },
        ["text"] = "Ми маємо за будь-яку ціну забезпечити виживання цього табору, $c! Ворогові не можна давати пощади, адже вони точно не пощадили б нас, якби ми її потребували.",
        ["npcs"] = { [1] = 7875 },
        ["roles"] = { ["greeting"] = true },
    },
    [1924772593] = {
        ["english"] = { [1] = "While my brother, Drazial, focuses his analysis on the more physical nature of the beasts of the blasted lands, I tend to focus on the more cerebral and spiritual aspects of the wildlife.$B$BIt is true that the beasts exhibit extremely unusual strength, agility, and stamina, but some of them also possess great intelligence and regenerative abilities, untied to their physical being.$B$BPerhaps you would be interested in helping advance my research, $r?\010" },
        ["text"] = "Поки мій брат Дразіал зосереджує аналіз на фізичній природі звірів Спустошених земель, я більше вивчаю розумові й духовні аспекти місцевої фауни.$B$BПравда, звірі демонструють надзвичайну силу, спритність і витривалість, але деякі з них також мають великий інтелект і здібності до відновлення, не пов'язані з їхнім фізичним тілом.$B$BМожливо, тобі цікаво допомогти просунути мої дослідження, $r?\010",
        ["npcs"] = { [1] = 7506 },
        ["roles"] = { ["greeting"] = true },
    },
    [3334384754] = {
        ["english"] = { [1] = "We do not know.$B$BThe Dark Irons that did survive made their way into the mountain and began rebuilding their city.$B$BFrom the ashes of Thaurissan then rose Blackrock Spire and the new Dark Iron nation. Additional fortifications were made within the Searing Gorge, in the area known as the Cauldron.$B$BStories of an ancient evil that controlled the kingdom of Dark Irons began to circulate. " },
        ["text"] = "Ми не знаємо.$B$BТемні Залізні, яким вдалося вижити, пробралися в гору й почали відбудовувати своє місто.$B$BЗ попелу Тауріссана тоді постав Чорнокамінний Шпиль і нова держава Темного Заліза. Додаткові укріплення спорудили у Випаленій ущелині, в місці, відомому як Котел.$B$BПочали ширитися історії про прадавнє зло, що керувало королівством Темного Заліза. ",
        ["npcs"] = { [1] = 8879 },
        ["roles"] = { ["greeting"] = true },
    },
    [1477494489] = {
        ["english"] = { [1] = "Try to ignore the firm, feathery behinds of the harpies... the creatures are really quite deadly!" },
        ["text"] = "Спробуй не дивитися на пружні пір'ясті зади гарпій... ці створіння насправді дуже небезпечні!",
        ["npcs"] = { [1] = 3293 },
        ["roles"] = { ["greeting"] = true },
    },
    [3278571104] = {
        ["english"] = { [1] = "Yarp." },
        ["text"] = "Ага.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1638250757] = {
        ["english"] = { [1] = "What can you tell me about the nightsaber cat - Shadumbra?", [2] = "What can you tell me about the nightsaber cat - Shadumbra?\010" },
        ["text"] = "Що можеш розповісти про нічного шаблезуба Шадумбру?",
        ["npcs"] = { [1] = 12696 },
        ["roles"] = { ["reply"] = true },
    },
    [869727123] = {
        ["english"] = { [1] = "Ya mon, I be Gadrin's assistant.  Dis here volunteer work be my way of gettin through Witch Doctor School.  Since you help him, I help ya for free.  Whatcha need fixin?" },
        ["text"] = "Так, мон, я помічник Ґадріна. Ця волонтерська робота допомагає мені оплатити школу знахарів. Оскільки ти допомагаєш йому, я допоможу тобі безплатно. Що треба полагодити?",
        ["npcs"] = { [1] = 10578 },
        ["roles"] = { ["greeting"] = true },
    },
    [2581490518] = {
        ["english"] = { [1] = "Train me in the ways of herbalism." },
        ["text"] = "Навчи мене травництва.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1982269110] = {
        ["english"] = { [1] = "We already have control of Twin Spire Ruins! Get out there and defend it!" },
        ["text"] = "Ми вже контролюємо Руїни Двох Шпилів! Вирушай туди й захищай їх!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3943252116] = {
        ["english"] = { [1] = "What is Ysera and how were you blessed?" },
        ["text"] = "Хто така Ізера і як саме вона тебе благословила?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2665479844] = {
        ["english"] = { [1] = "Try these fireworks launchers.  They're a blast!" },
        ["text"] = "Спробуй ці пускові установки для феєрверків. Вибухова штука!",
        ["npcs"] = { [1] = 15694 },
        ["roles"] = { ["greeting"] = true },
    },
    [2297980394] = {
        ["english"] = { [1] = "To die in battle is glorious! But, with what I teach you, maybe you not die so quickly, hm?" },
        ["text"] = "Загинути в бою — славно! Але з тим, чого я тебе навчу, може, не загинеш так швидко, га?",
        ["npcs"] = { [1] = 11066 },
        ["roles"] = { ["greeting"] = true },
    },
    [2277055953] = {
        ["english"] = { [1] = "Why did you do this to us?" },
        ["text"] = "Навіщо ти зробив це з нами?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2467384881] = {
        ["english"] = { [1] = "Yah, I know, it be lookin' like we already have all of the mithril bars we be needin' for the war. But ya know, there still be plenty of folk 'round here that can probably be usin' your help right about now.  Thanks mon." },
        ["text"] = "Ага, знаю, схоже, ми вже маємо всі мітрилові зливки, потрібні для війни. Але тут іще повно народу, якому зараз може знадобитися твоя допомога. Дякую, мон.",
        ["npcs"] = { [1] = 15469 },
        ["roles"] = { ["greeting"] = true },
    },
    [3796088586] = {
        ["english"] = { [1] = "What do you need?" },
        ["text"] = "Що тобі потрібно?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3509704893] = {
        ["english"] = { [1] = "Ya may know a thing or two about handlin' animals, but have ya ever taken ta the skies? We Wildhammers know how ta ride the wind with the best of 'em. Fer a small fee, if ya've got the mettle, I'll train ya good and proper." },
        ["text"] = "Може, ти й дещо знаєш про поводження з тваринами, але чи здіймався колись у небо? Ми, Дикі Молоти, вміємо осідлати вітер краще за будь-кого. За невелику плату, якщо маєш відвагу, я навчу тебе як слід.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [291638017] = {
        ["english"] = { [1] = "Where is Elder Highpeak?" },
        ["text"] = "Де старійшина Високий Пік?",
        ["npcs"] = { [1] = 15561, [2] = 15594 },
        ["roles"] = { ["reply"] = true },
    },
    [761759714] = {
        ["english"] = { [1] = "Well my friend, ye have more skill than I do. Why don't ye go find me old friend Rotgath Stonebeard. He stayed in Ironforge when I left to join Jaina's army. I'm sure he'll be able ta teach ye somethin, or at least know someone who can. If he's still around, I'm sure he'll be at The Great Forge." },
        ["text"] = "Ну що ж, друже, ти вже вправніший за мене. Чому б не знайти мого старого друга Ротґата Кам'яноборода? Він залишився в Стальгорні, коли я пішов до армії Джайни. Упевнений, він зможе тебе чогось навчити або принаймні знає когось, хто зможе. Якщо він іще там, шукай його у Великій Кузні.",
        ["npcs"] = { [1] = 6299 },
        ["roles"] = { ["greeting"] = true },
    },
    [1481234592] = {
        ["english"] = { [1] = "Why don't you try looking in the Lion's Pride Inn?  The cook there might be able to teach you a few good recipes." },
        ["text"] = "Чому б не пошукати в таверні «Гордість Лева»? Тамтешній кухар, можливо, навчить кількох добрих рецептів.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [1034954945] = {
        ["english"] = { [1] = "Ya be havin' me gratitude, $c.$b$bIf there be anythin' I can be doin' fer yeh, just say so." },
        ["text"] = "Маєш мою вдячність, $c.$b$bЯкщо я можу щось для тебе зробити — тільки скажи.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2431412339] = {
        ["english"] = { [1] = "What are ye doin' here?! Get yer chatty self ta Alterac Vallery, where ye're needed!" },
        ["text"] = "Ти що тут робиш?! Забирай свою балакучу дупу до Альтерацької долини, там ти потрібен!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [35168853] = {
        ["english"] = { [1] = "Where is Elder Skygleam?" },
        ["text"] = "Де старійшина Небосвіт?",
        ["npcs"] = { [1] = 15595, [2] = 15598, [3] = 15603, [4] = 15605 },
        ["roles"] = { ["reply"] = true },
    },
    [1388428076] = {
        ["english"] = { [1] = "When I grow up, I wanna be the king of Stormwind!" },
        ["text"] = "Коли виросту, хочу стати королем Штормовію!",
        ["npcs"] = { [1] = 14305 },
        ["roles"] = { ["greeting"] = true },
    },
    [2934331928] = {
        ["english"] = { [1] = "Wushoolay, the Storm Witch.$B$BHer power is the power of the sky, the rain, and the shattered earth.  May she once again reign mother to the Gurubashi.$B$BWushoolay now rages near the edge of madness." },
        ["text"] = "Вушулай, Відьма Бурі.$B$BЇї сила — це сила неба, дощу й розколотої землі. Нехай вона знову стане матір'ю-правителькою Ґурубаші.$B$BТепер Вушулай шаленіє на межі божевілля.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4196828820] = {
        ["english"] = { [1] = "Wulan in Shadowprey Village can sell you the \"Expert Cookbook\".  You will need that if you are to better yourself." },
        ["text"] = "Вулан у селищі Тіньової Здобичі може продати тобі «Кулінарну книгу експерта». Вона знадобиться, якщо хочеш розвиватися далі.",
        ["npcs"] = { [1] = 1382, [2] = 2818, [3] = 3026, [4] = 3067, [5] = 3399, [6] = 4552, [7] = 8306 },
        ["roles"] = { ["greeting"] = true },
    },
    [3614568109] = {
        ["english"] = { [1] = "Through the valleys and peaks of Mount Hyjal, across the shifting sands of Silithus, against the Legion's dread armies - we have fought. We are the nameless, faceless, sons and daughters of the Alliance. By the Light and by the might of the Alliance, the first strike belongs to us and the last strike is all that our enemies see.$B$BWe are 7th Legion.$B" },
        ["text"] = "Через долини й вершини гори Гіджал, крізь мінливі піски Силітуса, проти жахливих армій Легіону — ми билися. Ми — безіменні, безликі сини й доньки Альянсу. Світлом і могуттю Альянсу перший удар завжди за нами, а останній — це все, що бачать наші вороги.$B$BМи — 7-й легіон.$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [649256321] = {
        ["english"] = { [1] = "Welcome to the headquarters of the Blood Knights, the defenders of Quel'Thalas, the faithful servants of Silvermoon, and the true masters of the Light." },
        ["text"] = "Ласкаво просимо до штабу Лицарів Крові — захисників Кель'Таласа, вірних слуг Срібномісяця й істинних володарів Світла.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1911559551] = {
        ["english"] = { [1] = "Very good $N.  You will find Grizzle Halfmane in the Royal Quarter of the Undercity.  May you find great honor in Alterac Valley." },
        ["text"] = "Дуже добре, $N. Ґріззла Напівгривого знайдеш у Королівському кварталі Підмістя. Нехай Альтерацька долина принесе тобі велику честь.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1660018174] = {
        ["english"] = { [1] = "Very well, but if I were you, I would pay attention and not just blindly nod my head at what I heard.$B$BIt begins, as all good stories do, with betrayal. Oh, it's not that we were betrayed... not at all. The Lich King raised us death knights above all others.$B$BRather, it was we who betrayed him with the help of Highlord Darion Mograine.$B$BIn the final fight at Light's Hope Chapel in the Plaguelands, with the simpletons moments away from annihilation, Tirion Fordring helped Mograine break the Lich King's hold upon him and all of the rest of us that were present." },
        ["text"] = "Гаразд, але на твоєму місці я б уважно слухав, а не просто бездумно кивав головою.$B$BПочинається все, як і кожна добра історія, зі зради. О, не нас зрадили... зовсім ні. Король-Ліч підніс нас, лицарів смерті, над усіма іншими.$B$BНасправді це ми зрадили його — за допомогою верховного лорда Даріона Моґрейна.$B$BУ фінальній битві біля каплиці Останньої Надії в Чумних землях, коли до знищення простаків лишалися лічені миті, Тіріон Фордрінґ допоміг Моґрейну розірвати владу Короля-Ліча над ним і над усіма нами, хто там був.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4155478340] = {
        ["english"] = { [1] = "We must take what is ours. Our survival depends on it." },
        ["text"] = "Ми повинні взяти те, що належить нам. Від цього залежить наше виживання.",
        ["npcs"] = { [1] = 2700 },
        ["roles"] = { ["greeting"] = true },
    },
    [4213115871] = {
        ["english"] = { [1] = "Wow, you're insane, aren't you?" },
        ["text"] = "Ого, ти ж божевільний, правда?",
        ["npcs"] = { [1] = 16131 },
        ["roles"] = { ["reply"] = true },
    },
    [1904746375] = {
        ["english"] = { [1] = "What is Cryptstalker armor?" },
        ["text"] = "Що таке обладунок Склепового Мисливця?",
        ["npcs"] = { [1] = 16132 },
        ["roles"] = { ["reply"] = true },
    },
    [315240381] = {
        ["english"] = { [1] = "What do you need directions to?" },
        ["text"] = "Куди тобі потрібні вказівки?",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1989440547] = {
        ["english"] = { [1] = "Woo Ping is the master of polearms. He trains his students at Weller's Arsenal in Stormwind." },
        ["text"] = "Ву Пін — майстер древкової зброї. Він навчає учнів у Арсеналі Веллера в Штормовії.",
        ["npcs"] = { [1] = 11865, [2] = 11866, [3] = 13084 },
        ["roles"] = { ["greeting"] = true },
    },
    [1354082869] = {
        ["english"] = { [1] = "What do you know about the Cult of the Damned?" },
        ["text"] = "Що ти знаєш про Культ Проклятих?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2888951273] = {
        ["english"] = { [1] = "Wow!  These kegs are filled with powerful stuff!  They lift me right out of my boots!" },
        ["text"] = "Ого! У цих кегах дуже міцне пійло! Воно просто піднімає мене з чобіт!",
        ["npcs"] = { [1] = 15723 },
        ["roles"] = { ["greeting"] = true },
    },
    [1259684992] = {
        ["english"] = { [1] = "Wow! Looks like we already gathered all of the thick leather they think we'll need. That sure went by fast. You know, there are probably others around here that could use your help though if ya want to give 'em a hand." },
        ["text"] = "Ого! Схоже, ми вже зібрали всю товсту шкіру, яка, за розрахунками, нам потрібна. Швидко впоралися. Але тут, мабуть, є інші, кому ще не завадить твоя допомога, якщо хочеш підсобити.",
        ["npcs"] = { [1] = 15450 },
        ["roles"] = { ["greeting"] = true },
    },
    [3970072897] = {
        ["english"] = { [1] = "Walk always in the Light, $N." },
        ["text"] = "Завжди ступай у Світлі, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1632820229] = {
        ["english"] = { [1] = "Would you rather trust your goods with a goblin?" },
        ["text"] = "Ти справді радше довіриш свої товари гобліну?",
        ["npcs"] = { [1] = 3309, [2] = 3318, [3] = 3320 },
        ["roles"] = { ["greeting"] = true },
    },
    [1537808819] = {
        ["english"] = { [1] = "Winterhoof? I hear he's living it up in Booty Bay." },
        ["text"] = "Зимове Копито? Чув, він розкошує в Бухті Наживи.",
        ["npcs"] = { [1] = 15557, [2] = 15577, [3] = 15593, [4] = 15596 },
        ["roles"] = { ["greeting"] = true },
    },
    [4270953041] = {
        ["english"] = { [1] = "Would you like a flight to Thunder Bluff, courtesy of the Cenarion Circle?" },
        ["text"] = "Хочеш полетіти до Громового Бескиду коштом Кенарієвого Кола?",
        ["npcs"] = { [1] = 11798 },
        ["roles"] = { ["greeting"] = true },
    },
    [1706252672] = {
        ["english"] = { [1] = "We feel nothing. Our souls remain here, in limbo. We are unable to leave until our remains are found and spirits laid to rest." },
        ["text"] = "Ми нічого не відчуваємо. Наші душі лишилися тут, у забутті. Ми не можемо піти, доки не знайдуть наші останки й не упокоять духи.",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["greeting"] = true },
    },
    [3507188931] = {
        ["english"] = { [1] = "We're pretty far from anything I'd call civilization here, at least until the Horde can send us more reinforcements. You must really like working with leather." },
        ["text"] = "До всього, що я назвав би цивілізацією, звідси далеченько — принаймні доки Орда не надішле більше підкріплень. Схоже, тобі справді подобається працювати зі шкірою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2686187443] = {
        ["english"] = { [1] = "Welcome to the Falconwing Square Inn. May I prepare a meal for you, or ready a room?" },
        ["text"] = "Ласкаво просимо до таверни на площі Соколиного Крила. Приготувати для тебе їжу чи підготувати кімнату?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2540915511] = {
        ["english"] = { [1] = "With you and your people as allies, we have decided to stay on this island and rebuild. Elune bless you, hero.$B$BWhile the sadness still comes and goes, I think we will survive.$B" },
        ["text"] = "З вами та вашим народом як союзниками ми вирішили залишитися на цьому острові й відбудуватися. Нехай Елуна благословить тебе, герою.$B$BСмуток іще часом повертається, але, думаю, ми виживемо.$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1893564152] = {
        ["english"] = { [1] = "What are love tokens?" },
        ["text"] = "Що таке знаки кохання?",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [1309006432] = {
        ["english"] = { [1] = "We really must perfect a way to deal with those smelly Shadowpine trolls!" },
        ["text"] = "Нам справді треба нарешті придумати, як упоратися з тими смердючими тролями Тіньової Сосни!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1157350775] = {
        ["english"] = { [1] = "Would a tauren paladin be a holy cow?" },
        ["text"] = "Чи був би таурен-паладин священною коровою?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [567775416] = {
        ["english"] = { [1] = "We have all the copper bars that we need. Thank you for your assistance, $c. You might wanna help out with the other materials being collected here." },
        ["text"] = "У нас уже є всі потрібні мідні зливки. Дякую за допомогу, $c. Можеш допомогти з іншими матеріалами, які тут збирають.",
        ["npcs"] = { [1] = 15383 },
        ["roles"] = { ["greeting"] = true },
    },
    [1625337472] = {
        ["english"] = { [1] = "Well, looks like we have all of the cooked albacore that we can properly salt and store for the upcoming war at Ahn'Qiraj. Thanks for asking though, $c. If you have a mind to, check around with the other collectors. I'd bet there's someone else here that could use your help with gathering up whatever it is that they need." },
        ["text"] = "Схоже, ми вже маємо стільки приготовленого альбакора, скільки можемо правильно засолити й зберегти для майбутньої війни за Ан'Кіраж. Але дякую, що спитав, $c. Якщо хочеш допомогти, пройдися до інших збирачів. Готовий посперечатися, тут знайдеться хтось, кому ще потрібна допомога зі збором.",
        ["npcs"] = { [1] = 15455 },
        ["roles"] = { ["greeting"] = true },
    },
    [1479882773] = {
        ["english"] = { [1] = "Wot kin I do fer ye?" },
        ["text"] = "Чим можу допомогти?",
        ["npcs"] = { [1] = 895, [2] = 1231, [3] = 5115, [4] = 5117, [5] = 10930 },
        ["roles"] = { ["greeting"] = true },
    },
    [2674910127] = {
        ["english"] = { [1] = "Working with this technology is a huge headache.  Everything is constructed in such an alien way." },
        ["text"] = "Працювати з цією технологією — страшенний головний біль. Усе сконструйовано таким чужим способом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4222990225] = {
        ["english"] = { [1] = "We have auction house in central ring." },
        ["text"] = "Аукціонний дім у центральному кільці.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [1939646042] = {
        ["english"] = { [1] = "What are you staring at, $r?" },
        ["text"] = "Чого витріщився, $r?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2247488226] = {
        ["english"] = { [1] = "Who is Malygos?" },
        ["text"] = "Хто такий Маліґос?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [568540627] = {
        ["english"] = { [1] = "Us want felhound for pet.  We feed it and treat it good and teach it play fetch.  You find Warlocks in Magic Quarter on outer ring of city." },
        ["text"] = "Ми хочемо скверногончака за вихованця. Будемо годувати, добре доглядати й навчимо приносити паличку. Чорнокнижників знайдеш у Кварталі Магії, в будівлі на зовнішньому кільці міста.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [1604668787] = {
        ["english"] = { [1] = "We suspect that in order to preserve their fortune and hold of the land - well past their lifespan - the Barovs made a deal with a powerful human mage named Kel'Thuzad.$B$B<Eva shudders.>$B$BFrom this deal sprang the school of necromancy: A place which bore the Cult of the Damned and would become their capital.$B$BAs each week passed, the house Barov became more and more decrepit...$B$BDark beings began to take residence in the various wings of the house. Upkeep became impossible... and disgusting." },
        ["text"] = "Ми підозрюємо, що заради збереження свого багатства й влади над землями навіть після смерті Барови уклали угоду з могутнім людським магом на ім'я Кел'Тузад.$B$B<Єва здригається.>$B$BІз цієї угоди народилася школа некромантії — місце, що породило Культ Проклятих і згодом стало його столицею.$B$BЗ кожним тижнем дім Барових занепадав дедалі більше...$B$BУ різних крилах оселі почали селитися темні створіння. Підтримувати маєток стало неможливо... й огидно.",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["greeting"] = true },
    },
    [1109962356] = {
        ["english"] = { [1] = "Well, from what I've gathered while waiting to be eaten by these yokels... it might not be necessary to kill every ogre you find here.$B$BThe ogres were going on and on the other day about how King Gordok came to power; specifically, he killed the previous king and took his place.  Well, the king's henchmen - those that Gordok spared - immediately swore fealty to the new king.$B$BWho knows - the ogre you save could very well be your own... figuratively speaking, of course!" },
        ["text"] = "Ну, з того, що я встиг з'ясувати, поки ці йолопи готувалися мене з'їсти... можливо, зовсім не обов'язково вбивати кожного огра тут.$B$BНещодавно огри без кінця говорили про те, як король Ґордок прийшов до влади; точніше, він убив попереднього короля й зайняв його місце. І слуги старого короля — ті, кого Ґордок пощадив, — одразу присягнули новому.$B$BХтозна — огр, якого ти врятуєш, цілком може стати твоїм власним... образно кажучи, звісно!",
        ["npcs"] = { [1] = 14338 },
        ["roles"] = { ["greeting"] = true },
    },
    [1310250412] = {
        ["english"] = { [1] = "Where is your Medallion of Station, little one?  You may not speak with a Duke without proof of title..." },
        ["text"] = "Де твій Медальйон Становища, малий? Без доказу титулу не можна говорити з герцогом...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1799795810] = {
        ["english"] = { [1] = "Would a fly without wings be called a walk?" },
        ["text"] = "Чи називали б муху без крил ходою?",
        ["npcs"] = { [1] = 14444 },
        ["roles"] = { ["greeting"] = true },
    },
    [861260030] = {
        ["english"] = { [1] = "Word is that Vance Undergloom has taken a permanent room upstairs at the Gallows' End Tavern at the southeast end of town.  I think he's just off the reading room." },
        ["text"] = "Кажуть, Венс Підморок назавжди оселився в кімнаті нагорі в таверні «Кінець Шибениці» на південно-східному краю міста. Здається, це одразу за читальною залою.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [2074251367] = {
        ["english"] = { [1] = "Unless?" },
        ["text"] = "Хіба що?",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["reply"] = true },
    },
    [814337867] = {
        ["english"] = { [1] = "We chose to leave the protection and comfort of the Depths to exploit... er, I mean... hrm, yes that's right, EXPLORE the world." },
        ["text"] = "Ми вирішили покинути захист і затишок Глибин, щоб експлуатувати... е-е, тобто... кхм, саме так, ДОСЛІДЖУВАТИ світ.",
        ["npcs"] = { [1] = 14628 },
        ["roles"] = { ["greeting"] = true },
    },
    [1615625124] = {
        ["english"] = { [1] = "Whirlaxis!  I hold your scepter!  I command you to enter this world!" },
        ["text"] = "Вірлаксисе! Я тримаю твій скіпетр! Наказую тобі увійти в цей світ!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1904311921] = {
        ["english"] = { [1] = "Word got back to me through channels concerning Lady Sylvanas's reaction to you and the recovery of her necklace. I still think you did the right thing; don't worry too much about how the lady reacted.$B$BNow, state your business." },
        ["text"] = "До мене дійшли чутки каналами про реакцію Пані Сильвани на тебе й повернення її намиста. Я досі вважаю, що ти вчинив правильно; не переймайся надто через її реакцію.$B$BА тепер кажи, чого прийшов.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3151018205] = {
        ["english"] = { [1] = "Well met, $c.  My advice to you is this: as you travel the world, be wary of magic for it will burn the untrained." },
        ["text"] = "Вітаю, $c. Моя порада така: мандруючи світом, остерігайся магії — непідготовленого вона спалить.",
        ["npcs"] = { [1] = 198, [2] = 328, [3] = 331, [4] = 2124, [5] = 2128, [6] = 3047, [7] = 3048, [8] = 3049, [9] = 4566, [10] = 4567, [11] = 4568, [12] = 5497, [13] = 5498 },
        ["roles"] = { ["greeting"] = true },
    },
    [2858465781] = {
        ["english"] = { [1] = "Two words: Arcanite buoy." },
        ["text"] = "Два слова: арканітовий буй.",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [3921160209] = {
        ["english"] = { [1] = "Woohoo! They are into it now!" },
        ["text"] = "Уу-ху! Тепер вони по-справжньому взялися!",
        ["npcs"] = { [1] = 14395 },
        ["roles"] = { ["greeting"] = true },
    },
    [3018592904] = {
        ["english"] = { [1] = "We don't get many visitors out here. May I interest you in something?" },
        ["text"] = "Тут у нас нечасто бувають гості. Може, щось тебе зацікавить?",
        ["npcs"] = { [1] = 11048 },
        ["roles"] = { ["greeting"] = true },
    },
    [434962902] = {
        ["english"] = { [1] = "Woo Ping's stamina is simply astounding.  Watching him practice his weapon techniques for hours on end, I felt sorry for the practice dummy afterward.  I can't think of anyone better suited to train you in armed combat." },
        ["text"] = "Витривалість Ву Піна просто вражає. Після того як я годинами спостерігав за його тренуваннями зі зброєю, мені стало шкода тренувального манекена. Не можу уявити нікого кращого для навчання збройного бою.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2822367184] = {
        ["english"] = { [1] = "What? Bonescythe?" },
        ["text"] = "Що? Кісткоріз?",
        ["npcs"] = { [1] = 16131 },
        ["roles"] = { ["reply"] = true },
    },
    [995699408] = {
        ["english"] = { [1] = "Touch the Suntara stone and call forth Lathoric the Black and his guardian, Obsidion." },
        ["text"] = "Торкнися каменя Сунтари й приклич Латоріка Чорного та його вартового Обсидіона.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3323636163] = {
        ["english"] = { [1] = "We are lucky to have survived this ordeal. If it wasn't for you, everyone on this island could have been killed!" },
        ["text"] = "Нам пощастило пережити це випробування. Якби не ти, усі на цьому острові могли б загинути!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [349293722] = {
        ["english"] = { [1] = "Woo hoo, here we go! Everyone's collected everything, and it's all being airlifted via zeppelin to Silithus as we speak. The last of it should be there in less than a day. Once it's all over there, and the scepter has been assembled, the war against those dirty insects can begin. As they say, 'Ship It!'" },
        ["text"] = "Уу-ху, почалося! Усі все зібрали, й просто зараз вантажі дирижаблями перевозять до Силітуса. Останні мають прибути менш ніж за день. Коли все буде там і скіпетр зберуть, можна починати війну проти тих брудних комах. Як кажуть: «Відправляй!»",
        ["npcs"] = { [1] = 15431 },
        ["roles"] = { ["greeting"] = true },
    },
    [2267766152] = {
        ["english"] = { [1] = "Welcome, $N. Bring me the marks that Illidan bestows upon his most powerful minions and I shall grant you access to my alchemical goods." },
        ["text"] = "Ласкаво просимо, $N. Принеси мені знаки, якими Іллідан нагороджує своїх наймогутніших прислужників, і я відкрию тобі доступ до моїх алхімічних товарів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [732775113] = {
        ["english"] = { [1] = "Welcome to Revantusk Village, stranger. I am Primal Torntusk, leader of the Revantusk trolls." },
        ["text"] = "Ласкаво просимо до селища Зловісного Бивня, незнайомцю. Я Первісний Торнтуск, ватажок тролів Зловісного Бивня.",
        ["npcs"] = { [1] = 14736 },
        ["roles"] = { ["greeting"] = true },
    },
    [2078992889] = {
        ["english"] = { [1] = "Woo hoo, here we go! Everyone's collected everything, and it's all being airlifted via zeppelin to Silithus as we speak. The last of it should be there in less than $2113w days. Once it's all over there, and the scepter has been assembled, the war against those dirty insects can begin. As they say, 'Ship It!'\009" },
        ["text"] = "Уу-ху, почалося! Усі все зібрали, й просто зараз вантажі дирижаблями перевозять до Силітуса. Останні мають прибути менш ніж за $2113w днів. Коли все буде там і скіпетр зберуть, можна починати війну проти тих брудних комах. Як кажуть: «Відправляй!»\009",
        ["npcs"] = { [1] = 15431 },
        ["roles"] = { ["greeting"] = true },
    },
    [402604530] = {
        ["english"] = { [1] = "Won't be long now until the Darkmoon Faire opens.  Come back later and check to see if we're done." },
        ["text"] = "До відкриття ярмарку Темного Місяця вже недовго. Зайди пізніше й перевір, чи ми закінчили.",
        ["npcs"] = { [1] = 14843, [2] = 14849 },
        ["roles"] = { ["greeting"] = true },
    },
    [1292873754] = {
        ["english"] = { [1] = "What have you heard of the Shady Rest Inn?" },
        ["text"] = "Що ти чув про таверну «Тінистий Притулок»?",
        ["npcs"] = { [1] = 4944 },
        ["roles"] = { ["reply"] = true },
    },
    [3819951425] = {
        ["english"] = { [1] = "Woah, woah, woah! Keep it down, $N. Keep it down!$B$B<Blast looks around.>$B$BWe don't want those frosty vrykul noticing us, now do we?$B$BWhat do you think of my jumpbot? I based it off of the mechagnome. Pretty slick, huh?" },
        ["text"] = "Ого, ого, ого! Тихіше, $N. Тихіше!$B$B<Бласт озирається.>$B$BМи ж не хочемо, щоб ті морозні врікули нас помітили, правда?$B$BЯк тобі мій стрибобот? Я взяв за основу механогнома. Крута штука, еге ж?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3747554072] = {
        ["english"] = { [1] = "To avenge my people, to drive out the blight that has engulfed our land - I will take your oath. I will pledge all that I have and all that I am to the Horde." },
        ["text"] = "Щоб помститися за свій народ і вигнати пошесть, що поглинула нашу землю, я прийму твою присягу. Я віддам Орді все, що маю, і все, ким я є.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3133807269] = {
        ["english"] = { [1] = "What have you got there, $N?$B$B<Malyfous points to the unfired plate gauntlets hanging out of your pack.>" },
        ["text"] = "Що це в тебе там, $N?$B$B<Маліфус вказує на необпалені латні рукавиці, що стирчать із твоєї сумки.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2813803663] = {
        ["english"] = { [1] = "What now?  Can't you see I'm rather busy?" },
        ["text"] = "Що тепер? Не бачиш, я доволі зайнятий?",
        ["npcs"] = { [1] = 16032 },
        ["roles"] = { ["greeting"] = true },
    },
    [3857457011] = {
        ["english"] = { [1] = "Yeah, that would be Austil de Mon.  He's always hanging out in the tavern at the southeast end of town.  It's called the Gallows' End Tavern, you can't miss it." },
        ["text"] = "Так, це буде Остіл де Мон. Він завжди стирчить у таверні на південно-східному краю міста. Називається «Кінець Шибениці» — не проминеш.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [1665195633] = {
        ["english"] = { [1] = "Who is this Terokk you keep mentioning?" },
        ["text"] = "Хто цей Терокк, якого ти постійно згадуєш?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1742411773] = {
        ["english"] = { [1] = "We have to kill more trolls!  Kill enough and I'll blow the door to the troll chief!" },
        ["text"] = "Треба вбити ще більше тролів! Убий достатньо — і я підірву двері до їхнього ватажка!",
        ["npcs"] = { [1] = 7607 },
        ["roles"] = { ["greeting"] = true },
    },
    [487178399] = {
        ["english"] = { [1] = "Uhnhh.... Don't... bother with me.$b$bI am... finished...." },
        ["text"] = "У-у-у.... Не... зважай на мене.$b$bМені... кінець....",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [536567817] = {
        ["english"] = { [1] = "We are the last of the furbolg race... The Timbermaw tribe remains uncorrupted, yet we face the same hostility from outsiders; most believe that it is not possible... that there could actually be furbolg that escaped the corruption...$B$BAngry at those that strive to make enemies too quickly, my brethren now attack any that draw near; they trust no one.$B$BBut perhaps, if you strive to make your presence peaceful with them, they might look upon you as an ally." },
        ["text"] = "Ми — останні з фурболґів... Плем'я Деревної Пащі лишилося неоскверненим, та чужинці ставляться до нас із тією ж ворожістю; більшість не вірить, що це можливо... що бодай якісь фурболґи могли уникнути скверни...$B$BРозгнівані на тих, хто надто швидко робить із інших ворогів, мої брати тепер нападають на кожного, хто наближається; вони нікому не довіряють.$B$BАле, можливо, якщо ти покажеш їм мирні наміри, вони визнають у тобі союзника.",
        ["npcs"] = { [1] = 11554 },
        ["roles"] = { ["greeting"] = true },
    },
    [3554572291] = {
        ["english"] = { [1] = "We don't know much about the burning of the Shady Rest Inn, except that James Hyal's wife and child were unable to escape.$b$bWe managed to drag James out, but he hasn't been the same since.$b$bWe have many leads but not much evidence. It is our hope that through the efforts of the guard and the vigilant help of the people of Theramore, we will unravel this terrible crime.$b$bIf you would like to lend assistance to the investigation, what remains of the inn can be found at the border to the Barrens." },
        ["text"] = "Ми мало знаємо про пожежу в таверні «Тінистий Притулок», окрім того, що дружина й дитина Джеймса Гіала не змогли врятуватися.$b$bНам вдалося витягти Джеймса, але відтоді він сам не свій.$b$bУ нас багато зачіпок, та мало доказів. Сподіваємося, що завдяки зусиллям варти й пильній допомозі мешканців Терамора ми розкриємо цей жахливий злочин.$b$bЯкщо хочеш допомогти розслідуванню, рештки таверни знайдеш на кордоні зі Степами.",
        ["npcs"] = { [1] = 4944 },
        ["roles"] = { ["greeting"] = true },
    },
    [1923056087] = {
        ["english"] = { [1] = "Yeah yeah, I know Dadanga dislikes smoke.  From the smell of it though, seems like Dadanga also dislikes bathing." },
        ["text"] = "Ага-ага, знаю, Даданґа не любить диму. Але, судячи із запаху, Даданґа ще й купатися не любить.",
        ["npcs"] = { [1] = 9272 },
        ["roles"] = { ["greeting"] = true },
    },
    [3224196489] = {
        ["english"] = { [1] = "Would you like a flight to Rut'theran Village, courtesy of the Cenarion Circle?" },
        ["text"] = "Хочеш полетіти до селища Рут'теран коштом Кенарієвого Кола?",
        ["npcs"] = { [1] = 11800 },
        ["roles"] = { ["greeting"] = true },
    },
    [3474443974] = {
        ["english"] = { [1] = "With the Warsong Offensive here in Icecrown Citadel, victory is within our grasp! The death of the Lich King will bring glory to the Horde!" },
        ["text"] = "Коли Наступ Пісні Війни вже тут, у Цитаделі Крижаної Корони, перемога в наших руках! Смерть Короля-Ліча принесе славу Орді!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1379987604] = {
        ["english"] = { [1] = "With the sanction of Lord Varimathras, the Deathstalkers' numbers grow. More blades to strike at our enemies when they least expect it." },
        ["text"] = "З дозволу лорда Варіматраса ряди Смертоловів ростуть. Більше клинків ударять ворогів тоді, коли ті найменше цього чекають.",
        ["npcs"] = { [1] = 2122, [2] = 2130, [3] = 4582, [4] = 4583, [5] = 4584, [6] = 6566 },
        ["roles"] = { ["greeting"] = true },
    },
    [2684220653] = {
        ["english"] = { [1] = "With the Light's blessing and your help, $N, the Defias are no longer a threat.$B$BBut we're a long way from Westfall up here, and if we don't win this battle, there may not be a home to return to." },
        ["text"] = "З благословенням Світла й твоєю допомогою, $N, Непокірні більше не загроза.$B$BАле ми далеко від Західного краю, і якщо не виграємо цю битву, може не залишитися дому, куди повертатися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3191825704] = {
        ["english"] = { [1] = "Um, I'm taking some prisoners we found outside before the king for punishment." },
        ["text"] = "Ем, я веду до короля кількох полонених, яких ми знайшли зовні, щоб він їх покарав.",
        ["npcs"] = { [1] = 14325 },
        ["roles"] = { ["reply"] = true },
    },
    [4164947294] = {
        ["english"] = { [1] = "What are ye daft? That's not a weapon, that's a dinner knife. I don't train amateurs." },
        ["text"] = "Ти що, здурів? Це не зброя, а столовий ніж. Я не навчаю дилетантів.",
        ["npcs"] = { [1] = 7232 },
        ["roles"] = { ["greeting"] = true },
    },
    [553242726] = {
        ["english"] = { [1] = "Well, maybe 'pay' isn't the best word to use. See, when I was stuck in the belly of that thing, I got to thinking:$B$BThis creature lives in hot, flaming magma and yet it doesn't take a lick of damage from the fire!$B$BIf only I could find a pristine hide from one of these beasts. I could take it back to my dear friend, Malyfous Darkhammer, in Everlook. If anyone could do anything with the hide of a beast like this, it would be him. \010" },
        ["text"] = "Ну, можливо, слово «платня» тут не найкраще. Розумієш, коли я застряг у череві тієї тварюки, то задумався:$B$BЦе створіння живе в гарячій палаючій магмі, але вогонь зовсім не завдає йому шкоди!$B$BЯкби тільки мені вдалося знайти бездоганну шкуру одного з цих звірів. Я міг би віднести її своєму дорогому другові Маліфусу Темному Молоту в Завшегляді. Якщо хтось і здатен щось зробити зі шкурою такого звіра, то саме він. \010",
        ["npcs"] = { [1] = 10776 },
        ["roles"] = { ["greeting"] = true },
    },
    [2411336202] = {
        ["english"] = { [1] = "With the Lich King fleeing in fear of Fordring armed with the Ashbringer, we were able to easily wrest Ebon Hold from the remaining Scourge forces.$B$BThat didn't settle things between us and the Scarlet Crusade, however.$B$BAs the Forsaken have learned the hard way, the Scarlets cannot seem to differentiate between us and the Scourge.$B$BWe think on our own, we have our own motivations, we have almost all of the qualities of the living, and yet to them, we are no different than the mindless slaves of the Lich King.$B$BMistakenly they think we will roll over and play dead." },
        ["text"] = "Коли Король-Ліч у страху втік від Фордрінґа, озброєного Спопелителем, ми легко відбили Чорну фортецю в решти сил Скари.$B$BОднак це не владнало справи між нами й Багряним Походом.$B$BЯк Відречені вже болісно зрозуміли, багряні просто не здатні відрізнити нас від Скари.$B$BМи думаємо самостійно, маємо власні мотиви, зберегли майже всі якості живих, а для них усе одно нічим не відрізняємося від бездумних рабів Короля-Ліча.$B$BВони помилково думають, що ми просто ляжемо й удаватимемо мертвих.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [365340134] = {
        ["english"] = { [1] = "Time to relax, the Alliance be way behind us mon. We all done with our collectin' here, and the final polishes be goin' on things as we speak. When they get done over in their Ironforge, then we be thinkin' 'bout movin' all this stuff to Silithus. 'Til then, sit tight and maybe do some fishin'." },
        ["text"] = "Час відпочити, Альянс далеко позаду, мон. Ми тут уже все позбирали, і останні штрихи саме доробляють. Коли вони там у Стальгорні завершать, тоді й подумаємо, як перевезти все це в Силітус. А доти сиди тихо та, може, порибаль.",
        ["npcs"] = { [1] = 15534 },
        ["roles"] = { ["greeting"] = true },
    },
    [4294877244] = {
        ["english"] = { [1] = "With the help of our new taunka allies, the Northrend will belong to the Horde." },
        ["text"] = "З допомогою наших нових союзників-таунка Нортренд належатиме Орді.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1010283325] = {
        ["english"] = { [1] = "We must not allow the Alliance to expand their power base in Arathi!  Even their miniscule Refuge Pointe may one day grow to threaten us." },
        ["text"] = "Не можна дозволити Альянсу розширити свою опору в Араті! Навіть їхній крихітний Притулок одного дня може вирости й стати загрозою для нас.",
        ["npcs"] = { [1] = 15021 },
        ["roles"] = { ["greeting"] = true },
    },
    [2088232748] = {
        ["english"] = { [1] = "Why do you keep saying he died? Who told you he died? I never said he died.$B$BHe went missing is all.$B$BYou see, apparently we had gotten into the middle of some big orc versus Dark Iron dwarf battle. The orcs, being the filthy, miserable curs that they are, were out early, setting up some traps and other diabolical things you probably wouldn't understand." },
        ["text"] = "Чому ти весь час кажеш, що він помер? Хто сказав тобі, що він помер? Я ніколи не казав, що він помер.$B$BВін просто зник.$B$BРозумієш, схоже, ми опинилися посеред великої битви між орками й дворфами Темного Заліза. Орки, брудні жалюгідні пси, якими вони є, вийшли рано й розставляли пастки та інші диявольські штуки, яких ти, мабуть, не зрозумієш.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["greeting"] = true },
    },
    [1700780706] = {
        ["english"] = { [1] = "We have won $2219W battles against the Scourge.  Take heart, $N.  While many battles lie ahead, heroes, heroes from every realm have risen to fight them." },
        ["text"] = "Ми виграли $2219W битв проти Скари. Не падай духом, $N. Попереду ще багато боїв, та герої — герої з кожного світу — вже піднялися, щоб стати до них.",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["greeting"] = true },
    },
    [1261205919] = {
        ["english"] = { [1] = "With the garments that Me'Lynn tailors, one might think that her needle was blessed by Elune herself.  Unless your needle is so blessed, you best pay her a visit and listen to her teachings.  You can find her in The Craftsmen's Terrace in northeastern Darnassus." },
        ["text"] = "Поглянувши на вбрання, які шиє Ме'Лінн, можна подумати, що її голку благословила сама Елуна. Якщо твоя голка не має такого благословення, краще навідайся до неї й послухай настанови. Знайдеш її на Терасі Ремісників у північно-східному Дарнасі.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [2137529857] = {
        ["english"] = { [1] = "With the Emperors slain, the magical protection blocking teleportation within the temple has been greatly weakened. If you desire, I am able to translocate you to the Emperors' lair." },
        ["text"] = "Імператорів убито, тож магічний захист, який блокував телепортацію всередині храму, значно ослаб. Якщо бажаєш, я можу перенести тебе до лігва Імператорів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [996020664] = {
        ["english"] = { [1] = "What is it that you want, $r?" },
        ["text"] = "Чого тобі треба, $r?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4286802973] = {
        ["english"] = { [1] = "Uldaman" },
        ["text"] = "Ульдаман",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [43174457] = {
        ["english"] = { [1] = "With the Earth Mother's blessing, we shall begin." },
        ["text"] = "З благословення Матері-Землі — почнімо.",
        ["npcs"] = { [1] = 11051 },
        ["roles"] = { ["greeting"] = true },
    },
    [1538292843] = {
        ["english"] = { [1] = "Welcome to Stormwind!  I am one of the city's officers, aiding the citizenry of the city through our census bureau.  If you are in need of locating someone specific, then I might be able to assist you.  Through arcane methods and sharpened mental discipline, I am able to access these records.$B$BIf you have business with me, then please proceed!" },
        ["text"] = "Ласкаво просимо до Штормовію! Я один із міських урядовців і допомагаю мешканцям через наше бюро перепису. Якщо тобі треба знайти когось конкретного, можливо, я зможу допомогти. За допомогою арканічних методів і загостреної дисципліни розуму я маю доступ до цих записів.$B$BЯкщо маєш до мене справу — кажи!",
        ["npcs"] = { [1] = 10782 },
        ["roles"] = { ["greeting"] = true },
    },
    [3253238197] = {
        ["english"] = { [1] = "With the cauldrons breeched, we are now able to introduce the counter agent into the environment.  This should give the scourge a taste of their own medicine, as it were!$B$BCheck with Alchemist Arbington on information regarding the reagents needed to use in the cauldrons.  I will be handling all information reports on how we are doing overall in turning the plague against the Scourge!" },
        ["text"] = "Котли пробито, тож тепер ми можемо ввести протидійний реагент у довкілля. Нехай Скара скуштує власних ліків!$B$BЗапитай алхіміка Арбінґтона про реагенти, потрібні для котлів. Я збиратиму всі звіти про наш загальний успіх у поверненні чуми проти Скари!",
        ["npcs"] = { [1] = 11053 },
        ["roles"] = { ["greeting"] = true },
    },
    [151291718] = {
        ["english"] = { [1] = "Unexpected that you are all capable of such organization. Both the Alliance and the Horde have completed their preparations for the Ahn'Qiraj War. Even as we speak the materiel is being shipped over to Silithus and should all arrive within a day. Then it is up to the one who is going to reassemble the Scepter of the Shifting Sands to beat on the gong at the Scarab Dais and open the gates of Ahn'Qiraj. That is when the war will truly begin!" },
        ["text"] = "Неочікувано, що ви всі здатні на таку організацію. І Альянс, і Орда завершили приготування до війни за Ан'Кіраж. Просто зараз припаси перевозять до Силітуса, і всі вони мають прибути протягом дня. Далі все залежатиме від того, хто збере докупи Скіпетр Мінливих Пісків, ударить у гонг на Помості Скарабея й відчинить брами Ан'Кіражу. От тоді війна почнеться по-справжньому!",
        ["npcs"] = { [1] = 15539 },
        ["roles"] = { ["greeting"] = true },
    },
    [3362573347] = {
        ["english"] = { [1] = "Whoa now, $c, Pele'keiki thinkin' that you not knowin' all that stuff be on its way to Silithus. Pele'keiki told the last of it be getting' there in less than a day, and after that some misguided fool gonna ring the gong outside the Ahn'Qiraj gates to open 'em up and be startin' the war." },
        ["text"] = "Ого, $c, Пеле'кейкі думає, що ти не знаєш: усе те добро вже везуть до Силітуса. Пеле'кейкі сказали, що останнє прибуде менш ніж за день, а потім якийсь заблудлий дурень вдарить у гонг біля брам Ан'Кіражу, відчинить їх і почне війну.",
        ["npcs"] = { [1] = 15508 },
        ["roles"] = { ["greeting"] = true },
    },
    [1472925880] = {
        ["english"] = { [1] = "Us starting ta like little $N!  Yous bashem da demons real good!" },
        ["text"] = "Нам уже починає подобатися малий $N! Ти добре гамселиш демонів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3610142858] = {
        ["english"] = { [1] = "With pleasure... just let me savor this moment for a minute longer." },
        ["text"] = "Із задоволенням... тільки дозволь ще хвилину насолодитися цією миттю.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["greeting"] = true },
    },
    [3008399778] = {
        ["english"] = { [1] = "Wait, $g brother:m'lady;....$b$bOne last thing..." },
        ["text"] = "Зачекай, $g брате:пані;....$b$bЩе одне...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [300724402] = {
        ["english"] = { [1] = "Usurper?" },
        ["text"] = "Узурпатор?",
        ["npcs"] = { [1] = 4949 },
        ["roles"] = { ["reply"] = true },
    },
    [369379979] = {
        ["english"] = { [1] = "Well, the way I see it, $N, we have two options to consider for leaving this cave.$B$BWe can make our way stealthfully--I use the cloak you've given me, and you'd be left to your own devices, or, and this may be a harder option considering my wounds, we fight our way out back to back.$B$BI'll let you decide since you know your strengths better than I." },
        ["text"] = "Ну, як я це бачу, $N, у нас є два варіанти, як вибратися з цієї печери.$B$BМожемо прокрастися — я використаю плащ, який ти мені дав, а ти далі сам по собі; або, і це може бути важче через мої рани, проб'ємося назовні спина до спини.$B$BВирішувати тобі, бо свої сильні сторони ти знаєш краще за мене.",
        ["npcs"] = { [1] = 3692 },
        ["roles"] = { ["greeting"] = true },
    },
    [2705906865] = {
        ["english"] = { [1] = "Vol'jin told me ta keep hittin' da drum till he gets back.  If ya be waitin' for him, he'd be back soon to take back da Isles.$B$BJust wait here and enjoy da music!" },
        ["text"] = "Вол'джин сказав мені бити в барабан, доки він не повернеться. Якщо ти його чекаєш, то він скоро повернеться, щоб відбити острови.$B$BПросто зачекай тут і насолоджуйся музикою!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1278148732] = {
        ["english"] = { [1] = "Train me" },
        ["text"] = "Навчи мене",
        ["npcs"] = { [1] = 376, [2] = 377, [3] = 837, [4] = 1226, [5] = 5141, [6] = 5142, [7] = 5143, [8] = 5484, [9] = 5489, [10] = 11397, [11] = 11406 },
        ["roles"] = { ["reply"] = true },
    },
    [3342164786] = {
        ["english"] = { [1] = "What does Dadanga like to eat?", [2] = "What does Dadanga like to eat?\010" },
        ["text"] = "Що любить їсти Даданґа?",
        ["npcs"] = { [1] = 9273 },
        ["roles"] = { ["reply"] = true },
    },
    [1126938912] = {
        ["english"] = { [1] = "With Ouro slain the way is clear to the final chamber. I am able to transport you there, if you desire." },
        ["text"] = "Оуро вбитий, і шлях до останньої зали відкритий. Якщо бажаєш, я можу перенести тебе туди.",
        ["npcs"] = { [1] = 15502 },
        ["roles"] = { ["greeting"] = true },
    },
    [2044622722] = {
        ["english"] = { [1] = "Where can I find the relics of Terokk?" },
        ["text"] = "Де знайти реліквії Терокка?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [340539569] = {
        ["english"] = { [1] = "Ye looking for Hogral?  Well did ye check the tavern?  Och!  If yer looking for a rogue, and a dwarf one at that, ye should start in the Inn!  Go have a look already." },
        ["text"] = "Шукаєш Гоґрала? А в таверні перевіряв? Ох! Якщо шукаєш розбійника, ще й дворфа, починати треба з таверни! Іди вже подивися.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [39254691] = {
        ["english"] = { [1] = "With all the screws that Bronk has been tightening, I think he's let a few of his own go if ye get me.  All the same he's still got a good head for engineering the darndest devices.  Ye should go pay him a visit over at Steelgrill's Depot." },
        ["text"] = "Після всіх гвинтів, які Бронк затягнув, думаю, кілька власних він послабив, якщо розумієш мене. Та все одно голова в нього добре варить, коли йдеться про найхимерніші інженерні пристрої. Навідайся до нього на склад Сталерешітки.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2269477605] = {
        ["english"] = { [1] = "With all of the fighting we do of course we have a First Aid Trainer in Razor Hill.  Find Rawrk inside the barracks on the east side of town." },
        ["text"] = "Через усі наші битви, звісно, в Колючому Пагорбі є наставник першої допомоги. Шукай Рорка в казармах на східному боці міста.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [306339195] = {
        ["english"] = { [1] = "What can we say, $N?  $G Dude : Dudette;, anything that we have in the store is yours to purchase!$B$BRight on!" },
        ["text"] = "Що тут скажеш, $N? $G Друже : Подруго;, усе, що є в крамниці, можеш купувати!$B$BОтак!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3909285282] = {
        ["english"] = { [1] = "Where is Elder Stormbrow?" },
        ["text"] = "Де старійшина Громобровий?",
        ["npcs"] = { [1] = 15557, [2] = 15562, [3] = 15577, [4] = 15593 },
        ["roles"] = { ["reply"] = true },
    },
    [1894901119] = {
        ["english"] = { [1] = "Would you like to hear a story?" },
        ["text"] = "Хочеш почути історію?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2006350854] = {
        ["english"] = { [1] = "Windsor was particularly ornery that day - and believe me, for Windsor, that's a monumental accomplishment. He kept telling me that 'something feels off.' Well he wasn't kidding!$B$BWe were in the middle of Blackrock Mountain when the filthy animals attacked. I'm talking about the orcs, of course. Pay attention, will ya? All you could hear were grunts and the clanging of steel as they rushed us. " },
        ["text"] = "Того дня Віндзор був особливо сварливий — а повір, для Віндзора це вже неабияке досягнення. Він постійно повторював: «Щось тут не так». І не жартував!$B$BМи були посеред Чорнокамінної гори, коли ті брудні тварюки напали. Я про орків, звісно. Слухай уважно, гаразд? Чути було лише гарчання й брязкіт сталі, коли вони кинулися на нас. ",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["greeting"] = true },
    },
    [3844364703] = {
        ["english"] = { [1] = "What happened to your mercenary company, The Veiled Blade?" },
        ["text"] = "Що сталося з твоєю найманською компанією «Затулений Клинок»?",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["reply"] = true },
    },
    [2834976742] = {
        ["english"] = { [1] = "Very few seek me out... What may I do for you?" },
        ["text"] = "Дуже мало хто мене шукає... Чим можу прислужитися?",
        ["npcs"] = { [1] = 9299 },
        ["roles"] = { ["greeting"] = true },
    },
    [3167121715] = {
        ["english"] = { [1] = "Will you help?" },
        ["text"] = "Допоможеш?",
        ["npcs"] = { [1] = 7783 },
        ["roles"] = { ["reply"] = true },
    },
    [1365839283] = {
        ["english"] = { [1] = "Watch your step aboard Elune's Blessing, $r.  Though Elune's blessed us with the discovery of our new friends, we've also had our share of hardships at sea.$b$bHowever, recovering souls lost at sea or lost in a new world is truly a blessing from Elune." },
        ["text"] = "Дивися під ноги на борту «Благословення Елуни», $r. Хоч Елуна й благословила нас відкриттям наших нових друзів, у морі ми теж зазнали чимало лиха.$b$bТа повернення душ, загублених у морі чи в новому світі, — справжнє благословення Елуни.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [937200238] = {
        ["english"] = { [1] = "We're filled to capacity on purple lotus, $c. Go ask one of the others if they need your help, and leave me to my studies. There is no time to waste!" },
        ["text"] = "Пурпурового лотоса в нас уже по самі вінця, $c. Запитай когось іншого, чи потрібна їм допомога, а мене залиш із дослідженнями. Не можна гаяти часу!",
        ["npcs"] = { [1] = 15512 },
        ["roles"] = { ["greeting"] = true },
    },
    [2482448900] = {
        ["english"] = { [1] = "What are you gonna do when Rulk-a-mania runs wild on you, brother????!" },
        ["text"] = "Що ти робитимеш, коли Рулк-а-манія пронесеться просто по тобі, брате????!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3885083270] = {
        ["english"] = { [1] = "What is the ultimate ability of the Ruby Drake?" },
        ["text"] = "Яка найпотужніша здібність Рубінового драка?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2596918694] = {
        ["english"] = { [1] = "Will you blow up that door now?" },
        ["text"] = "Тепер підірвеш ті двері?",
        ["npcs"] = { [1] = 7607 },
        ["roles"] = { ["reply"] = true },
    },
    [1781035347] = {
        ["english"] = { [1] = "Will the Horde grant me the chance to battle the Scourge?" },
        ["text"] = "Чи дасть Орда мені шанс битися зі Скарою?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3545671218] = {
        ["english"] = { [1] = "Ye want to be trained in the use of a weapon, do ye?  Well don't stand there slack-jawed, speak up $gladdie : lassie;!" },
        ["text"] = "Хочеш навчитися користуватися зброєю, еге? Не стій із роззявленим ротом, говори, $gхлопче : дівчино;!",
        ["npcs"] = { [1] = 11865 },
        ["roles"] = { ["greeting"] = true },
    },
    [3053846578] = {
        ["english"] = { [1] = "We're in a fine mess here." },
        ["text"] = "Добряче ж ми тут ускочили.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2973676115] = {
        ["english"] = { [1] = "Welcome to the Crossroads, $c. My name is Thork--I lead the defenses here in the name of the Warchief.$B$BPlease, feel free to make yourself at home. As long as you mind your business, no one should have any problem with you taking up some space.$B$BThere are many threats to our safety here. If you've already become familiar with the lay of the land, speak to the others here--perhaps they have tasks for you to do." },
        ["text"] = "Ласкаво просимо до Роздоріжжя, $c. Мене звати Торк — від імені Вождя я керую обороною тут.$B$BПочувайся як удома. Поки не лізтимеш у чужі справи, ніхто не матиме нічого проти, якщо ти трохи тут затримаєшся.$B$BНашій безпеці загрожує чимало небезпек. Якщо ти вже ознайомився з місцевістю, поговори з іншими — можливо, у них є для тебе завдання.",
        ["npcs"] = { [1] = 3429 },
        ["roles"] = { ["greeting"] = true },
    },
    [3828824016] = {
        ["english"] = { [1] = "Why... yes, of course. I've something to show you right inside this building, Mr. Anvilward." },
        ["text"] = "Так... звісно. Я хочу дещо показати тобі прямо всередині цієї будівлі, пане Ковадлозахист.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1692299053] = {
        ["english"] = { [1] = "We have begun to turn the Scourge's plague against them, but our hold is tenuous at best!  Be sure to aid the cause by subverting their cauldrons!" },
        ["text"] = "Ми почали обертати чуму Скари проти них самих, але наше становище дуже хитке! Обов'язково допомагай справі, саботуючи їхні котли!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1006177046] = {
        ["english"] = { [1] = "What is it, $c? The Horde is done with all collections, and final preparations are being made while the Alliance tries to catch up in their efforts. Is there anything else that you need?" },
        ["text"] = "Що таке, $c? Орда завершила весь збір, і поки Альянс намагається наздогнати, ми робимо останні приготування. Тобі ще щось потрібно?",
        ["npcs"] = { [1] = 15533 },
        ["roles"] = { ["greeting"] = true },
    },
    [368552400] = {
        ["english"] = { [1] = "Um, hello!  If you are here about fee collection and/or a summons, then you must have me mistaken for someone else.  Terribly sorry!" },
        ["text"] = "Ем, вітаю! Якщо ви прийшли щодо стягнення зборів та/або судової повістки, то, мабуть, переплутали мене з кимось іншим. Страшенно перепрошую!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2079168319] = {
        ["english"] = { [1] = "Why... that is very sweet of you.  I gather that you are volunteering time for Children's Week, yes $c?  Well, you are to be commended.  It is imperative that we remember those less fortunate - especially the children.$B$BI'd be happy to sign an autograph.  Here you go." },
        ["text"] = "Ой... це дуже мило з твого боку. Гадаю, ти добровільно допомагаєш під час Дитячого тижня, так, $c? Що ж, це гідно похвали. Дуже важливо пам'ятати про менш щасливих — особливо про дітей.$B$BЯ із задоволенням дам автограф. Ось, тримай.",
        ["npcs"] = { [1] = 4968 },
        ["roles"] = { ["greeting"] = true },
    },
    [1343270894] = {
        ["english"] = { [1] = "Unlucky name fer a sailor, innit?" },
        ["text"] = "Невдале ім'я для моряка, еге ж?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2252616305] = {
        ["english"] = { [1] = "Why, you look like a common street urchin!" },
        ["text"] = "Та ти схожий на звичайного вуличного шибеника!",
        ["npcs"] = { [1] = 11279, [2] = 11281 },
        ["roles"] = { ["greeting"] = true },
    },
    [616314428] = {
        ["english"] = { [1] = "Why you're just the $c I was looking for! I'm testing a new rocket-powered flying device, and I need your help!$B$BJust take one of these harnesses and put it on under your armor.  Hit the button on the side, and BOOM, off you go.$B$BDon't go trying to steal my work though. Each of these babies is fitted with a Transponster 8000 linked to the one in my hand. If you get too far from me the Transponster will shut down the main rocket and you'll be unable to lift off until you return.$B$BNow where did I put those liability forms?" },
        ["text"] = "Та ти саме той $c, якого я шукав! Я випробовую новий ракетний літальний пристрій і потребую допомоги!$B$BПросто візьми одну з цих упряжей і надягни під обладунок. Натисни кнопку збоку — і БАБАХ, полетів.$B$BТільки не думай красти мою роботу. У кожній цій красуні стоїть Транспонстер 8000, пов'язаний із тим, що в мене в руці. Якщо відійдеш надто далеко, Транспонстер вимкне головну ракету, і ти не зможеш злетіти, доки не повернешся.$B$BТак, а куди я поклав ті форми відмови від відповідальності?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1816071830] = {
        ["english"] = { [1] = "Welcome to my Inn, weary traveler. What can I do for you?" },
        ["text"] = "Ласкаво просимо до моєї таверни, стомлений мандрівнику. Чим можу допомогти?",
        ["npcs"] = { [1] = 295, [2] = 2352, [3] = 2808, [4] = 3628, [5] = 6272, [6] = 6727, [7] = 6740, [8] = 6790, [9] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3712673934] = {
        ["english"] = { [1] = "Urrrk... if that grubbing galley chief over there offers you his special, do yourself a favor and dump it in the ocean. It might kill a few makruras instead of your will to live." },
        ["text"] = "Ур-р-рк... якщо той ненажерливий начальник камбуза запропонує тобі свою фірмову страву, зроби собі послугу — викинь її в океан. Може, вона вб'є кількох макрур замість твоєї жаги до життя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [438321320] = {
        ["english"] = { [1] = "Why you would want to leave these sunny shores and crystal blue waters I have no idea. It's like paradise down here. But don't tell my brother Zapetta that, he's bitter enough already about getting stuck up there in Tirisfal all day long. This Zeppelin here drops off at Orgrimmar so you shouldn't have to worry about having to listen to him whine. But if you are in Tirisfal anytime soon, heed my warning and don't get him started." },
        ["text"] = "Навіщо взагалі покидати ці сонячні береги й кришталево-блакитну воду — не розумію. Тут унизу справжній рай. Тільки не кажи моєму братові Запетті — він і так достатньо злиться, що цілими днями застряг у Тірісфалі. Цей дирижабль летить до Орґріммара, тож слухати його скиглення не доведеться. Але якщо скоро опинишся в Тірісфалі, дослухайся до попередження й не заводь його на цю тему.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [366914585] = {
        ["english"] = { [1] = "What can I do for you?  No, wait!  What can you do for me?" },
        ["text"] = "Чим можу допомогти? Ні, стривай! Що ТИ можеш зробити для мене?",
        ["npcs"] = { [1] = 16417 },
        ["roles"] = { ["greeting"] = true },
    },
    [2018626676] = {
        ["english"] = { [1] = "Why you little..." },
        ["text"] = "Ах ти малий...",
        ["npcs"] = { [1] = 14354 },
        ["roles"] = { ["reply"] = true },
    },
    [3514796414] = {
        ["english"] = { [1] = "Why would you want to talk to Kaplak?  Nevermind.  Look for him on top of the burrow in the southwest corner of Razor Hill.  Just make sure that you keep your hands in your own pockets!" },
        ["text"] = "Навіщо тобі говорити з Каплаком? Та байдуже. Шукай його на вершині нори в південно-західному куті Колючого Пагорба. І тримай руки у власних кишенях!",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [1669086970] = {
        ["english"] = { [1] = "Well look at you. Aren't you big and tough... Maybe you think you're tough enough to step into the Ring of Blood and face the Warmaul champion?$B$B<The pitfighter laughs.>$B$BNot very likely but if you ever wanna test your strength, the Ring of Blood is far to the north against the mountains dividing Nagrand and Zangarmarsh. Gurgthock runs the show at the old Laughing Skull Ruins and he also dispenses the prizes. Speaking of prizes, I hear the prizes this season are incredible!" },
        ["text"] = "Ну поглянь на себе. Такий великий і міцний... Може, гадаєш, що досить сильний, аби вийти на Коло Крові й зустрітися з чемпіоном Бойового Молота?$B$B<Боєць арени сміється.>$B$BНавряд чи, але якщо захочеш випробувати силу, Коло Крові далеко на півночі, біля гір, що розділяють Наґранд і Занґарські болота. Ґурґток керує всім у старих Руїнах Сміхотливого Черепа й видає нагороди. До речі про нагороди — кажуть, цього сезону вони неймовірні!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2938705899] = {
        ["english"] = { [1] = "Welcome to Eco-Dome Midrealm, traveler. I would warn you to be wary of dealing with that goblin, Shauly. I don't believe I've ever heard anyone use the word \"buddy\" as punctuation before." },
        ["text"] = "Ласкаво просимо до Екокупола Серединного Світу, мандрівнику. Раджу остерігатися справ із тим гобліном Шаулі. Не думаю, що раніше чув, аби хтось уживав слово «дружище» замість розділових знаків.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4067621182] = {
        ["english"] = { [1] = "We need to get into the fight. Are you ready?" },
        ["text"] = "Нам треба вступати в бій. Ти готовий?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [317274539] = {
        ["english"] = { [1] = "With enough money, I could take over the world..." },
        ["text"] = "Маючи достатньо грошей, я міг би захопити світ...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [505339791] = {
        ["english"] = { [1] = "We have gained control of the armory, but our work on the island is not yet finished." },
        ["text"] = "Ми захопили зброярню, але наша робота на острові ще не завершена.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1738070811] = {
        ["english"] = { [1] = "Why isn't the Outland called Draenor anymore?" },
        ["text"] = "Чому Позамежжя більше не називається Дренором?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [932676560] = {
        ["english"] = { [1] = "We're here to protect Gadgetzan interests in Un'Goro and that's none of your business." },
        ["text"] = "Ми тут захищаємо інтереси Пристробляска в Ун'Ґоро, а це не твоя справа.",
        ["npcs"] = { [1] = 9460 },
        ["roles"] = { ["greeting"] = true },
    },
    [3422882598] = {
        ["english"] = { [1] = "Ye need some training?  Well, Azar Stronghammer is always up for showing the younger paladins a thing or two.  Why don't ye go see him in the Thunderbrew Distillery." },
        ["text"] = "Потрібне навчання? Азар Міцний Молот завжди готовий показати молодим паладинам кілька прийомів. Зазирни до нього в броварню Громоварів.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [148779502] = {
        ["english"] = { [1] = "Why is it that small creatures such as goblins are always fascinated with larger creatures?" },
        ["text"] = "Чому такі маленькі створіння, як гобліни, завжди зачаровані великими створіннями?",
        ["npcs"] = { [1] = 11627 },
        ["roles"] = { ["greeting"] = true },
    },
    [2219195225] = {
        ["english"] = { [1] = "What business brings you here, $c?" },
        ["text"] = "Яка справа привела тебе сюди, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2705334033] = {
        ["english"] = { [1] = "Through my studies, I see that defeating the god Hakkar's avatar has weakened him.  But the bulk of his strength remains, lurking at the far end of the Nether.$B$BYou have defeated his avatar once, $N.  Perhaps if you defeat it again you can further weaken the god so that, one day, we might face his true self.$B$BI have prepared a spell that you may use to again summon an avatar of Hakkar within the Sanctum of the Fallen God.  Do you want to confront it once again?" },
        ["text"] = "Зі своїх досліджень я бачу, що перемога над аватаром бога Гаккара послабила його. Та більша частина його сили й досі лишається, причаївшись на далекому краю Порожнечі.$B$BТи вже раз переміг його аватара, $N. Можливо, якщо здолаєш його знову, то ще більше послабиш бога, аби колись ми змогли постати перед його істинною сутністю.$B$BЯ підготував закляття, яким ти зможеш знову викликати аватара Гаккара у Святилищі Полеглого Бога. Хочеш знову кинути йому виклик?",
        ["npcs"] = { [1] = 8579 },
        ["roles"] = { ["greeting"] = true },
    },
    [2669354101] = {
        ["english"] = { [1] = "Ye should check over at Steelgrill's Depot for Bronk.  When he's not tinkering with some odd device, he's usually chatting up the pilots about their steam tanks." },
        ["text"] = "Пошукай Бронка на складі Сталерешітки. Коли він не майструє якийсь дивний пристрій, то зазвичай балакає з пілотами про їхні парові танки.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [3241435139] = {
        ["english"] = { [1] = "Welcome to the refuge, $N. Some come here with a purpose, others found their way here by accident... But everyone here seems to have a unique story to tell." },
        ["text"] = "Ласкаво просимо до притулку, $N. Дехто приходить сюди з певною метою, інші опиняються тут випадково... Але, здається, кожен має свою неповторну історію.",
        ["npcs"] = { [1] = 9997 },
        ["roles"] = { ["greeting"] = true },
    },
    [1236899376] = {
        ["english"] = { [1] = "Vengeance shall be mine." },
        ["text"] = "Помста буде моєю.",
        ["npcs"] = { [1] = 8479 },
        ["roles"] = { ["greeting"] = true },
    },
    [2030449369] = {
        ["english"] = { [1] = "Well hi there!  Are you here to learn the proper technique of a new weapon?" },
        ["text"] = "О, вітаю! Прийшов навчитися правильно користуватися новим видом зброї?",
        ["npcs"] = { [1] = 13084 },
        ["roles"] = { ["greeting"] = true },
    },
    [2197998671] = {
        ["english"] = { [1] = "We wish that we could create more than one darkrune in a day, but that would be a waste of time.  It's simply not physically possible.  Besides, we can't even reliably create them at that rate.$B$BAnd trust us, if there were anyone else here smart enough to help, they'd be conscripted and we'd have as many darkrunes as needed." },
        ["text"] = "Хотілося б створювати більше однієї темної руни на день, але це була б марна трата часу. Фізично це просто неможливо. Та й навіть із такою швидкістю ми не завжди можемо їх надійно створити.$B$BІ повір, якби тут був хтось іще достатньо розумний, щоб допомагати, його вже призвали б, і ми мали б стільки темних рун, скільки потрібно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [354833300] = {
        ["english"] = { [1] = "What brings you to this part of the world, $n?" },
        ["text"] = "Що привело тебе в цю частину світу, $n?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2886130876] = {
        ["english"] = { [1] = "We've managed to squeeze through Thunder Bluff twice now!  " },
        ["text"] = "Нам уже двічі вдалося протиснутися крізь Громовий Бескид!  ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [335121374] = {
        ["english"] = { [1] = "Why don't you do it?" },
        ["text"] = "Чому ти сам цього не зробиш?",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["reply"] = true },
    },
    [1760442138] = {
        ["english"] = { [1] = "We want everyone to have fun at Brewfest.  It would also help if we had some people remember it as well.$b$bThese goggles allow anyone to experience what it's like to be drunk, but without the drinking part.  Put the goggles on, and you're drunk!  Take them off, and you're sober!$b$bAre you interested in a pair?" },
        ["text"] = "Ми хочемо, щоб на Хмільному фестивалі всім було весело. І було б непогано, якби хтось потім іще щось пам'ятав.$b$bЦі окуляри дозволяють відчути, як це — бути п'яним, але без самого пиття. Надягнув — і ти п'яний! Зняв — і знову тверезий!$b$bХочеш пару?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2385362149] = {
        ["english"] = { [1] = "Welcome, $N. My expertise is in the art of working with primal mooncloth. Tailors interested in becoming mooncloth specialists often ask me to teach them our ways." },
        ["text"] = "Ласкаво просимо, $N. Я фахівець у роботі з первісною місячною тканиною. Кравці, які хочуть стати майстрами місячної тканини, часто просять мене навчити їх наших методів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2472829560] = {
        ["english"] = { [1] = "Why don't you and Rocknot go find somewhere private..." },
        ["text"] = "Чому б вам із Рокнотом не знайти якесь приватне місце...",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [465991137] = {
        ["english"] = { [1] = "We have a lot of supplies, but we still need a lot more in order to send a ground assault into the Field of Strife." },
        ["text"] = "У нас чимало припасів, але потрібно ще значно більше, щоб відправити наземний наступ на Поле Чвар.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3435913588] = {
        ["english"] = { [1] = "Whoah! You really want buy from us?" },
        ["text"] = "Ого! Ти справді хочеш щось у нас купити?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1331538140] = {
        ["english"] = { [1] = "What can I do for you?" },
        ["text"] = "Чим можу допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [398375955] = {
        ["english"] = { [1] = "We need to get this outpost ready for the push into Sholazar Basin.$B$BDon't just stand there, $c. Go out and represent the Horde with honor and spilled blood!" },
        ["text"] = "Треба підготувати цей форпост до наступу в Шолазарську низовину.$B$BНе стій стовпом, $c. Вирушай і гідно представляй Орду — честю та пролитою кров'ю!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1258072514] = {
        ["english"] = { [1] = "Why don't we see just what you're capable of? If you complete the task I shall be happy to further your training!" },
        ["text"] = "Чому б не перевірити, на що ти здатний? Виконаєш завдання — я із задоволенням продовжу твоє навчання!",
        ["npcs"] = { [1] = 7949 },
        ["roles"] = { ["greeting"] = true },
    },
    [2568292970] = {
        ["english"] = { [1] = "Warrior" },
        ["text"] = "Воїн",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076 },
        ["roles"] = { ["reply"] = true },
    },
    [3337636029] = {
        ["english"] = { [1] = "We a lot cleaner than da ogres in Tanaris.  All over da desert as far as da eye can see - ogre poo.  Not here, no $g sir : ma'am;!" },
        ["text"] = "Ми набагато чистіші за огрів у Танарісі. Куди не глянь у пустелі — скрізь огряче лайно. А тут такого нема, ні, $g пане : пані;!",
        ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 },
        ["roles"] = { ["greeting"] = true },
    },
    [1968316771] = {
        ["english"] = { [1] = "Used by the Barov family of the Scholomance as a mirror into the souls that they no longer possess. A valuable keepsake." },
        ["text"] = "Родина Барових зі Схоломансу використовувала це як дзеркало для душ, яких у них більше немає. Цінна пам'ятка.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1279757522] = {
        ["english"] = { [1] = "Why do you suffer?" },
        ["text"] = "Чому ти страждаєш?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2784213492] = {
        ["english"] = { [1] = "When we use the hides of the animals we must fell for food or protection we give honor to the Earth Mother and respect to the animal.  Chaw Stronghide can teach you of such things.  You will find him in the great tent at the northwest corner of Bloodhoof Village." },
        ["text"] = "Коли ми використовуємо шкури тварин, яких мусимо вбивати заради їжі чи захисту, то віддаємо шану Матері-Землі й поважаємо саму тварину. Чоу Міцношкірий може навчити тебе цьому. Знайдеш його у великому наметі в північно-західному куті селища Криваве Копито.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [249231769] = {
        ["english"] = { [1] = "We don't have time to talk!  We have to think about those trolls!" },
        ["text"] = "Нема часу на розмови! Треба думати про тих тролів!",
        ["npcs"] = { [1] = 7604 },
        ["roles"] = { ["greeting"] = true },
    },
    [1406467784] = {
        ["english"] = { [1] = "Where is Elder Grimtotem?" },
        ["text"] = "Де старійшина Похмурий Тотем?",
        ["npcs"] = { [1] = 15556, [2] = 15587, [3] = 15604 },
        ["roles"] = { ["reply"] = true },
    },
    [58124118] = {
        ["english"] = { [1] = "What can I do for you $c?" },
        ["text"] = "Чим можу допомогти, $c?",
        ["npcs"] = { [1] = 4314 },
        ["roles"] = { ["greeting"] = true },
    },
    [3702284386] = {
        ["english"] = { [1] = "We're too merciful with the Wretched.  We ought to drive a sword through each of them.$B$BTheir boldness in Sunsail Anchorage is unpardonable." },
        ["text"] = "Ми надто милосердні до Знедолених. Треба було б проткнути мечем кожного.$B$BЇхня зухвалість на Якорній стоянці Сонячного Вітрила непростима.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1771273475] = {
        ["english"] = { [1] = "Why didn't you just leave?" },
        ["text"] = "Чому ти просто не пішов?",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["reply"] = true },
    },
    [1410325894] = {
        ["english"] = { [1] = "Why da Scourge let you walk around in here, mon?" },
        ["text"] = "Чого Скара дозволяє тобі тут ходити, мон?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [255745216] = {
        ["english"] = { [1] = "We're tryin' ta blow this wall so Wick's men can work on the new Harbor gatehouse and road beyond, but the clueless sod is cryin' about me using too much powder!$B$BTch. I've been sappin' since he was in diapers. This goes on much longer, I'll kick him into the canal and finish the whole blasted job meself!" },
        ["text"] = "Ми намагаємося підірвати цю стіну, щоб люди Віка могли працювати над новою надбрамною вежею гавані й дорогою за нею, а той безголовий дурень скиглить, що я використовую забагато пороху!$B$BПф. Я підривала укріплення ще коли він у пелюшках ходив. Якщо це триватиме, я скину його в канал і сама закінчу всю кляту роботу!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3074820179] = {
        ["english"] = { [1] = "What was this decision?" },
        ["text"] = "Що це було за рішення?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1037643440] = {
        ["english"] = { [1] = "Why cook when everything tastes like ashes in your mouth?  If you have one still that is.  Very well, head to the Undercity south of Brill and ask an Undercity Guardian there for further directions to their Cooking Trainer.  To get there you can take the elevators down from the rear of the Ruins of Lordaeron." },
        ["text"] = "Навіщо готувати, коли все в роті смакує попелом? Якщо в тебе ще є рот, звісно. Гаразд, вирушай до Підмістя на південь від Брілля й запитай у Вартового Підмістя, як знайти наставника кулінарії. Дістатися туди можна ліфтами в задній частині Руїн Лордерону.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [284297149] = {
        ["english"] = { [1] = "We compete not only for glory, but to bring honor to our ancestors and to our people." },
        ["text"] = "Ми змагаємося не лише заради слави, а й щоб принести честь нашим предкам і нашому народові.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [684979652] = {
        ["english"] = { [1] = "Want to learn leatherworking, eh? Simon Tanner would be able to teach you. He can be found in Old Town at the Protective Hide." },
        ["text"] = "Хочеш навчитися шкірництва, еге? Саймон Таннер зможе тебе навчити. Його знайдеш у Старому місті в «Захисній Шкурі».",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1800128424] = {
        ["english"] = { [1] = "Together we will deal with this corruption of the water." },
        ["text"] = "Разом ми покладемо край цьому оскверненню води.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3555454510] = {
        ["english"] = { [1] = "Why are you here?" },
        ["text"] = "Навіщо ти тут?",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["reply"] = true },
    },
    [690450659] = {
        ["english"] = { [1] = "With some of the technology that was recovered by bold gnomes venturing into Gnomeregan, I have managed to construct my greatest invention:  The Matter Transporter!    All I need now is a skilled Gnomish Engineer to build a powerful beacon attuned to the transporter." },
        ["text"] = "Завдяки технологіям, які хоробрі гноми винесли з Гномреґана, мені вдалося створити свій найбільший винахід: Транспортер Матерії! Тепер потрібен лише вправний гномський інженер, щоб спорудити потужний маяк, налаштований на транспортер.",
        ["npcs"] = { [1] = 14743 },
        ["roles"] = { ["greeting"] = true },
    },
    [3678739029] = {
        ["english"] = { [1] = "We have one eye and see better than you!  Bank in center of Undercity!" },
        ["text"] = "У нас одне око, а бачимо краще за тебе! Банк у центрі Підмістя!",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3368002780] = {
        ["english"] = { [1] = "What you must understand is that being able to index 10,000 years of existence has given me a rather unique perspective on life. Your present day trials and tribulations are meaningless." },
        ["text"] = "Тобі слід зрозуміти: здатність упорядкувати десять тисяч років існування дала мені доволі унікальний погляд на життя. Твої нинішні випробування й негаразди нічого не важать.",
        ["npcs"] = { [1] = 14368 },
        ["roles"] = { ["greeting"] = true },
    },
    [3245792642] = {
        ["english"] = { [1] = "Whew... I need a smoke and the touch of a fine gnomish woman - not particularly in that order!$B$BI've been stuck inside the belly of that thing for months! What day is it anyway? Ah, nevermind. All that matters is that I'm finally out.$B$BWOOO HOOO!" },
        ["text"] = "Фух... мені потрібна сигара й дотик гарної гномки — і не обов'язково в такому порядку!$B$BЯ місяцями сидів у череві тієї тварюки! Який сьогодні день? Та байдуже. Головне, що я нарешті вибрався.$B$BУУУ-ХУУУ!",
        ["npcs"] = { [1] = 10776 },
        ["roles"] = { ["greeting"] = true },
    },
    [2005089767] = {
        ["english"] = { [1] = "Who's the most popular hero of the realm, you ask?  Well here are the current standings!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal Horde: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal Alliance: $2206w$B$BIf you want to cast your vote, be sure turn in your gift collections!" },
        ["text"] = "Питаєш, хто найпопулярніший герой королівства? Ось поточні результати!$B$BТралл: $2200w$BКерн: $2201w$BСильвана: $2202w$BУсього Орда: $2207w$B$BБолвар: $2203w$BМаґні: $2204w$BТіранда: $2205w$BУсього Альянс: $2206w$B$BЯкщо хочеш віддати голос, обов'язково здавай свої набори подарунків!",
        ["npcs"] = { [1] = 16075 },
        ["roles"] = { ["greeting"] = true },
    },
    [277734613] = {
        ["english"] = { [1] = "Very well. Cut another lump of flesh from one of these specimens. Let us test what you've learned so far, and we can progress from there." },
        ["text"] = "Гаразд. Відріж іще один шмат плоті від одного з цих зразків. Перевіримо, чого ти вже навчився, а тоді рушимо далі.",
        ["npcs"] = { [1] = 11044 },
        ["roles"] = { ["greeting"] = true },
    },
    [2559492125] = {
        ["english"] = { [1] = "We have much in common, night elf. I can't help but feel that perhaps it was fate that brought us together. Let me help you, Cowlen. Let my people help. We will right the wrongs. This I vow." },
        ["text"] = "У нас багато спільного, нічний ельфе. Не можу позбутися відчуття, що, можливо, сама доля звела нас. Дозволь мені допомогти тобі, Ковлене. Дозволь допомогти моєму народові. Ми виправимо заподіяне зло. Присягаюся.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3015110904] = {
        ["english"] = { [1] = "Who sent you here? You're not ready for my instruction yet! You'll be told when you're ready." },
        ["text"] = "Хто тебе сюди прислав? Ти ще не готовий до мого навчання! Тобі скажуть, коли настане час.",
        ["npcs"] = { [1] = 2399 },
        ["roles"] = { ["greeting"] = true },
    },
    [3222284620] = {
        ["english"] = { [1] = "We serve the light unquestioningly. Perhaps you might be a bit more curious about our purpose?" },
        ["text"] = "Ми беззаперечно служимо Світлу. Можливо, тобі варто трохи більше поцікавитися нашою метою?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1152458951] = {
        ["english"] = { [1] = "Welcome to the Cenarion Refuge, $n. I've been instructed to offer you basic supplies for purchase, should you need them." },
        ["text"] = "Ласкаво просимо до Кенарійського притулку, $n. Мені наказано продавати тобі базові припаси, якщо вони знадобляться.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3872712989] = {
        ["english"] = { [1] = "Who says Orcs aren't smart? It takes a lot of brains to be an engineer!" },
        ["text"] = "Хто сказав, що орки не розумні? Щоб бути інженером, треба мати чимало мізків!",
        ["npcs"] = { [1] = 2857 },
        ["roles"] = { ["greeting"] = true },
    },
    [710647153] = {
        ["english"] = { [1] = "Who knows? Anyhow, that was the last I saw of her. Maybe Frankal can give you better information.$B$BNot to steer off topic here as I'm sure the work you're doing for the Commander is important, but we're onto something huge here. HUGE! Our requests to Ironforge for an army have so far fallen on deaf ears. Apparently we're stretched too thin in protecting the realm or some such nonsense. Once you take your report back to the Commander, come back down here with some friends. We need your help!" },
        ["text"] = "Хто знає? У будь-якому разі, це був останній раз, коли я її бачив. Може, Франкал зможе розповісти більше.$B$BНе хочу відходити від теми — упевнений, робота для Командира важлива, — але ми натрапили на щось ВЕЛИЧЕЗНЕ. ВЕЛИЧЕЗНЕ! Наші прохання до Стальгорна про армію досі лишаються без відповіді. Кажуть, сили королівства й так надто розтягнуті чи якась така дурня. Коли віднесеш свій звіт Командиру, повертайся сюди з друзями. Нам потрібна допомога!",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["greeting"] = true },
    },
    [3250421216] = {
        ["english"] = { [1] = "What do you want?$B$BIt's a bit rude to walk up to strangers for no reason, don't you think?" },
        ["text"] = "Чого тобі?$B$BТрохи неввічливо підходити до незнайомців без причини, не думаєш?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3471735261] = {
        ["english"] = { [1] = "Who is this Lar'korwi you spoke of?" },
        ["text"] = "Хто такий цей Лар'корві, про якого ти говорив?",
        ["npcs"] = { [1] = 9619 },
        ["roles"] = { ["reply"] = true },
    },
    [4083747811] = {
        ["english"] = { [1] = "When the Darkmoon Faire opens, it will be located in Mulgore.  We'll be pitching our tents just southwest of Thunder Bluff!" },
        ["text"] = "Коли ярмарок Темного Місяця відкриється, він буде в Мулґорі. Ми поставимо намети трохи на південний захід від Громового Бескиду!",
        ["npcs"] = { [1] = 14843 },
        ["roles"] = { ["greeting"] = true },
    },
    [539657405] = {
        ["english"] = { [1] = "Wait, back up. What was that last thing you said?" },
        ["text"] = "Стривай, повернімося назад. Що ти щойно сказав?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1544993265] = {
        ["english"] = { [1] = "We'll take over from here, you've earned quite a respite after that battle." },
        ["text"] = "Далі ми впораємося самі. Після тієї битви ти заслужив добрячий перепочинок.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [967292785] = {
        ["english"] = { [1] = "We live in a world of endless tragedy." },
        ["text"] = "Ми живемо у світі нескінченної трагедії.",
        ["npcs"] = { [1] = 14358 },
        ["roles"] = { ["reply"] = true },
    },
    [1358250755] = {
        ["english"] = { [1] = "Welcome to Booty Bay, partner.  I hope your stay in my town is enjoyable and uneventful - emphasis on the latter.  We've got plenty of drink if you're thirsty, and plenty of bouncers if you're antsy.$B$BNow then... what can this humble servant of the Steamwheedle Cartel do for you?  Better still - what can you do for me, eh?" },
        ["text"] = "Ласкаво просимо до Бухти Наживи, партнере. Сподіваюся, твоє перебування в моєму місті буде приємним і без пригод — особливо без пригод. Якщо мучить спрага, випивки вистачає, а якщо сверблять кулаки — викидайл теж.$B$BНу то... чим цей скромний слуга Картелю Хиткої Шестерні може тобі прислужитися? А ще краще — що ти можеш зробити для мене, га?",
        ["npcs"] = { [1] = 2496 },
        ["roles"] = { ["greeting"] = true },
    },
    [2435559780] = {
        ["english"] = { [1] = "What do ye need directions to?" },
        ["text"] = "Куди тобі потрібні вказівки?",
        ["npcs"] = { [1] = 727, [2] = 5595, [3] = 12996, [4] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2019453508] = {
        ["english"] = { [1] = "What can you tell me about the hippogryph - Sharptalon?", [2] = "What can you tell me about the hippogryph - Sharptalon?\010" },
        ["text"] = "Що можеш розповісти про гіпогрифа Гострокігтя?",
        ["npcs"] = { [1] = 12696 },
        ["roles"] = { ["reply"] = true },
    },
    [4010235038] = {
        ["english"] = { [1] = "Very fine equipment you make, very fine indeed. Go to the Orc's home of Orgrimmar and seek out a smith named Saru Steelfury. One thing you must give the Orcs, they make beautiful instruments of death." },
        ["text"] = "Дуже гарне спорядження ти робиш, справді чудове. Вирушай до орчої столиці Орґріммара й знайди коваля на ім'я Сару Сталелють. Що не кажи про орків, а знаряддя смерті вони роблять прекрасні.",
        ["npcs"] = { [1] = 4596 },
        ["roles"] = { ["greeting"] = true },
    },
    [908994171] = {
        ["english"] = { [1] = "Where can I find bone fragments?" },
        ["text"] = "Де можна знайти уламки кісток?",
        ["npcs"] = { [1] = 16131 },
        ["roles"] = { ["reply"] = true },
    },
    [4027692535] = {
        ["english"] = { [1] = "Yeah, yeah, I'm feeling better, but I kind of like it down here." },
        ["text"] = "Ага-ага, мені вже краще, але тут унизу мені наче навіть подобається.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2841885477] = {
        ["english"] = { [1] = "What staff?" },
        ["text"] = "Який посох?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [102598056] = {
        ["english"] = { [1] = "Welcome to Light's Hope Chapel, stranger." },
        ["text"] = "Ласкаво просимо до каплиці Останньої Надії, незнайомцю.",
        ["npcs"] = { [1] = 16256 },
        ["roles"] = { ["greeting"] = true },
    },
    [4075933809] = {
        ["english"] = { [1] = "Who do I need to kill?" },
        ["text"] = "Кого мені треба вбити?",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["reply"] = true },
    },
    [1709499860] = {
        ["english"] = { [1] = "We have won $2219W battles against the Scourge.  Gird yourself, $N, for this war is far from over." },
        ["text"] = "Ми виграли $2219W битв проти Скари. Готуйся, $N, ця війна ще далеко не закінчена.",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["greeting"] = true },
    },
    [2976985407] = {
        ["english"] = { [1] = "Who are you?  Where am I?  I feel... so weak..." },
        ["text"] = "Хто ти? Де я? Я почуваюся... таким слабким...",
        ["npcs"] = { [1] = 15190 },
        ["roles"] = { ["greeting"] = true },
    },
    [3403419067] = {
        ["english"] = { [1] = "We are safe... for now. His strength has increased tenfold since our last battle. It will take a mighty army to destroy the Lich King. An army greater than even the Horde can rouse." },
        ["text"] = "Ми в безпеці... поки що. Від нашої останньої битви його сила зросла вдесятеро. Щоб знищити Короля-Ліча, знадобиться могутня армія. Армія більша, ніж навіть Орда здатна зібрати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2411733017] = {
        ["english"] = { [1] = "Who are you?  What do you want here?" },
        ["text"] = "Хто ти? Чого тобі тут треба?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1356087123] = {
        ["english"] = { [1] = "We are but so close to developing the New Plague that our Dark Lady desires with such fervor." },
        ["text"] = "Ми вже зовсім близько до створення Нової Чуми, якої так пристрасно бажає наша Темна Пані.",
        ["npcs"] = { [1] = 2216 },
        ["roles"] = { ["greeting"] = true },
    },
    [3260598851] = {
        ["english"] = { [1] = "Who are you? What do you want from me?" },
        ["text"] = "Хто ти? Чого хочеш від мене?",
        ["npcs"] = { [1] = 5157 },
        ["roles"] = { ["greeting"] = true },
    },
    [3179525291] = {
        ["english"] = { [1] = "We'll start in just a moment.$B$BI just want to be very clear -- we're not here to soften them up. We're not here to make a dent. We're here to put an end to the disease that calls itself the Scarlet Onslaught.$B$BIf you don't want any part of that, if you don't have the stomach, fly away now. I want someone with us who is going to be here every day until the job's done.$B$BAre you that $g man : woman;, $N?" },
        ["text"] = "Ми почнемо за мить.$B$BХочу, щоб усе було цілком зрозуміло: ми не прийшли їх просто послабити. Не прийшли трохи їм нашкодити. Ми прийшли покласти край хворобі, що називає себе Багряним Натиском.$B$BЯкщо не хочеш мати з цим справу, якщо тобі бракує духу — відлітай зараз. Мені потрібен той, хто буде з нами щодня, доки справа не буде завершена.$B$BТи саме $g чоловік : жінка;, $N?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4266929963] = {
        ["english"] = { [1] = "Who are you?" },
        ["text"] = "Хто ти?",
        ["npcs"] = { [1] = 5843 },
        ["roles"] = { ["greeting"] = true },
    },
    [3976885038] = {
        ["english"] = { [1] = "Who are you and why are you bothering me? Oh, right--potions student. Right. What can I do for you?" },
        ["text"] = "Хто ти й чому мені докучаєш? А, точно — учень зіль. Гаразд. Чим можу допомогти?",
        ["npcs"] = { [1] = 5177 },
        ["roles"] = { ["greeting"] = true },
    },
    [3903571958] = {
        ["english"] = { [1] = "To win this war, we can't sit idle and let the tides sweep us over.  We must strike, hard and fast, or Arathi will never again be ours." },
        ["text"] = "Щоб перемогти у цій війні, ми не можемо сидіти склавши руки й чекати, доки хвиля нас накриє. Треба бити сильно й швидко, інакше Араті вже ніколи не буде нашим.",
        ["npcs"] = { [1] = 14984 },
        ["roles"] = { ["greeting"] = true },
    },
    [1822333701] = {
        ["english"] = { [1] = "To learn to cure leather and work with hides go to Orgrimmar to the north.  One of the Orgrimmar Grunts will be able to tell you the way to the Leatherworking Trainer." },
        ["text"] = "Щоб навчитися вичиняти шкіру та працювати зі шкурами, вирушай на північ до Орґріммара. Один із орґріммарських вартових підкаже дорогу до наставника шкірництва.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [365064886] = {
        ["english"] = { [1] = "Who are the Sethekk?" },
        ["text"] = "Хто такі сетекки?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3366125632] = {
        ["english"] = { [1] = "Who are the Earthen?" },
        ["text"] = "Хто такі земельники?",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [856458005] = {
        ["english"] = { [1] = "Well met, Battle-Sister. I can assist you in recovering lost companions." },
        ["text"] = "Вітаю, бойова сестро. Я можу допомогти тобі повернути загублених супутників.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2723952709] = {
        ["english"] = { [1] = "What are the anomalies you speak of?" },
        ["text"] = "Що це за аномалії, про які ти говориш?",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [2242667015] = {
        ["english"] = { [1] = "Ye won't find any skinners out in here Dun Morogh $glad : lass;, they're mostly to be found in Ironforge if ye're looking to be trained." },
        ["text"] = "Тут у Дун-Морозі майстрів зі зняття шкур не знайдеш, $gхлопче : дівчино; якщо хочеш навчатися, більшість із них у Стальгорні.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [1528773235] = {
        ["english"] = { [1] = "What? No, I don't do armor repairs. Everlook is about a mile to the north, $g brother : sister;.$B$BNow buy something, or move along before I summon my warlock to deal with you!" },
        ["text"] = "Що? Ні, обладунки я не лагоджу. Завшегляд приблизно за милю на північ, $g брате : сестро;.$B$BА тепер купуй щось або забирайся, поки я не викликав свого чорнокнижника розібратися з тобою!",
        ["npcs"] = { [1] = 16015 },
        ["roles"] = { ["greeting"] = true },
    },
    [996295990] = {
        ["english"] = { [1] = "Uldaman is an ancient Titan vault that has laid buried within the earth since the world's creation. Dwarven excavations of the city have recently released the Titans' first failed creations: the troggs. Legends say that when the Titans deemed the trogg experiment a failure they tried again, resulting in the creation of the dwarven race. These secrets are recorded on the fabled Discs of Norgannon - massive artifacts that lie at the bottom of the ancient city, protected by giant constructs of living stone. \010" },
        ["text"] = "Ульдаман — це стародавнє сховище титанів, поховане в надрах землі ще від часів створення світу. Дворфійські розкопки міста нещодавно випустили на волю перші невдалі творіння титанів — троггів. За легендами, визнавши експеримент із троггами невдалим, титани спробували знову, і так з'явилася раса дворфів. Ці таємниці записані на легендарних Дисках Норґаннона — величезних артефактах, що лежать у глибинах стародавнього міста під охороною велетенських конструкцій із живого каменю. \010",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [395877368] = {
        ["english"] = { [1] = "Whiplash" },
        ["text"] = "Хлист",
        ["npcs"] = { [1] = 10578 },
        ["roles"] = { ["reply"] = true },
    },
    [2755284135] = {
        ["english"] = { [1] = "We of the Horde have done all that we can to prepare for the upcoming war at Ahn'Qiraj. Now we wait, $c, for the Alliance to do the same. Once they are done we will all transport our war materiel to Cenarion Hold in Silithus." },
        ["text"] = "Ми, Орда, зробили все можливе, щоб підготуватися до майбутньої війни за Ан'Кіраж. Тепер чекаємо, $c, доки Альянс зробить те саме. Коли вони завершать, ми всі перевеземо військові припаси до Кенарійської цитаделі в Силітусі.",
        ["npcs"] = { [1] = 15528 },
        ["roles"] = { ["greeting"] = true },
    },
    [2710574944] = {
        ["english"] = { [1] = "Welcome to our home, $N. Radnaal and I have little to offer, but you are welcome to what hospitality we can provide." },
        ["text"] = "Ласкаво просимо до нашої оселі, $N. Ми з Раднаалом небагато можемо запропонувати, але раді поділитися всією гостинністю, яку маємо.",
        ["npcs"] = { [1] = 3605 },
        ["roles"] = { ["greeting"] = true },
    },
    [1057814768] = {
        ["english"] = { [1] = "Well well!  You've come to the right place to learn Mining, $gboyo : girlie;!  Geofram Bouldertoe himself resides at the Deepmountain Mining Guild.  Ye couldn't ask for a better instructor than him." },
        ["text"] = "Ого! Ти прийшов саме туди, де треба вчитися гірництва, $gхлопче : дівчино;! Сам Ґеофрам Валунопалець живе в Гільдії гірників Глибокої Гори. Кращого наставника годі й шукати.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [3431022696] = {
        ["english"] = { [1] = "Where is Elder Brightspear?" },
        ["text"] = "Де старійшина Ясний Спис?",
        ["npcs"] = { [1] = 15574, [2] = 15603 },
        ["roles"] = { ["reply"] = true },
    },
    [1730936848] = {
        ["english"] = { [1] = "What is it? Can't you see I'm busy?" },
        ["text"] = "Що таке? Не бачиш, я зайнятий?",
        ["npcs"] = { [1] = 7231 },
        ["roles"] = { ["greeting"] = true },
    },
    [3988092462] = {
        ["english"] = { [1] = "While we have much to teach the other races of the Alliance, we have as much to learn from them.  Keep your eyes, ears and mind open, $c." },
        ["text"] = "Хоч нам і є чого навчити інші раси Альянсу, нам так само є чого в них навчитися. Тримай очі, вуха й розум відкритими, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3404680449] = {
        ["english"] = { [1] = "When I was wandering the crater after I crashed here, I remembered something that I once was told... \"Go up, up the mountain ahead,\" said the voice in my head.$B$BListening to it is how I ended up here, $N!" },
        ["text"] = "Коли я блукав кратером після аварії, то згадав дещо, що колись чув... «Підіймайся вгору, вгору на гору попереду», — сказав голос у моїй голові.$B$BЯ послухався його — і так опинився тут, $N!",
        ["npcs"] = { [1] = 8737 },
        ["roles"] = { ["greeting"] = true },
    },
    [1208011987] = {
        ["english"] = { [1] = "Welcome to Forest Song, $c. If there is anything I can do for you, please let me know." },
        ["text"] = "Ласкаво просимо до Лісової Пісні, $c. Якщо я можу чимось допомогти — скажи.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3412889962] = {
        ["english"] = { [1] = "Welcome to Tanaris, $N. How can I be of service to you today? You don't look like a blacksmith to me, but I know how looks can be deceiving." },
        ["text"] = "Ласкаво просимо до Танарісу, $N. Чим можу прислужитися сьогодні? На коваля ти не дуже схожий, але я знаю, що зовнішність оманлива.",
        ["npcs"] = { [1] = 5411 },
        ["roles"] = { ["greeting"] = true },
    },
    [3405530565] = {
        ["english"] = { [1] = "We Timbermaw can grant you safe passage through the hold, however, you must prove yourself worthy of our aid." },
        ["text"] = "Ми, Деревна Паща, можемо дати тобі безпечний прохід через нашу твердиню, але спершу доведи, що гідний нашої допомоги.",
        ["npcs"] = { [1] = 11556 },
        ["roles"] = { ["greeting"] = true },
    },
    [3312775156] = {
        ["english"] = { [1] = "What a wonderful day to be alive! Look at the beauty that surrounds you, friend. Enjoy what life has to give!" },
        ["text"] = "Який чудовий день, щоб бути живим! Поглянь на красу навколо, друже. Насолоджуйся всім, що дає життя!",
        ["npcs"] = { [1] = 14527 },
        ["roles"] = { ["greeting"] = true },
    },
    [4151240279] = {
        ["english"] = { [1] = "Warlocks... I don't care for their lot.  Like that Grimrizz who's set up shop outside the Thunderbrew Distillery. The ale will probably go flat there because of him!  Warlocks... bah!" },
        ["text"] = "Чорнокнижники... не до душі мені їхня братія. От хоча б той Ґрімрізз, що влаштувався біля пивоварні Громоварів. Через нього там, певно, все пиво видихається! Чорнокнижники... тьху!",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [1958532873] = {
        ["english"] = { [1] = "We're holding Lord Jaraxxus back for now, but we can't keep him bound for much longer." },
        ["text"] = "Поки що ми стримуємо лорда Джараксуса, але довго втримувати його в путах не зможемо.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3351409777] = {
        ["english"] = { [1] = "We are quickly learning the price of death in this frigid wasteland, $N. The Lich King's power extends across every inch of Northrend, permeating into the earth itself! He turns our own fallen people against us.$B$BFrom the sky, risen gryphon riders rain down their vengeful stormhammers as the walking dead assail us on the ground.$B" },
        ["text"] = "Ми швидко дізнаємося ціну смерті в цій крижаній пустці, $N. Влада Короля-Ліча простягається на кожен клаптик Нортренду, проникаючи в саму землю! Він обертає наших полеглих проти нас.$B$BЗ неба воскреслі вершники на грифонах обрушують мстиві громомолоти, а на землі нас атакують ходячі мерці.$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3352007055] = {
        ["english"] = { [1] = "While Theramore is reknown for it's exceptional training of warriors, I am afraid that I can not help you." },
        ["text"] = "Хоч Терамор і славиться винятковою підготовкою воїнів, боюся, я не можу тобі допомогти.",
        ["npcs"] = { [1] = 8141 },
        ["roles"] = { ["greeting"] = true },
    },
    [3105663696] = {
        ["english"] = { [1] = "Welcome to Caer Darrow, stranger." },
        ["text"] = "Ласкаво просимо до Каєр-Дарроу, незнайомцю.",
        ["npcs"] = { [1] = 11277 },
        ["roles"] = { ["greeting"] = true },
    },
    [1295059066] = {
        ["english"] = { [1] = "Times are changing, $N.  War has arrived.$B$BWill our people rise to the occasion and aid our allies... or will we linger in the sidelines?" },
        ["text"] = "Часи змінюються, $N. Війна прийшла.$B$BЧи піднімуться наші люди й допоможуть союзникам... чи лишаться осторонь?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3955368904] = {
        ["english"] = { [1] = "While nothing can change the past, time can heal all wounds. Thank you for showing me that it is possible, $N. I wish you well." },
        ["text"] = "Минулого не змінити, але час лікує всі рани. Дякую, що показав мені: це можливо, $N. Бажаю тобі всього найкращого.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3964440884] = {
        ["english"] = { [1] = "Welcome to the Bank of Darnassus. We offer financial accounts and safety deposit boxes for valuable items. Do you already have an account with us $g sir : ma'am;?" },
        ["text"] = "Ласкаво просимо до банку Дарнаса. Ми пропонуємо банківські рахунки та сейфи для цінних речей. У вас уже є рахунок у нас, $g пане : пані;?",
        ["npcs"] = { [1] = 4155 },
        ["roles"] = { ["greeting"] = true },
    },
    [2724073447] = {
        ["english"] = { [1] = "Very well, let's go!" },
        ["text"] = "Гаразд, ходімо!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4098494408] = {
        ["english"] = { [1] = "Us have skinning hook.  We get it from Killian Hagey who teach us how to skin kills.  You have nice skin.  You find him on inner ring of Rogues' Quarter." },
        ["text"] = "У нас є гак для зняття шкур. Ми його взяли в Кілліана Геґі, він учить нас знімати шкури зі здобичі. У тебе гарна шкіра. Знайдеш його на внутрішньому кільці Кварталу Розбійників.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [1733346173] = {
        ["english"] = { [1] = "While it is true that the Alliance has completed all of their war effort tasks, don't let that discourage you, $r. Time is of the essence, but we would much rather that you help in the Horde's collections carefully and thoroughly. That seems better to me than making a mistake that could cost someone their life once this war truly begins. Wouldn't you agree, $c?" },
        ["text"] = "Хоч Альянс і завершив усі свої завдання для війни, не падай духом, $r. Час важливий, але ми воліли б, щоб ти допомагав Орді збирати все уважно й ретельно. Це краще, ніж припуститися помилки, яка може коштувати комусь життя, коли війна справді почнеться. Згоден, $c?",
        ["npcs"] = { [1] = 15458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2079625393] = {
        ["english"] = { [1] = "Wow, you totally bombed out there. Let's think of that as a rehearsal, shall we? Ready to go out again?" },
        ["text"] = "Ого, ти там повністю провалився. Вважаймо це репетицією, гаразд? Готовий спробувати ще раз?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1349878770] = {
        ["english"] = { [1] = "While exploration in these new lands is no doubt important, you mustn't forsake Azeroth! We need you now more than ever in the fight against the Defilers. Those resources must be secured!" },
        ["text"] = "Дослідження цих нових земель, без сумніву, важливе, але не можна забувати Азерот! У боротьбі проти Осквернителів ти потрібен нам як ніколи. Ці ресурси мають бути захоплені!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [680804862] = {
        ["english"] = { [1] = "What enchantments interest you today, $c?" },
        ["text"] = "Які зачарування цікавлять тебе сьогодні, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2654901726] = {
        ["english"] = { [1] = "While Cyndra is not bubbly like her potions, her kind manner is suitable for teaching her trade.  You can find her just east of the Inn in Dolanaar." },
        ["text"] = "Хоч Синдра й не така шипуча, як її зілля, її добра вдача чудово пасує до навчання ремесла. Знайдеш її трохи на схід від таверни в Доланаарі.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [1737996593] = {
        ["english"] = { [1] = "We are but darkness and shadows. Eternal. Invisible." },
        ["text"] = "Ми — лише темрява й тіні. Вічні. Невидимі.",
        ["npcs"] = { [1] = 3599, [2] = 4163, [3] = 4214, [4] = 4215 },
        ["roles"] = { ["greeting"] = true },
    },
    [448462128] = {
        ["english"] = { [1] = "Train me." },
        ["text"] = "Навчи мене.",
        ["npcs"] = { [1] = 514, [2] = 1103, [3] = 1241, [4] = 1292, [5] = 1346, [6] = 1355, [7] = 1430, [8] = 1470, [9] = 1676, [10] = 1699, [11] = 1701, [12] = 1702, [13] = 2326, [14] = 2327, [15] = 2329, [16] = 2798, [17] = 2836, [18] = 3001, [19] = 3004, [20] = 3007, [21] = 3069, [22] = 3087, [23] = 3136, [24] = 3137, [25] = 3181, [26] = 3347, [27] = 3357, [28] = 3365, [29] = 3373, [30] = 3605, [31] = 4159, [32] = 4210, [33] = 4211, [34] = 4213, [35] = 4254, [36] = 4591, [37] = 4598, [38] = 5127, [39] = 5153, [40] = 5164, [41] = 5174, [42] = 5177, [43] = 5392, [44] = 5482, [45] = 5513, [46] = 5759, [47] = 5939, [48] = 5943, [49] = 6094, [50] = 6286, [51] = 7949, [52] = 8126, [53] = 8153, [54] = 8738, [55] = 9584, [56] = 11052, [57] = 11072, [58] = 11073 },
        ["roles"] = { ["reply"] = true },
    },
    [942101572] = {
        ["english"] = { [1] = "Well you're an ugly one! Don't mean you don't know how to fight though.$B$BOne of my squads should be geared and ready to march soon - get your sorry butt in line and make the climb with them!" },
        ["text"] = "Ну й страхіття ж ти! Але це не означає, що битися не вмієш.$B$BОдин із моїх загонів незабаром буде споряджений і готовий рушати — ставай у стрій і підіймайся разом із ними!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2616687101] = {
        ["english"] = { [1] = "Tower Point holds the pass between the Field of Strife and the Horde territories to the south.$B$BIt is controlled by the Horde." },
        ["text"] = "Вежова точка утримує прохід між Полем Чвар і територіями Орди на півдні.$B$BЇї контролює Орда.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1413303558] = {
        ["english"] = { [1] = "Um, you already know everything I could teach you. Maybe it's time for you to talk to someone else. Try the night elf Ainethil in the Craftsmen's Terrace of Darnassus. She's got some real talent!" },
        ["text"] = "Ем, ти вже знаєш усе, чого я міг би тебе навчити. Може, час поговорити з кимось іншим. Спробуй знайти нічну ельфійку Айнетіль на Терасі Ремісників у Дарнасі. Вона справді талановита!",
        ["npcs"] = { [1] = 5177 },
        ["roles"] = { ["greeting"] = true },
    },
    [242532920] = {
        ["english"] = { [1] = "Which trainer do you seek?" },
        ["text"] = "Якого наставника ти шукаєш?",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 3084, [13] = 3212, [14] = 3215, [15] = 3217, [16] = 3218, [17] = 3219, [18] = 3220, [19] = 3221, [20] = 3222, [21] = 3223, [22] = 3224, [23] = 3296, [24] = 5624, [25] = 5725, [26] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [2893777626] = {
        ["english"] = { [1] = "Which profession?" },
        ["text"] = "Якої професії?",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 3084, [13] = 3212, [14] = 3215, [15] = 3217, [16] = 3218, [17] = 3219, [18] = 3220, [19] = 3221, [20] = 3222, [21] = 3223, [22] = 3224, [23] = 3296, [24] = 5624, [25] = 5725, [26] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [2679048162] = {
        ["english"] = { [1] = "What a fine day! It inspires me to create a new design." },
        ["text"] = "Який чудовий день! Він надихає мене створити новий дизайн.",
        ["npcs"] = { [1] = 4159 },
        ["roles"] = { ["greeting"] = true },
    },
    [1536085045] = {
        ["english"] = { [1] = "We are most pleased with your actions against the night elves. When you uncovered their plot to use the ley-line nexi and their so-called moon crystals to spy upon us, you strengthened our position here by an order of magnitude.$B$BYou have our gratitude, $N." },
        ["text"] = "Ми дуже задоволені твоїми діями проти нічних ельфів. Коли ти розкрив їхню змову — використовувати вузли лей-ліній і так звані місячні кристали, щоб шпигувати за нами, — ти незмірно зміцнив наші позиції тут.$B$BПрийми нашу вдячність, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1488050284] = {
        ["english"] = { [1] = "Which profession trainer would ye be looking for?" },
        ["text"] = "Якого наставника професії ти шукаєш?",
        ["npcs"] = { [1] = 727, [2] = 5595, [3] = 12996, [4] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2105689401] = {
        ["english"] = { [1] = "Tyrande sends her prayers. The Mother Moon blesses us all." },
        ["text"] = "Тіранда передає свої молитви. Нехай Місячна Матір благословить усіх нас.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1990326142] = {
        ["english"] = { [1] = "Which profession trainer are you looking for?" },
        ["text"] = "Якого наставника професії ти шукаєш?",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [358781867] = {
        ["english"] = { [1] = "We are very fortunate to be alive, you and I!" },
        ["text"] = "Нам із тобою дуже пощастило залишитися живими!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3545441291] = {
        ["english"] = { [1] = "Which class trainer might ye be looking for?" },
        ["text"] = "Якого наставника класу ти шукаєш?",
        ["npcs"] = { [1] = 727, [2] = 5595, [3] = 12996, [4] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [1579444906] = {
        ["english"] = { [1] = "What?! How did you sneak past my jail...er, minion out there? Well, I suppose it's for the best. Sales have been a little slow lately.$B$BHow may I fulfill your infernal needs, $c?" },
        ["text"] = "Що?! Як ти прокрався повз мою в'яз... тобто прислужника там зовні? Ну, мабуть, воно й на краще. Продажі останнім часом не дуже.$B$BЧим задовольнити твої пекельні потреби, $c?",
        ["npcs"] = { [1] = 16015 },
        ["roles"] = { ["greeting"] = true },
    },
    [1698387513] = {
        ["english"] = { [1] = "Where is Elder Bladeswift?" },
        ["text"] = "Де старійшина Швидкий Клинок?",
        ["npcs"] = { [1] = 15562, [2] = 15595, [3] = 15600, [4] = 15601, [5] = 15871 },
        ["roles"] = { ["reply"] = true },
    },
    [2514079191] = {
        ["english"] = { [1] = "Where is Elder Obsidian?" },
        ["text"] = "Де старійшина Обсидіан?",
        ["npcs"] = { [1] = 15568, [2] = 15594 },
        ["roles"] = { ["reply"] = true },
    },
    [3170384842] = {
        ["english"] = { [1] = "What can I do for ya?" },
        ["text"] = "Чим можу допомогти?",
        ["npcs"] = { [1] = 5167 },
        ["roles"] = { ["greeting"] = true },
    },
    [3482393705] = {
        ["english"] = { [1] = "Word travels fast in this circle.  Thanks for restocking the supplies!" },
        ["text"] = "У нашому колі новини розлітаються швидко. Дякую, що поповнив запаси!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3576510729] = {
        ["english"] = { [1] = "Well, you're not going to sign recruitment papers or anything, but you are going to fight alongside him. You need to make sure Arthas culls Stratholme and defeats Mal'Ganis. Without Uther and Jaina around, he'll need all the help he can get. If you talk to Arthas, he'll put you to work destroying the forces of Mal'Ganis. Follow along until I can figure out what's going on with the Infinites. I'll contact you again when I know more." },
        ["text"] = "Ні, ти не підписуватимеш жодних паперів про вступ чи щось таке, але битимешся пліч-о-пліч із ним. Треба переконатися, що Артас очистить Стратгольм і переможе Мал'Ґаніса. Без Утера й Джайни йому знадобиться вся можлива допомога. Поговори з Артасом — він доручить тобі знищувати сили Мал'Ґаніса. Іди разом із ним, доки я не розберуся, що відбувається з Нескінченними. Я зв'яжуся з тобою, коли дізнаюся більше.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [728093059] = {
        ["english"] = { [1] = "We succeeded in taking the Sanctum.  We can continue to convert sentries and use them as guards at other tactical locations." },
        ["text"] = "Нам вдалося захопити Святилище. Тепер можемо й далі навертати вартових і використовувати їх для охорони інших стратегічних точок.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [102390455] = {
        ["english"] = { [1] = "Welcome!  If you need a place to rest, I can solve that problem." },
        ["text"] = "Вітаю! Якщо потрібне місце для відпочинку, я це влаштую.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4183045386] = {
        ["english"] = { [1] = "We have little to discuss, $c. Perhaps you should seek other, more like-minded individuals." },
        ["text"] = "Нам майже нема про що говорити, $c. Можливо, тобі варто пошукати інших, більш близьких за духом людей.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1352390065] = {
        ["english"] = { [1] = "Welcome to Camp Mojache, brave $C. How may I assist you this day?", [2] = "Welcome to Camp Mojache, brave $c.  How may I assist you this day?" },
        ["text"] = "Ласкаво просимо до табору Мохаче, хоробрий $C. Чим можу допомогти тобі сьогодні?",
        ["npcs"] = { [1] = 7854 },
        ["roles"] = { ["greeting"] = true },
    },
    [3527099834] = {
        ["english"] = { [1] = "We still go through the motions, but the feast of Winter Veil feels empty now. In Orgrimmar they have the true celebration." },
        ["text"] = "Ми й далі дотримуємося традицій, але Свято Зимового Покрову тепер здається порожнім. Справжнє святкування — в Орґріммарі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1608771258] = {
        ["english"] = { [1] = "What are you doing here? Arthas is at the entrance to Stratholme right now and you should be with him! Go!" },
        ["text"] = "Що ти тут робиш? Артас зараз біля входу до Стратгольма, і ти маєш бути з ним! Іди!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3650936074] = {
        ["english"] = { [1] = "Which battleground are you interested in?" },
        ["text"] = "Яке поле бою тебе цікавить?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2863481783] = {
        ["english"] = { [1] = "Whoa now, $c, Pele'keiki thinkin' that you not knowin' all that stuff be on its way to Silithus. Pele'keiki told the last of it be getting' there in less than $2113w days, and after that some misguided fool gonna ring the gong outside the Ahn'Qiraj gates to open 'em up and be startin' the war." },
        ["text"] = "Ого, $c, Пеле'кейкі думає, що ти не знаєш: усе те добро вже везуть до Силітуса. Пеле'кейкі сказали, що останнє прибуде менш ніж за $2113w днів, а потім якийсь заблудлий дурень вдарить у гонг біля брам Ан'Кіражу, відчинить їх і почне війну.",
        ["npcs"] = { [1] = 15508 },
        ["roles"] = { ["greeting"] = true },
    },
    [570609378] = {
        ["english"] = { [1] = "Well, you're just zooming right along! I can't teach you anything you don't already know, but Springspindle Fizzlegear sure can! You can find Springspindle in Ironforge. Good luck!" },
        ["text"] = "Та ти летиш уперед зі швидкістю ракети! Я вже не навчу тебе нічого нового, але Пружновісь Свистошестірня точно зможе! Знайдеш його в Стальгорні. Удачі!",
        ["npcs"] = { [1] = 5518 },
        ["roles"] = { ["greeting"] = true },
    },
    [1209987448] = {
        ["english"] = { [1] = "Well now, it would appear that we have some time on our hands. The Horde has completed its gathering tasks, and all is being prepared for final shipment to Silithus. We're only waiting on the Alliance to finish with theirs. You should go ask that silly, little ambassador of theirs how far along they are." },
        ["text"] = "Ну що ж, схоже, у нас з'явилося трохи вільного часу. Орда завершила збір, і все готують до останнього відправлення в Силітус. Ми лише чекаємо, поки Альянс закінчить своє. Іди запитай у їхнього дурненького маленького посла, як у них справи.",
        ["npcs"] = { [1] = 15525 },
        ["roles"] = { ["greeting"] = true },
    },
    [1247452778] = {
        ["english"] = { [1] = "Vesprystus' hippogryphs will bear you swiftly to your destination." },
        ["text"] = "Гіпогрифи Веспристуса швидко доправлять тебе до місця призначення.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [629842156] = {
        ["english"] = { [1] = "WAIT $c! Your search for the next boss isn't this way. Try another way." },
        ["text"] = "СТІЙ, $c! Наступного боса треба шукати не тут. Спробуй інший шлях.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3115843728] = {
        ["english"] = { [1] = "What are you after? Speak up. I'm not about to trust you with one of my Elekks until you prove your dedication and friendship to our people." },
        ["text"] = "Чого тобі треба? Говори. Я не довірю тобі жодного зі своїх елекків, доки ти не доведеш свою відданість і дружбу до нашого народу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [611048824] = {
        ["english"] = { [1] = "Where was I? Oh yes, so we were captured. My elite guardsmen were executed on the spot. They spared me and took the princess away by way of ram. I was taken to the detention halls of the Slag Pit and then transferred to this prison.$B$BI can only assume I am still alive because they wish to extract a ransom for my pitiful life. Or maybe out of cruelty, as a way to let me forever play back the events that transpired in my mind. Regret is the cruelest jailor of all, $r." },
        ["text"] = "На чому я зупинився? А, так, нас схопили. Моїх елітних вартових стратили на місці. Мене пощадили, а принцесу повезли на барані. Мене кинули до камер утримання в Шлаковій Ямі, а потім перевели до цієї в'язниці.$B$BМожу лише припустити, що я досі живий, бо вони хочуть отримати викуп за моє жалюгідне життя. А може, це просто жорстокість — щоб я вічно прокручував у голові те, що сталося. Каяття — найжорстокіший тюремник, $r.",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["greeting"] = true },
    },
    [3174192465] = {
        ["english"] = { [1] = "Where is Elder Starsong?" },
        ["text"] = "Де старійшина Зореспів?",
        ["npcs"] = { [1] = 15563, [2] = 15565, [3] = 15576, [4] = 15577, [5] = 15596 },
        ["roles"] = { ["reply"] = true },
    },
    [3958296317] = {
        ["english"] = { [1] = "Where the Eye of the Prophets rested for millenia, only an empty niche remains." },
        ["text"] = "Там, де тисячоліттями лежало Око Пророків, тепер лишилася тільки порожня ніша.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2760162981] = {
        ["english"] = { [1] = "Where is the key to this lock?" },
        ["text"] = "Де ключ від цього замка?",
        ["npcs"] = { [1] = 2239 },
        ["roles"] = { ["reply"] = true },
    },
    [695747404] = {
        ["english"] = { [1] = "We will ravage the living... I mean the Scourge, of course.$B" },
        ["text"] = "Ми винищимо живих... тобто Скару, звісно.$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3167506001] = {
        ["english"] = { [1] = "What's a young $c like you out visiting an old farmer like me?" },
        ["text"] = "Що такий молодий $c, як ти, робить у гостях у такого старого фермера, як я?",
        ["npcs"] = { [1] = 6586 },
        ["roles"] = { ["greeting"] = true },
    },
    [1844132397] = {
        ["english"] = { [1] = "Ugh... these pests keep me busy night and day! Haven't you seen them?$B$BI wish I could just jump down a pipe to get away from them..." },
        ["text"] = "Уф... ці шкідники не дають мені спокою ні вдень, ні вночі! Невже ти їх не бачив?$B$BОт би просто стрибнути в трубу й утекти від них...",
        ["npcs"] = { [1] = 9118 },
        ["roles"] = { ["greeting"] = true },
    },
    [2180272172] = {
        ["english"] = { [1] = "Where is Elder Windtotem?" },
        ["text"] = "Де старійшина Вітрототем?",
        ["npcs"] = { [1] = 15572, [2] = 15575, [3] = 15579, [4] = 15580, [5] = 15588, [6] = 15597, [7] = 15604 },
        ["roles"] = { ["reply"] = true },
    },
    [127106299] = {
        ["english"] = { [1] = "Where is Elder Windrun?" },
        ["text"] = "Де старійшина Вітробіг?",
        ["npcs"] = { [1] = 15566, [2] = 15594, [3] = 15602, [4] = 15607 },
        ["roles"] = { ["reply"] = true },
    },
    [4261064448] = {
        ["english"] = { [1] = "Where is Elder Thunderhorn?" },
        ["text"] = "Де старійшина Громоріг?",
        ["npcs"] = { [1] = 15570, [2] = 15573, [3] = 15578, [4] = 15586, [5] = 15599 },
        ["roles"] = { ["reply"] = true },
    },
    [1417291251] = {
        ["english"] = { [1] = "With a good portion of their demons slain, the Legion will think twice about attacking our lumber camp again.  However, I still sense demonic evil stirring." },
        ["text"] = "Коли добру частину їхніх демонів убито, Легіон двічі подумає, перш ніж знову нападати на наш лісозаготівельний табір. Однак я досі відчуваю, як ворушиться демонічне зло.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [898823599] = {
        ["english"] = { [1] = "Welcome to the front lines, $c.  While politicians may connive and scheme amongst themselves, they'll find no such luxury afforded to them here.  This is the Bulwark, and we fight for our continued survival on a daily basis here.$B$BIf you've come here looking for a chance to prove yourself as a hero, then you'll find plenty of opportunities to do so... especially as we push towards Andorhal and whatever malign force that controls the Scourge there." },
        ["text"] = "Ласкаво просимо на передову, $c. Політики можуть плести інтриги й змови між собою, але тут такої розкоші їм не буде. Це Бастіон, і тут ми щодня боремося за своє виживання.$B$BЯкщо ти прийшов сюди, щоб довести свою героїчність, нагод буде вдосталь... особливо коли ми просуваємося до Андорала й тієї зловісної сили, що керує там Скарою.",
        ["npcs"] = { [1] = 10837 },
        ["roles"] = { ["greeting"] = true },
    },
    [3578211040] = {
        ["english"] = { [1] = "Where is Elder Stonespire?" },
        ["text"] = "Де старійшина Кам'яний Шпиль?",
        ["npcs"] = { [1] = 15603, [2] = 15605, [3] = 15606 },
        ["roles"] = { ["reply"] = true },
    },
    [232033025] = {
        ["english"] = { [1] = "Where is Elder Stonefort?" },
        ["text"] = "Де старійшина Кам'яна Твердиня?",
        ["npcs"] = { [1] = 15567 },
        ["roles"] = { ["reply"] = true },
    },
    [1780698706] = {
        ["english"] = { [1] = "Yeah, sure, go ahead and tell ol' Greatfather Winter what you'd like for this Winter's Veil.$B$BHo ho hurry up." },
        ["text"] = "Так-так, кажи старому Дідусеві Зимі, що хочеш отримати на цей Зимовий Покров.$B$BГо-го, тільки швидше.",
        ["npcs"] = { [1] = 13444, [2] = 13445 },
        ["roles"] = { ["greeting"] = true },
    },
    [3977633150] = {
        ["english"] = { [1] = "Um... I think you're a little too big to ride a Mechano-strider there, $g mister : ma'am;.  You'd likely crush the finely tuned servo-balancers!" },
        ["text"] = "Ем... думаю, ти трохи завеликий для механострайдера, $g пане : пані;. Ти ж розчавиш його тонко налаштовані сервобалансири!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4094336380] = {
        ["english"] = { [1] = "Where are we battling the Scourge?" },
        ["text"] = "Де ми б'ємося зі Скарою?",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["reply"] = true },
    },
    [1559177266] = {
        ["english"] = { [1] = "Welcome back to the Great Forge, $N. Ye come to visit an old Dwarf or do ye think yer ready for the next step in yer training?" },
        ["text"] = "З поверненням до Великої Кузні, $N. Прийшов провідати старого дворфа чи гадаєш, що вже готовий до наступного етапу навчання?",
        ["npcs"] = { [1] = 5164 },
        ["roles"] = { ["greeting"] = true },
    },
    [3962534044] = {
        ["english"] = { [1] = "Where is Elder Splitrock?" },
        ["text"] = "Де старійшина Розколота Скеля?",
        ["npcs"] = { [1] = 15581, [2] = 15587 },
        ["roles"] = { ["reply"] = true },
    },
    [2625383482] = {
        ["english"] = { [1] = "Where is Elder Snowcrown?" },
        ["text"] = "Де старійшина Сніжна Корона?",
        ["npcs"] = { [1] = 15568, [2] = 15592, [3] = 15594, [4] = 15602, [5] = 15607 },
        ["roles"] = { ["reply"] = true },
    },
    [3386130277] = {
        ["english"] = { [1] = "Well met, friend!" },
        ["text"] = "Вітаю, друже!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3190024433] = {
        ["english"] = { [1] = "Weve located the mark, commander. Ya-six and i have been seperated. Requesting backup." },
        ["text"] = "Ми знайшли ціль, командире. Я-Шість і я розділилися. Просимо підкріплення.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1227299672] = {
        ["english"] = { [1] = "What discoveries?" },
        ["text"] = "Які відкриття?",
        ["npcs"] = { [1] = 4949 },
        ["roles"] = { ["reply"] = true },
    },
    [4248143002] = {
        ["english"] = { [1] = "When lightning strikes the ocean why don't all the fish die?" },
        ["text"] = "Коли блискавка б'є в океан, чому вся риба не помирає?",
        ["npcs"] = { [1] = 14444 },
        ["roles"] = { ["greeting"] = true },
    },
    [1233133874] = {
        ["english"] = { [1] = "Well, if it isn't $N!  It's good to see you again; I cannot express my gratitude enough at the help that you've given me and my invention work to date.$B$BWhat can I do for you today?" },
        ["text"] = "О, та це ж $N! Радий знову тебе бачити; не можу достатньо висловити вдячність за всю допомогу, яку ти досі надав мені й моїм винаходам.$B$BЧим можу допомогти сьогодні?",
        ["npcs"] = { [1] = 7406 },
        ["roles"] = { ["greeting"] = true },
    },
    [2644093326] = {
        ["english"] = { [1] = "We must re-establish our stranglehold on these mines!" },
        ["text"] = "Ми повинні знову встановити залізну хватку над цими копальнями!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1908724099] = {
        ["english"] = { [1] = "We discovered these proto-drakes at the Bronze Dragonshrine in the Dragonblight. We knew at once that they were kin - our blood from ages past.$B$BMy apologies, $c. You are probably confused. I am Penumbrius of the bronze dragonflight. I have taken this form out of convenience. It is much easier to communicate and live amongst mortals while in the mortal guise.$B$BHow can I help you?$B" },
        ["text"] = "Ми знайшли цих протодраків біля Бронзового святилища драконів на Драконовому кладовищі. Одразу зрозуміли, що вони наші родичі — наша кров із прадавніх часів.$B$BПерепрошую, $c. Ти, мабуть, спантеличений. Я Пенумбрій із бронзової зграї. Я прийняв цю подобу заради зручності. У смертній подобі набагато легше спілкуватися й жити серед смертних.$B$BЧим можу допомогти?$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3288343630] = {
        ["english"] = { [1] = "Where is Elder Silvervein?" },
        ["text"] = "Де старійшина Срібна Жила?",
        ["npcs"] = { [1] = 15567, [2] = 15569 },
        ["roles"] = { ["reply"] = true },
    },
    [4139945412] = {
        ["english"] = { [1] = "Where would you like to fly to?" },
        ["text"] = "Куди бажаєш полетіти?",
        ["npcs"] = { [1] = 931, [2] = 1387, [3] = 1571, [4] = 2299, [5] = 2389, [6] = 2409, [7] = 2432, [8] = 2835, [9] = 2851, [10] = 2861, [11] = 4267, [12] = 4312, [13] = 4317, [14] = 4319, [15] = 4321, [16] = 4407, [17] = 4415, [18] = 6026, [19] = 6706, [20] = 6726, [21] = 7823, [22] = 7824, [23] = 8018, [24] = 8019, [25] = 8020, [26] = 8609, [27] = 8610, [28] = 10583, [29] = 10897, [30] = 11138, [31] = 11139, [32] = 11899, [33] = 11901, [34] = 12577, [35] = 12578, [36] = 12596, [37] = 12616, [38] = 12617, [39] = 12636, [40] = 12740, [41] = 13177, [42] = 15177, [43] = 15178, [44] = 16227 },
        ["roles"] = { ["greeting"] = true },
    },
    [4116163732] = {
        ["english"] = { [1] = "What kin I do for ye, $n?" },
        ["text"] = "Чим можу допомогти, $n?",
        ["npcs"] = { [1] = 5166 },
        ["roles"] = { ["greeting"] = true },
    },
    [2415382707] = {
        ["english"] = { [1] = "Welcome, $c!  I hope you aren't afraid of heights!$b$bI've got a practice parachute for you.  These chutes are for quick landings.  If you want to gently soar to the ground, use a mount.  If you want action and an adrenaline rush, you fall.  At the last possible moment you use your chute.  That's how these were made.  Quick action!  Are you ready for some quick action?$b$bThe chute only lasts a few seconds.  So you'll need to time it just right.  I'm not sure you can handle it, $c.  I'd like to see you prove me wrong." },
        ["text"] = "Ласкаво просимо, $c! Сподіваюся, висоти ти не боїшся!$b$bУ мене є тренувальний парашут. Ці парашути створені для швидких приземлень. Якщо хочеш плавно спуститися — використовуй верхову тварину. Якщо хочеш дії та адреналіну — падай. В останню можливу мить розкривай парашут. Саме для цього вони й створені. Швидка дія! Готовий до швидкої дії?$b$bПарашут діє лише кілька секунд. Тож треба ідеально розрахувати час. Не впевнений, що ти впораєшся, $c. Доведи, що я помиляюся.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2126287560] = {
        ["english"] = { [1] = "Well done, soldier. A few more and our stables will be overflowing with mounts for the cavalry to ride into combat!" },
        ["text"] = "Добре зроблено, солдате. Ще кілька — і наші стайні будуть переповнені верховими тваринами для кавалерії!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4078103233] = {
        ["english"] = { [1] = "When I first saw the undead, I wept, for I could not imagine their horror and loneliness. The Earth Mother spoke to me then; she sang in my blood. And she told me, \"Save them.\"" },
        ["text"] = "Коли я вперше побачив невмерлих, то заплакав, бо не міг уявити їхній жах і самотність. Тоді до мене промовила Мати-Земля; вона співала в моїй крові. І сказала: «Врятуй їх». ",
        ["npcs"] = { [1] = 3009 },
        ["roles"] = { ["greeting"] = true },
    },
    [3889846469] = {
        ["english"] = { [1] = "Very sad to think what has befallen those poor undead souls.  You can find Archmage Shymm reflecting near the Pools of Vision under the Spirit Rise." },
        ["text"] = "Дуже сумно думати про те, що сталося з тими бідними душами невмерлих. Архімага Шимма знайдеш біля Озер Видінь під Вершиною Духів.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [3004546354] = {
        ["english"] = { [1] = "Where is Elder Ragetotem?" },
        ["text"] = "Де старійшина Лютототем?",
        ["npcs"] = { [1] = 15578, [2] = 15583, [3] = 15584, [4] = 15586 },
        ["roles"] = { ["reply"] = true },
    },
    [269708290] = {
        ["english"] = { [1] = "We must eliminate the elves and their cowardly Alliance from Warsong Gulch.  Go to the Hall of the Brave in the Valley of Honor and speak with Brakgul Deathbringer if you have what it takes to aid the Horde.", [2] = "We must eliminate the elves and their cowardly Alliance from Warsong Gulch. Go to the Hall of the Brave in the Valley of Honor and speak with Brakgul Deathbringer if you have what it takes to aid the Horde." },
        ["text"] = "Ми повинні вигнати ельфів і їхній боягузливий Альянс з Ущелини Пісні Війни. Вирушай до Зали Хоробрих у Долині Честі й поговори з Бракґулом Смертеносцем, якщо маєш силу допомогти Орді.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3684095597] = {
        ["english"] = { [1] = "While we have no Alchemy Trainer here in Bloodhoof Village, there is one in Thunder Bluff to the north.  Follow the road there and ask one of the Bluffwatchers for directions when you get to the top." },
        ["text"] = "У селищі Криваве Копито немає наставника алхімії, але один є в Громовому Бескиді на півночі. Іди дорогою туди, а коли піднімешся нагору, запитай дорогу у Вартового Бескиду.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [1773329538] = {
        ["english"] = { [1] = "Where is Elder Nightwind?" },
        ["text"] = "Де старійшина Нічний Вітер?",
        ["npcs"] = { [1] = 15574, [2] = 15600, [3] = 15601, [4] = 15605, [5] = 15606 },
        ["roles"] = { ["reply"] = true },
    },
    [2726359930] = {
        ["english"] = { [1] = "What's needed for the cauldron at Gahrron's Withering?" },
        ["text"] = "Що потрібно для котла в Гаарроновому В'яненні?",
        ["npcs"] = { [1] = 11056, [2] = 11057 },
        ["roles"] = { ["reply"] = true },
    },
    [3356412598] = {
        ["english"] = { [1] = "Where is Elder Morningdew?" },
        ["text"] = "Де старійшина Ранкова Роса?",
        ["npcs"] = { [1] = 15581, [2] = 15582, [3] = 15584, [4] = 15587, [5] = 15588, [6] = 15597 },
        ["roles"] = { ["reply"] = true },
    },
    [884537433] = {
        ["english"] = { [1] = "We have seeded Darkmoon Cards around the world to see if any worthy individuals could complete a set of any of the four suits.    If you manage to collect all eight cards of one of the suits we will reward you with one of the Greater Darkmoon cards that functions as a powerful trinket as well as a link to the Darkmoon Faire." },
        ["text"] = "Ми розсіяли по всьому світу карти ярмарку Темного Місяця, щоб перевірити, чи знайдуться гідні люди, здатні зібрати повний комплект однієї з чотирьох мастей. Якщо збереш усі вісім карт однієї масті, ми нагородимо тебе однією з Великих карт Темного Місяця, яка слугує могутньою дрібничкою та водночас зв'язком із ярмарком Темного Місяця.",
        ["npcs"] = { [1] = 14847 },
        ["roles"] = { ["greeting"] = true },
    },
    [3484784512] = {
        ["english"] = { [1] = "Well what do you know, this is Children's Week!  What can I do to help?" },
        ["text"] = "О, дивина, та це ж Дитячий тиждень! Чим можу допомогти?",
        ["npcs"] = { [1] = 14450, [2] = 14451 },
        ["roles"] = { ["reply"] = true },
    },
    [123521597] = {
        ["english"] = { [1] = "What do you think of Dadanga?", [2] = "What do you think of Dadanga?\010" },
        ["text"] = "Що ти думаєш про Даданґу?",
        ["npcs"] = { [1] = 9272 },
        ["roles"] = { ["reply"] = true },
    },
    [1411214532] = {
        ["english"] = { [1] = "Where is Elder Morndeep?" },
        ["text"] = "Де старійшина Ранкова Глибина?",
        ["npcs"] = { [1] = 15567 },
        ["roles"] = { ["reply"] = true },
    },
    [2537817052] = {
        ["english"] = { [1] = "Where is Elder Moonstrike?" },
        ["text"] = "Де старійшина Місячний Удар?",
        ["npcs"] = { [1] = 15559, [2] = 15561, [3] = 15564, [4] = 15566, [5] = 15568, [6] = 15592, [7] = 15602 },
        ["roles"] = { ["reply"] = true },
    },
    [2118585032] = {
        ["english"] = { [1] = "What's the worst that could happen?" },
        ["text"] = "Що найгірше може статися?",
        ["npcs"] = { [1] = 3836 },
        ["roles"] = { ["reply"] = true },
    },
    [148889955] = {
        ["english"] = { [1] = "Tragically, it was Thrall's wisdom that finally sealed the bond between the demon lord and his minions. It was Trebor's regiment that served as the catalyst to unite the demon lord, the shadowsworn sects and the ogres. The lure of nearly unlimited power and the granting of immortal shock troops to each respective leader sealed the deal in blood.\010" },
        ["text"] = "На жаль, саме мудрість Тралла зрештою скріпила союз між володарем демонів і його посіпаками. Полк Требора став каталізатором, що об'єднав володаря демонів, секти Тінеклятих та огрів. Обіцянка майже безмежної сили й дарування кожному ватажкові безсмертних ударних загонів скріпили угоду кров'ю.\010",
        ["npcs"] = { [1] = 7783 },
        ["roles"] = { ["greeting"] = true },
    },
    [4186132858] = {
        ["english"] = { [1] = "Uhnhh.... Don't... bother with me.$b$bI am... finished..." },
        ["text"] = "У-у-у.... Не... зважай на мене.$b$bМені... кінець...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1101139277] = {
        ["english"] = { [1] = "We know that the wyrmcultists are massing on the other side of the tunnel.  We'll make our stand here." },
        ["text"] = "Ми знаємо, що по той бік тунелю збираються культисти змієкрилів. Тут ми й дамо їм бій.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1263855612] = {
        ["english"] = { [1] = "What do you wish to know of Jewelcrafting?" },
        ["text"] = "Що ти хочеш знати про ювелірну справу?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2609399329] = {
        ["english"] = { [1] = "Unfortunately you are not yet strong enough to survive in Warsong Gulch, $c." },
        ["text"] = "На жаль, ти ще недостатньо сильний, щоб вижити в Ущелині Пісні Війни, $c.",
        ["npcs"] = { [1] = 15105 },
        ["roles"] = { ["greeting"] = true },
    },
    [1894191843] = {
        ["english"] = { [1] = "When I scowled at you before you became da new king... um... I was just joking.$B$BYeah!" },
        ["text"] = "Коли я насупився на тебе до того, як ти став новим королем... е-е... я просто жартував.$B$BАга!",
        ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 },
        ["roles"] = { ["greeting"] = true },
    },
    [3271233273] = {
        ["english"] = { [1] = "Very clever how you got in here like that, $N.$B$BWhat? Surprised that I know your name? I'm a demon, that's what we do. I also know your true name, so you'd better buy something expensive." },
        ["text"] = "Дуже кмітливо ти сюди пробрався, $N.$B$BЩо? Дивуєшся, що я знаю твоє ім'я? Я демон — ми таке вміємо. Я навіть знаю твоє справжнє ім'я, тож краще купи щось дороге.",
        ["npcs"] = { [1] = 16015 },
        ["roles"] = { ["greeting"] = true },
    },
    [2935349638] = {
        ["english"] = { [1] = "Welcome to Falcon Watch, $c. I see to the needs of the pilgrims and help them in continuing their long journey. If you haven't yet undertaken the pilgrimage, I can provide you with the information you will need." },
        ["text"] = "Ласкаво просимо до Соколиного Дозору, $c. Я дбаю про потреби прочан і допомагаю їм продовжувати довгу подорож. Якщо ти ще не вирушив у паломництво, я можу надати потрібну інформацію.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1708637540] = {
        ["english"] = { [1] = "Well then... show me the tribute!" },
        ["text"] = "Ну ж бо... показуй данину!",
        ["npcs"] = { [1] = 14353 },
        ["roles"] = { ["reply"] = true },
    },
    [1515137154] = {
        ["english"] = { [1] = "What happened to the staff?" },
        ["text"] = "Що сталося з посохом?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2388121366] = {
        ["english"] = { [1] = "Who has the fastest car?  Who knows?!?" },
        ["text"] = "У кого найшвидша машина? Хто знає?!?",
        ["npcs"] = { [1] = 4419 },
        ["roles"] = { ["greeting"] = true },
    },
    [2227976940] = {
        ["english"] = { [1] = "What's there to ask? He's a monkey you crazy fool. Anyhow, so yea, the monkey went into a frenzy after seein' ol' Brann flop into the sand face first. Nothin' the night elf could do was stopping Glibb here from poundin' on her noggin." },
        ["text"] = "Що тут питати? Це мавпа, ти божевільний дурню. Так от, мавпа оскаженіла, коли побачила, як старий Бранн гепнувся обличчям у пісок. Що б та нічна ельфійка не робила, ніщо не могло зупинити Ґлібба, який гамселив її по макітрі.",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["greeting"] = true },
    },
    [3256884681] = {
        ["english"] = { [1] = "Well then, I'll give the signal to Tirion when you are ready to go." },
        ["text"] = "Ну що ж, коли будеш готовий, я дам Тіріону сигнал вирушати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [537557438] = {
        ["english"] = { [1] = "Where is Elder Graveborn?" },
        ["text"] = "Де старійшина Могилородний?",
        ["npcs"] = { [1] = 15561, [2] = 15564, [3] = 15566, [4] = 15594, [5] = 15602 },
        ["roles"] = { ["reply"] = true },
    },
    [1528421837] = {
        ["english"] = { [1] = "We've done it, $N.  Mar'nah has learned how to transmute very special gems.  And I've learned how to work them." },
        ["text"] = "Ми це зробили, $N. Мар'на навчилася трансмутувати дуже особливі самоцвіти. А я навчився їх обробляти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1019676038] = {
        ["english"] = { [1] = "What are you talking about, mage?" },
        ["text"] = "Про що ти говориш, магу?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3001638001] = {
        ["english"] = { [1] = "We have some supplies, but not many.  We'll need a lot more in order to send a ground assault into the Field of Strife." },
        ["text"] = "У нас є трохи припасів, але небагато. Потрібно значно більше, щоб відправити наземний наступ на Поле Чвар.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1689911597] = {
        ["english"] = { [1] = "We need a great number of copper bars, $c. The upcoming war at Ahn'Qiraj is going to use up a lot of metal for weapons, armor and whatnot. I'm told that the Horde alone needs to collect $1998w copper bars. As of now we have $2018w." },
        ["text"] = "Нам потрібна величезна кількість мідних зливків, $c. Майбутня війна за Ан'Кіраж поглине безліч металу на зброю, обладунки й усе інше. Кажуть, самій лише Орді треба зібрати $1998w мідних зливків. Наразі в нас є $2018w.",
        ["npcs"] = { [1] = 15459 },
        ["roles"] = { ["greeting"] = true },
    },
    [296211952] = {
        ["english"] = { [1] = "Where is Elder Farwhisper?" },
        ["text"] = "Де старійшина Далекий Шепіт?",
        ["npcs"] = { [1] = 15566, [2] = 15592 },
        ["roles"] = { ["reply"] = true },
    },
    [1894162053] = {
        ["english"] = { [1] = "Where is Elder Ezra Wheathoof?" },
        ["text"] = "Де старійшина Езра Пшеничне Копито?",
        ["npcs"] = { [1] = 15564, [2] = 15575, [3] = 15579, [4] = 15582 },
        ["roles"] = { ["reply"] = true },
    },
    [849275203] = {
        ["english"] = { [1] = "We have quite the feast for you friend." },
        ["text"] = "Для тебе в нас справжній бенкет, друже.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1398156093] = {
        ["english"] = { [1] = "We're always eager for more flight data!  Where do you want to go?" },
        ["text"] = "Ми завжди раді новим польотним даним! Куди хочеш вирушити?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3745383559] = {
        ["english"] = { [1] = "Truly an amazing sword, don't you think? That's no weapon of dwarven make, no, it's far more ancient than that.$B$BThese Sunreaver and Silver Covenant representatives seem intent on getting to the bottom of the mystery. I'm already working on a report for Brann." },
        ["text"] = "Надзвичайний меч, чи не так? Це точно не дворфійська робота — ні, він значно давніший.$B$BСхоже, представники Сонячних Викрадачів і Срібного Союзу сповнені рішучості докопатися до суті цієї таємниці. Я вже готую звіт для Бранна.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [40390598] = {
        ["english"] = { [1] = "Yeah, I'll show you a few things. We'll see how you do, maybe you'll surprise me!" },
        ["text"] = "Так, я покажу тобі кілька речей. Подивимося, як упораєшся — може, ще здивуєш мене!",
        ["npcs"] = { [1] = 3494, [2] = 10993 },
        ["roles"] = { ["greeting"] = true },
    },
    [2246781654] = {
        ["english"] = { [1] = "We serve Thorim, sister." },
        ["text"] = "Ми служимо Торіму, сестро.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2224983571] = {
        ["english"] = { [1] = "Well, well, what do you know, sparky, we did it. Everything's collected and ready to go. We're just waiting on those Horde yahoos now, and once they get their act together it's off to the races at Ahn'Qiraj!" },
        ["text"] = "Ну що, і хто б міг подумати, Іскрику, ми впоралися. Усе зібрано й готове. Тепер лише чекаємо на тих дурників з Орди, і щойно вони зберуться докупи — почнеться веселощі в Ан'Кіражі!",
        ["npcs"] = { [1] = 15431 },
        ["roles"] = { ["greeting"] = true },
    },
    [1202383095] = {
        ["english"] = { [1] = "Where is Elder Darkhorn?" },
        ["text"] = "Де старійшина Темний Ріг?",
        ["npcs"] = { [1] = 15564, [2] = 15572, [3] = 15580, [4] = 15582 },
        ["roles"] = { ["reply"] = true },
    },
    [423728139] = {
        ["english"] = { [1] = "Watch your step, $r. We of the Brotherhood of the Light are not as lenient as our brethren when it comes to meting justice to those that would do this world wrong.$B$BWoe unto those that would anger Korfax.$B$BNow if you have no business with me or the other members of the Brotherhood, please leave so that we may continue our meeting. \010" },
        ["text"] = "Дивися під ноги, $r. Ми, Братство Світла, не такі поблажливі, як наші брати, коли йдеться про покарання тих, хто чинить цьому світові зло.$B$BГоре тому, хто розгніває Корфакса.$B$BА тепер, якщо в тебе немає справ до мене чи інших членів Братства, будь ласка, залиш нас, щоб ми могли продовжити нараду. \010",
        ["npcs"] = { [1] = 16115 },
        ["roles"] = { ["greeting"] = true },
    },
    [269567155] = {
        ["english"] = { [1] = "Well there's a gryphon master up in Stormwind if you need to fly somewhere.  You should be able to see the gryphons landing on your right as you walk through the Valley of Heroes." },
        ["text"] = "У Штормовії є доглядач грифонів, якщо тобі треба кудись полетіти. Коли проходитимеш Долиною Героїв, праворуч має бути видно, як грифони приземляються.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [1576853741] = {
        ["english"] = { [1] = "Uh huh.  Unholies in War Quarter standing around main building on outer ring of city." },
        ["text"] = "Ага. Нечестивці у Військовому кварталі, біля головної будівлі на зовнішньому кільці міста.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3095733463] = {
        ["english"] = { [1] = "Where is Elder Darkcore?" },
        ["text"] = "Де старійшина Темне Ядро?",
        ["npcs"] = { [1] = 15568, [2] = 15579, [3] = 15580, [4] = 15594 },
        ["roles"] = { ["reply"] = true },
    },
    [4048151671] = {
        ["english"] = { [1] = "Trick or Treat!" },
        ["text"] = "Цукерка чи капость!",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [3070143212] = {
        ["english"] = { [1] = "Which class trainer are you looking for?" },
        ["text"] = "Якого наставника класу ти шукаєш?",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3178860488] = {
        ["english"] = { [1] = "Well done! Your understanding of potions is coming along nicely." },
        ["text"] = "Молодець! Твоє розуміння зіль помітно покращується.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3939149735] = {
        ["english"] = { [1] = "Where is Elder Bladeleaf?" },
        ["text"] = "Де старійшина Клинолист?",
        ["npcs"] = { [1] = 15598, [2] = 15600 },
        ["roles"] = { ["reply"] = true },
    },
    [2396424059] = {
        ["english"] = { [1] = "We are united in cause, $r. An ancient evil threatens to extinguish all life on Kalimdor and consume the world with its depravity... Its hatred of all things born of the great Shapers: The eternal Titans.$B$BWe are the first and the last lines of defense against the armies of C'Thun. If we do not rise up and strike at our enemy, our enemy will surely destroy us.$B$BThe war effort needs you!" },
        ["text"] = "Нас об'єднує спільна мета, $r. Давнє зло загрожує згасити все життя в Калімдорі й поглинути світ своєю мерзотою... Воно ненавидить усе, що створили великі Творці — вічні титани.$B$BМи — перша й остання лінія оборони проти армій К'Туна. Якщо ми не піднімемося й не вдаримо ворога, він неодмінно знищить нас.$B$BВійськові зусилля потребують тебе!",
        ["npcs"] = { [1] = 15458, [2] = 15701 },
        ["roles"] = { ["greeting"] = true },
    },
    [1513093227] = {
        ["english"] = { [1] = "Welcome to the Explorer's League.  If you need information, and it is in book form, then I might be able to help you out." },
        ["text"] = "Ласкаво просимо до Ліги дослідників. Якщо тобі потрібна інформація і вона існує у вигляді книги, можливо, я зможу допомогти.",
        ["npcs"] = { [1] = 2916 },
        ["roles"] = { ["greeting"] = true },
    },
    [1943112301] = {
        ["english"] = { [1] = "What abilities do Emerald Drakes have?" },
        ["text"] = "Які здібності мають смарагдові драки?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2131184714] = {
        ["english"] = { [1] = "Until you have mastered the Apprentice level of Jewelcrafting we shall not speak again." },
        ["text"] = "Поки не опануєш учнівський рівень ювелірної справи, ми більше не говоритимемо.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2297767] = {
        ["english"] = { [1] = "Where is Elder Bellowrage?" },
        ["text"] = "Де старійшина Ревогнів?",
        ["npcs"] = { [1] = 15593 },
        ["roles"] = { ["reply"] = true },
    },
    [1632956095] = {
        ["english"] = { [1] = "We have more than one enemy in Silithus, $N.$B$BWhile everyone's attention is focused on the silithid, my big brother and I have been keeping a close eye on the Twilight's Hammer crazies.\010\010" },
        ["text"] = "У Силітусі в нас не один ворог, $N.$B$BПоки увага всіх прикута до силітидів, ми зі старшим братом пильно стежимо за божевільними з Молота Сутінків.\010\010",
        ["npcs"] = { [1] = 15306 },
        ["roles"] = { ["greeting"] = true },
    },
    [1830579236] = {
        ["english"] = { [1] = "Welcome to our camp, $c. You're free to rest here if you'd like." },
        ["text"] = "Ласкаво просимо до нашого табору, $c. Можеш відпочити тут, якщо хочеш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1903986648] = {
        ["english"] = { [1] = "When mounted on the back of a wind rider, one sees that its reputation for strength and speed is well earned." },
        ["text"] = "Коли сидиш на спині вітрокрила, одразу розумієш: його слава про силу й швидкість цілком заслужена.",
        ["npcs"] = { [1] = 2995 },
        ["roles"] = { ["greeting"] = true },
    },
    [1786825028] = {
        ["english"] = { [1] = "Where else are we battling the Scourge?" },
        ["text"] = "Де ще ми б'ємося зі Скарою?",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["reply"] = true },
    },
    [1034048253] = {
        ["english"] = { [1] = "Where did you think the Wind Rider Master would be?  Head to the top of The Sky Tower in the Valley of Strength!" },
        ["text"] = "А де, по-твоєму, має бути доглядач вітрокрилів? Іди на вершину Небесної Вежі в Долині Сили!",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1392072336] = {
        ["english"] = { [1] = "Ye have the look of a Blacksmith to ye. Soot under the nails, steel in yer bones. Aye, very much the blood of a Blacksmith in yer veins. Which means ye've come to me looking to learn a thing or two, well $g lad : lass; grab a hammer. Let's see what I can teach ye." },
        ["text"] = "Виглядаєш як коваль. Сажа під нігтями, сталь у кістках. Так, у твоїх жилах точно тече ковальська кров. Значить, прийшов до мене чогось навчитися. Ну що, $g хлопче : дівчино;, бери молот. Подивімося, чого я можу тебе навчити.",
        ["npcs"] = { [1] = 4258 },
        ["roles"] = { ["greeting"] = true },
    },
    [1546383703] = {
        ["english"] = { [1] = "We have excess supplies, but not many.  We'll need a lot more before we can send a ground assault into the Field of Strife." },
        ["text"] = "У нас є зайві припаси, але небагато. Потрібно ще значно більше, перш ніж ми зможемо відправити наземний наступ на Поле Чвар.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2482459257] = {
        ["english"] = { [1] = "Welcome to the Faire young one!   We have collected wonders from all over the world for your perusal.   Oh and please let me know if you manage to collect a set of the lesser darkmoon cards, as the master...I mean I would be keenly interested in them." },
        ["text"] = "Ласкаво просимо на ярмарок, юначе! Ми зібрали дива з усього світу для твого огляду. О, і неодмінно скажи мені, якщо зумієш зібрати комплект молодших карт Темного Місяця, адже господар... тобто я був би ними вкрай зацікавлений.",
        ["npcs"] = { [1] = 14847 },
        ["roles"] = { ["greeting"] = true },
    },
    [4044768175] = {
        ["english"] = { [1] = "Well met, $c. Your arrival in Thrallmar could not have occurred at a better time. The warchief is depending on us, since he cannot be here himself." },
        ["text"] = "Вітаю, $c. Ти прибув до Траллмара якраз вчасно. Вождь покладається на нас, бо сам не може бути тут.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3317639452] = {
        ["english"] = { [1] = "Where can I send you today $c?" },
        ["text"] = "Куди відправити тебе сьогодні, $c?",
        ["npcs"] = { [1] = 10378 },
        ["roles"] = { ["greeting"] = true },
    },
    [3513064379] = {
        ["english"] = { [1] = "We'll get to the bottom of this massacre if it's the last thing we do!" },
        ["text"] = "Ми докопаємося до правди про цю різанину, навіть якщо це буде останнє, що ми зробимо!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1846339584] = {
        ["english"] = { [1] = "What kind of services?" },
        ["text"] = "Які саме послуги?",
        ["npcs"] = { [1] = 16135 },
        ["roles"] = { ["reply"] = true },
    },
    [367014067] = {
        ["english"] = { [1] = "With new enemies on our doorsteps, we must not allow our ancient enemies to take advantage of our situation!" },
        ["text"] = "Коли нові вороги вже біля наших дверей, ми не можемо дозволити давнім ворогам скористатися нашим становищем!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [244852225] = {
        ["english"] = { [1] = "We got the final barrier blockin' entry to Frostwing Halls down, $g lad:lass;. Only Sindragosa stands between the Lich King and divine retribution! What are ye waitin' for?!" },
        ["text"] = "Ми зняли останній бар'єр, що перегороджував вхід до Залів Крижаного Крила, $g хлопче:дівчино;. Лише Синдраґоса стоїть між Королем-Лічем і божественною відплатою! Чого ж ти чекаєш?!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3068726379] = {
        ["english"] = { [1] = "What are these Tonk Control Consoles?" },
        ["text"] = "Що це за пульти керування танками?",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["reply"] = true },
    },
    [904821538] = {
        ["english"] = { [1] = "We are here to help." },
        ["text"] = "Ми тут, щоб допомогти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [546455432] = {
        ["english"] = { [1] = "We've come to the Ruuan Weald to see if we can reestablish the balance of nature to these mountains.$B$BThe interference of the arakkoa and the wyrmcult is making this a difficult task, however.$B$BLuckily, there are those like you and Samia that are willing to lend us a hand." },
        ["text"] = "Ми прийшли до гаю Рууан, щоб спробувати відновити природну рівновагу в цих горах.$B$BОднак втручання араккоа та культу змієкрилів дуже ускладнює це завдання.$B$BНа щастя, є такі, як ти й Самія, хто готовий простягнути нам руку допомоги.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3558791939] = {
        ["english"] = { [1] = "When I first arrived, I'd hoped to meet the town's namesake.$B$B<Ros'eleth glances around.>$B$BMost young high elves outgrow the 'I wanna be a Farstrider' phase by the time they're taken as apprentices. Then, it's onto the 'I'm going to be a magister' stage.$B$BI don't think I ever quite outgrew the Farstrider phase, to be honest. No one dreams of growing up to be a seamstress, but we can't have the Farstriders running around naked, as my mother used to say." },
        ["text"] = "Коли я вперше прибула сюди, то сподівалася зустріти того, на честь кого назване місто.$B$B<Роз'елет озирається.>$B$BБільшість молодих високих ельфів переростає фазу «хочу бути далекоходцем» ще до того, як їх беруть у учні. Потім настає фаза «стану магістром». $B$BЯкщо чесно, не думаю, що я колись переросла фазу далекоходців. Ніхто не мріє вирости й стати швачкою, але ж не можуть далекоходці бігати голими, як казала моя мати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [382402039] = {
        ["english"] = { [1] = "We've lost a good many of our wind riders on scouting missions to the west. The Scourge is ruthless in their assault against any would-be spies.$B$BFortunately, I've come up with a solution that only risks the life of the rider. It's seen a 30% survival rate to those being ferried across the Plains of Nasam. That's a 30% improvement over when we were using wind riders!" },
        ["text"] = "Ми втратили чимало вітрокрилів під час розвідувальних місій на захід. Скара безжально розправляється з будь-якими потенційними шпигунами.$B$BНа щастя, я придумав рішення, яке наражає на небезпеку лише самого вершника. Серед тих, кого перевозили через рівнини Насам, виживає аж 30%. Це на 30% краще, ніж коли ми використовували вітрокрилів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2692130417] = {
        ["english"] = { [1] = "Warriors can usually be found either at the Pig and Whistle Tavern or the Barracks in Old Town. Tell ya though, the tavern is probably a better place look." },
        ["text"] = "Воїнів зазвичай можна знайти або в таверні «Свиня і Свисток», або в казармах Старого міста. Хоча, скажу тобі, у таверні шукати, мабуть, краще.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1671906130] = {
        ["english"] = { [1] = "What other things can I do at the faire?" },
        ["text"] = "Чим іще можна зайнятися на ярмарку?",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["reply"] = true },
    },
    [3473633583] = {
        ["english"] = { [1] = "Where are you going?  Well if you're looking to get there quickly, then look no further!" },
        ["text"] = "Куди прямуєш? Якщо хочеш дістатися туди швидко — ти прийшов за адресою!",
        ["npcs"] = { [1] = 523 },
        ["roles"] = { ["greeting"] = true },
    },
    [957301445] = {
        ["english"] = { [1] = "Where is Elder Starglade?" },
        ["text"] = "Де старійшина Зоряна Галявина?",
        ["npcs"] = { [1] = 15576, [2] = 15593 },
        ["roles"] = { ["reply"] = true },
    },
    [2484040520] = {
        ["english"] = { [1] = "Where are the Plates of Uldum?" },
        ["text"] = "Де Плити Ульдуму?",
        ["npcs"] = { [1] = 7918 },
        ["roles"] = { ["reply"] = true },
    },
    [1227064517] = {
        ["english"] = { [1] = "When you take one of these tasks, we'll lend you a ram. It's a loan, so it won't last forever. The ram may seem slow, but just ease up on the reins a bit and he'll pick up the pace.$b$bOur rams love apples. We've put a few bushels of apples out along the way, so make sure to stop by. Eating apples will make your ram forget about how tired he's been getting." },
        ["text"] = "Коли береш одне з цих завдань, ми позичаємо тобі барана. Саме позичаємо, тож назавжди він не залишиться. Може здатися, що баран повільний, але трохи послаб повід — і він прискориться.$b$bНаші барани обожнюють яблука. Ми розставили вздовж шляху кілька кошиків, тож обов'язково зупиняйся біля них. Яблука допоможуть барану забути, як він стомився.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1660961248] = {
        ["english"] = { [1] = "When you run with Razak's Roughriders, you learn a thing or two about following orders.$B$BThe first thing is that you fight until you die.  The second thing is, see the first thing." },
        ["text"] = "Коли бігаєш із Головорізами Разака, то дечого вчишся про виконання наказів.$B$BПерше — б'єшся, доки не помреш. Друге — дивись перше.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3236834603] = {
        ["english"] = { [1] = "What could I have done to give the gods cause to lash out at me with such ferocity? All that I cherished is gone - dead or destroyed. My family taken from me by the brutes of the forest. My home razed. My ship sunk.$B$BI am a broken man, stranded on a broken island.$B$BPerhaps you are you here to finish the job? Make it quick, I will not resist. Take my life, stranger; I am too cowardly to do it myself. My hand shivers... the blade will not strike true.$B" },
        ["text"] = "Що я міг зробити, щоб дати богам причину так люто на мене накинутися? Усе, що я любив, зникло — загинуло або було знищене. Родину забрали лісові звірі. Дім спалено. Корабель затонув.$B$BЯ зломлена людина, застрягла на зломленому острові.$B$BМоже, ти прийшов завершити справу? Роби швидко, я не чинитиму опору. Забери моє життя, незнайомцю; я надто боягузливий, щоб зробити це сам. Рука тремтить... клинок не влучить точно.$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2051852952] = {
        ["english"] = { [1] = "What are you looking at, $glad : lass;?  Never seen a dwarf before, then?$B$BYou'd best be on yer way if you don't want any trouble." },
        ["text"] = "На що дивишся, $gхлопче : дівчино;? Дворфа раніше не бачив?$B$BКраще йди своєю дорогою, якщо не хочеш проблем.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3243434261] = {
        ["english"] = { [1] = "When you have lived as long as I, it becomes easy to forget about love for years. It is always good to be reminded." },
        ["text"] = "Коли живеш так довго, як я, легко на роки забути про кохання. Добре, коли тобі про нього нагадують.",
        ["npcs"] = { [1] = 2796, [2] = 3517, [3] = 3561, [4] = 3562, [5] = 4088, [6] = 4164, [7] = 4167, [8] = 4168, [9] = 4169, [10] = 4170, [11] = 4171, [12] = 4172, [13] = 4173, [14] = 4175, [15] = 4177, [16] = 4180, [17] = 4181, [18] = 4203, [19] = 4216, [20] = 4220, [21] = 4221, [22] = 4222, [23] = 4223, [24] = 4225, [25] = 4226, [26] = 4228, [27] = 4229, [28] = 4230, [29] = 4231, [30] = 4232, [31] = 4233, [32] = 4234, [33] = 4235, [34] = 4236, [35] = 4240, [36] = 4262, [37] = 4521, [38] = 5407, [39] = 5782, [40] = 6034, [41] = 6142, [42] = 7313, [43] = 7316, [44] = 7740, [45] = 8026, [46] = 8665, [47] = 11700, [48] = 11709, [49] = 14378, [50] = 14379, [51] = 14380 },
        ["roles"] = { ["greeting"] = true },
    },
    [3933972633] = {
        ["english"] = { [1] = "We're celebrating the who breaking free of the what? Bah, who cares?! More candy!" },
        ["text"] = "Ми святкуємо там когось, хто звільнився від чогось? Та байдуже! Головне — більше цукерок!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2271783820] = {
        ["english"] = { [1] = "We orcs are usually a private people, but lately, no one's been hiding their feelings." },
        ["text"] = "Ми, орки, зазвичай не виставляємо почуття напоказ, але останнім часом ніхто вже нічого не приховує.",
        ["npcs"] = { [1] = 3296, [2] = 3312, [3] = 3313, [4] = 3315, [5] = 3316, [6] = 3317, [7] = 3319, [8] = 3321, [9] = 3322, [10] = 3323, [11] = 3329, [12] = 3330, [13] = 3331, [14] = 3333, [15] = 3334, [16] = 3335, [17] = 3342, [18] = 3346, [19] = 3348, [20] = 3349, [21] = 3350, [22] = 3351, [23] = 3356, [24] = 3358, [25] = 3359, [26] = 3360, [27] = 3361, [28] = 3364, [29] = 3366, [30] = 3367, [31] = 3368, [32] = 3369, [33] = 3371, [34] = 3372, [35] = 4043, [36] = 4047, [37] = 4485, [38] = 5603, [39] = 5606, [40] = 5609, [41] = 5611, [42] = 5614, [43] = 5640, [44] = 5816, [45] = 5817, [46] = 5909, [47] = 6446, [48] = 6986, [49] = 6987, [50] = 7790, [51] = 7792, [52] = 11176, [53] = 12799, [54] = 14375, [55] = 14376, [56] = 14377 },
        ["roles"] = { ["greeting"] = true },
    },
    [1600386875] = {
        ["english"] = { [1] = "Welcome to the Taverns of Time!" },
        ["text"] = "Ласкаво просимо до Таверн Часу!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [934080707] = {
        ["english"] = { [1] = "When you give love tokens to townsfolk, you'll receive different gifts in return.  Some of those you'll want to keep and use, but others can be bundled together and given to your favorite hero!  Visit Kwee Q. Peddlefeet to turn them in.$B$BKwee can be found near Cairne, Sylvanas and Thrall." },
        ["text"] = "Коли даруєш мешканцям міста знаки кохання, натомість отримуєш різні подарунки. Деякі варто лишити й використати, а інші можна зібрати в пакунок і віддати улюбленому герою! Віднеси їх Кві К. Педалькіну.$B$BКві можна знайти біля Керна, Сильвани та Тралла.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [723910920] = {
        ["english"] = { [1] = "What you be expectin', mon?$B$BMaywiki only be dealin' with the druids and shaman." },
        ["text"] = "Чого ти чекаєш, мон?$B$BМейвікі має справу тільки з друїдами й шаманами.",
        ["npcs"] = { [1] = 14904 },
        ["roles"] = { ["greeting"] = true },
    },
    [3535594370] = {
        ["english"] = { [1] = "When you get a ram, you also get the reins. These aren't your grandma's reins though, you've gotta use them!$b$bJust loosen up on the reins a few times to build up some speed.  Keep on loosening up and GIDDYUP!  You'll be flying!$b$bBut the faster he goes the quicker he'll get tired. So you have to be careful.$B" },
        ["text"] = "Коли отримуєш барана, разом із ним отримуєш і повід. Але це не бабусині поводи — ними треба користуватися!$b$bКілька разів послаб повід, щоб набрати швидкість. Продовжуй послаблювати й ГЕЙ-ГОП! Полетиш!$b$bАле що швидше він біжить, то швидше втомлюється. Тож будь обережний.$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2380970661] = {
        ["english"] = { [1] = "We have no time to waste, $c. Why do you delay here?" },
        ["text"] = "Не можна гаяти часу, $c. Чому ти тут баришся?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1888321483] = {
        ["english"] = { [1] = "Ye've come to the right place $glad : lass;!  People come here from all o'er the world to train to be a blacksmith.  Ye'll find Bengus Deepforge hammering away at an anvil in the middle of our fine city by The Great Forge itself." },
        ["text"] = "Ти прийшов саме туди, $gхлопче : дівчино;! Люди з усього світу приходять сюди вчитися ковальства. Бенґуса Глибокогорна знайдеш біля ковадла посеред нашого прекрасного міста, просто біля Великої Кузні.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [1540572606] = {
        ["english"] = { [1] = "When the tournament starts, all will see the Forsaken emerge triumphant." },
        ["text"] = "Коли турнір почнеться, усі побачать тріумф Відречених.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1154687953] = {
        ["english"] = { [1] = "When the Darkmoon Faire is open, it will be located in Elwynn Forest.  We'll be pitching our tents just south of Goldshire!" },
        ["text"] = "Коли ярмарок Темного Місяця відкриється, він буде в Ельвинському лісі. Ми поставимо намети трохи південніше Злотохрестя!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3305318956] = {
        ["english"] = { [1] = "What do I look like, the Grand Poobah of enchanters? Your skills require the guidance of an Artisan! Go find Kitta Firewind at the Tower of Azora." },
        ["text"] = "На кого я схожий — на Великого Головного Чарівника? Твої навички потребують наставництва майстра! Знайди Кітту Вогневійну біля Вежі Азори.",
        ["npcs"] = { [1] = 5157 },
        ["roles"] = { ["greeting"] = true },
    },
    [4121613350] = {
        ["english"] = { [1] = "Well ye'd be sure to find some training in the magical arts over in the Hall of Mysteries, north of the gates of Ironforge.  Juli Stormkettle can always be found there with her nose in a book." },
        ["text"] = "Навчанню магічних мистецтв точно знайдеться місце в Залі Таємниць, на північ від брам Стальгорна. Джулі Громоказан завжди там, уткнувшись носом у книгу.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [4142914723] = {
        ["english"] = { [1] = "When Lolo doesn't wanna spill any o' his precious ale or get his lil' dress dirty, I'm called in. Yep. Ol' Hansel is the dwarf they use to mete out a lil' bit o' justice an' a whole lotta pain." },
        ["text"] = "Коли Лоло не хоче розливати свій дорогоцінний ель чи бруднити свою маленьку сукенку, кличуть мене. Ага. Старий Гансел — той дворф, якого посилають відміряти трохи справедливості й дуже багато болю.",
        ["npcs"] = { [1] = 14627 },
        ["roles"] = { ["greeting"] = true },
    },
    [2536175307] = {
        ["english"] = { [1] = "When it comes to treasure, never be lookin' sideways at lootin' someone else's junk. Stolen goods be much sweeter, ya? But free is free, no matta how it got that way!" },
        ["text"] = "Коли справа доходить до скарбів, не дивися косо на чуже барахло, яке можна поцупити. Вкрадене добро солодше, еге ж? Але безплатне — воно й є безплатне, як би таким не стало!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2755126272] = {
        ["english"] = { [1] = "What?  But how?  No!  This is not possible!  I have been so careful... he could not know!$B$BYou lie!  You lie, and now you'll die for your deceit!" },
        ["text"] = "Що? Але як? Ні! Це неможливо! Я був такий обережний... він не міг знати!$B$BТи брешеш! Брешеш — і тепер помреш за свою брехню!",
        ["npcs"] = { [1] = 14523 },
        ["roles"] = { ["greeting"] = true },
    },
    [2882161899] = {
        ["english"] = { [1] = "We're making progress, $r, but far too slowly." },
        ["text"] = "Ми просуваємося вперед, $r, але надто повільно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1230941692] = {
        ["english"] = { [1] = "What's needed for the cauldron at Felstone Field?" },
        ["text"] = "Що потрібно для котла на Полі Фелстонів?",
        ["npcs"] = { [1] = 11056, [2] = 11057 },
        ["roles"] = { ["reply"] = true },
    },
    [2272375471] = {
        ["english"] = { [1] = "Welcome to Theramore, $c." },
        ["text"] = "Ласкаво просимо до Терамора, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3569487981] = {
        ["english"] = { [1] = "Vaelastrasz, no!!!" },
        ["text"] = "Валестразе, ні!!!",
        ["npcs"] = { [1] = 13020 },
        ["roles"] = { ["reply"] = true },
    },
    [2934610090] = {
        ["english"] = { [1] = "Where is Elder Meadowrun?" },
        ["text"] = "Де старійшина Луговий Біг?",
        ["npcs"] = { [1] = 15566, [2] = 15568, [3] = 15592, [4] = 15594 },
        ["roles"] = { ["reply"] = true },
    },
    [2250045089] = {
        ["english"] = { [1] = "We could certainly use another cook around Dolanaar, not that Zarrin's cooking is lacking mind you.  Why don't you go see what he can teach you?" },
        ["text"] = "Ще один кухар у Доланаарі нам точно не завадив би — не те щоб Заррін погано готував. Чому б тобі не навідатися до нього й не дізнатися, чого він може навчити?",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [2401103316] = {
        ["english"] = { [1] = "Xon'cha will stable your extra pets.  Find him in the Valley of Honor at the stables between the arena and the Hunter's Hall.  Now begone!" },
        ["text"] = "Ксон'ча прихистить твоїх зайвих вихованців у стайні. Знайдеш його в Долині Честі, у стайнях між ареною та Залою Мисливців. А тепер геть!",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [4071202990] = {
        ["english"] = { [1] = "Thuwd will show you how to skin your kills.  Look for him at Kodohide Leatherworkers in The Drag." },
        ["text"] = "Тувд покаже тобі, як знімати шкури зі здобичі. Шукай його в «Шкіряниках Кодошкурих» у Хитрому провулку.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [2856066271] = {
        ["english"] = { [1] = "When I grow up I wanna be a tanner!" },
        ["text"] = "Коли виросту, хочу стати чинбарем!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3699930717] = {
        ["english"] = { [1] = "Turn that frown upside down!" },
        ["text"] = "Не кисни!",
        ["npcs"] = { [1] = 14354 },
        ["roles"] = { ["greeting"] = true },
    },
    [2075022070] = {
        ["english"] = { [1] = "While I live to serve the Earth Mother and the Horde, I cannot help but feel a little nervous now that we've collected everything that we need. At least we have a little time until the Alliance finishes their gathering efforts. After that it will all be shipped to Cenarion Hold in Silithus, and the war will likely follow not long after." },
        ["text"] = "Хоч я живу, щоб служити Матері-Землі й Орді, не можу не нервувати тепер, коли ми зібрали все необхідне. Принаймні маємо трохи часу, доки Альянс завершить свій збір. Потім усе відправлять до Кенарійської цитаделі в Силітусі, а невдовзі, найімовірніше, почнеться війна.",
        ["npcs"] = { [1] = 15532 },
        ["roles"] = { ["greeting"] = true },
    },
    [1629801218] = {
        ["english"] = { [1] = "We must discover what's behind the mystery of the giant crystal that fell from the heavens on Fallen Sky Ridge." },
        ["text"] = "Ми повинні розкрити таємницю велетенського кристала, що впав із небес на Кряжі Полеглого Неба.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2066674392] = {
        ["english"] = { [1] = "Until I traveled through Nagrand and came to the forest, I feared that too much of our original culture was lost. I'm thankful to see that I was wrong.$B$BThere is so much to be done here!" },
        ["text"] = "Поки я не пройшов через Наґранд і не дістався лісу, то боявся, що надто багато нашої первісної культури втрачено. Я радий, що помилявся.$B$BТут іще стільки всього треба зробити!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3761882578] = {
        ["english"] = { [1] = "Where is Elder Riversong?" },
        ["text"] = "Де старійшина Річкоспів?",
        ["npcs"] = { [1] = 15574, [2] = 15600, [3] = 15601, [4] = 15603 },
        ["roles"] = { ["reply"] = true },
    },
    [2379184526] = {
        ["english"] = { [1] = "Where can I find core of elements?" },
        ["text"] = "Де можна знайти ядро стихій?",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["reply"] = true },
    },
    [449690928] = {
        ["english"] = { [1] = "What is the cause of this conflict?" },
        ["text"] = "У чому причина цього конфлікту?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1766963008] = {
        ["english"] = { [1] = "When I clawed my way out of the grave, I thought my family would welcome me with open arms. Instead, they drove me from the village, screaming in a language I could no longer understand." },
        ["text"] = "Коли я видерся з могили, то думав, що родина зустріне мене з розкритими обіймами. Натомість вони вигнали мене із села, кричачи мовою, якої я більше не розумів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2598043103] = {
        ["english"] = { [1] = "What a landmark discovery! The Royal Apothecary Society has spent years working to break the secrets of the Lich King's plague, and I've finally done it!$B$BDespite this turning point in history, there is still so much to discover. I have more experiments to conduct... test subjects to acquire...$B$BAt least I don't have to worry about Scourge necropoli. The Alliance is dealing with that problem. This leaves me plenty of time to delve into the secrets of the plague and uncover what I can." },
        ["text"] = "Яке визначне відкриття! Королівське товариство аптекарів роками намагалося розкрити таємниці чуми Короля-Ліча, і я нарешті це зробив!$B$BПопри цей історичний перелом, попереду ще стільки відкриттів. Мені треба провести більше дослідів... знайти піддослідних...$B$BПринаймні не треба хвилюватися про некрополі Скари. Альянс розбирається з цією проблемою. Тож у мене вдосталь часу зануритися в таємниці чуми й дізнатися все можливе.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2438670793] = {
        ["english"] = { [1] = "When he says, 'younger brother,' he fails to mention that we're twins. He's really only older by a couple of minutes.$B$BDon't let that 'rising star' bit of his fool you. I'll never be a trader of the same magnitude that he is." },
        ["text"] = "Коли він каже «молодший брат», то забуває згадати, що ми близнюки. Він старший лише на кілька хвилин.$B$BНе дай його словам про «висхідну зірку» тебе обдурити. Я ніколи не стану торговцем такого ж масштабу, як він.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4070900194] = {
        ["english"] = { [1] = "Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.$B$BThere are rumors of strife within the Cenarion Circle, but you should pay such loose talk no heed.  Our Arch Druid, Fandral Staghelm, leads us and all of Teldrassil to glory!" },
        ["text"] = "Ласкаво просимо, $g брате : сестро;. Якщо ти прийшов тренуватися, я із задоволенням тебе навчу.$B$BХодять чутки про розбрат у Кенарієвому Колі, але не зважай на пусті балачки. Наш архідруїд Фендрал Оленеріг веде нас і весь Тельдрассіль до слави!",
        ["npcs"] = { [1] = 4217, [2] = 4218, [3] = 4219 },
        ["roles"] = { ["greeting"] = true },
    },
    [4278927245] = {
        ["english"] = { [1] = "Which battleground do you seek your glory in?" },
        ["text"] = "На якому полі бою ти шукаєш слави?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [549913221] = {
        ["english"] = { [1] = "We've just arrived here and already we've buried too many of our friends and comrades." },
        ["text"] = "Ми щойно прибули, а вже поховали надто багато друзів і побратимів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [676916626] = {
        ["english"] = { [1] = "Welcome!  Welcome to Yebb Neblegear's Darkmoon Zoo Bizarre - a Trove of Living Legends and Mythical Oddities!  Enjoy your visit, friend!$B$BBut be mindful of what you touch!  These exhibits hold artifacts and beasts both dire and divine!  They might burn the wayward hand of an over-curious onlooker..." },
        ["text"] = "Ласкаво просимо! Ласкаво просимо до Химерного зоопарку Темного Місяця Єбба Небельшестерні — скарбниці живих легенд і міфічних дивовиж! Приємного візиту, друже!$B$BАле дивися, чого торкаєшся! Серед цих експонатів є артефакти й звірі — і жахливі, і божественні! Вони можуть обпалити необережну руку надто допитливого відвідувача...",
        ["npcs"] = { [1] = 14829 },
        ["roles"] = { ["greeting"] = true },
    },
    [3391499300] = {
        ["english"] = { [1] = "We have won $2219W battles against the Scourge.  Stand firm, $N!  We must persevere!" },
        ["text"] = "Ми виграли $2219W битв проти Скари. Стій твердо, $N! Ми мусимо вистояти!",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["greeting"] = true },
    },
    [3989523324] = {
        ["english"] = { [1] = "Until what?" },
        ["text"] = "До чого?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1625500252] = {
        ["english"] = { [1] = "Whatever you need, Brazie Getz! Get it?$B$BAnd I'm not just talkin' about the \"legal\" stuff, either. WHATEVER YOU NEED, PAL! Anything..." },
        ["text"] = "Що завгодно тобі потрібно — Брейзі дістане! Зрозумів?$B$BІ я говорю не лише про «законні» речі. ЩО ЗАВГОДНО ТОБІ ПОТРІБНО, ДРУЖЕ! Будь-що...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3603935772] = {
        ["english"] = { [1] = "Whatever advice I can give to aid in your fight against the ogres, you shall have it!" },
        ["text"] = "Я дам тобі будь-яку пораду, що допоможе в боротьбі проти огрів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3973435923] = {
        ["english"] = { [1] = "We do not have much time, hero. What do you need?" },
        ["text"] = "У нас обмаль часу, герою. Що тобі потрібно?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3930363532] = {
        ["english"] = { [1] = "We've got to get those supply crates back!" },
        ["text"] = "Ми повинні повернути ті ящики з припасами!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1876745252] = {
        ["english"] = { [1] = "Where is Elder Primestone?" },
        ["text"] = "Де старійшина Первісний Камінь?",
        ["npcs"] = { [1] = 15583, [2] = 15599 },
        ["roles"] = { ["reply"] = true },
    },
    [2900462376] = {
        ["english"] = { [1] = "Watch your step in here, $gboy:girl;.  The master sees all..." },
        ["text"] = "Дивися під ноги тут, $gхлопче:дівчино;. Господар бачить усе...",
        ["npcs"] = { [1] = 707, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096 },
        ["roles"] = { ["greeting"] = true },
    },
    [55256926] = {
        ["english"] = { [1] = "Ye bothered me for that? Ye'd be better off strapping a dead rabbit to yer back and running through a Troll's den than wearing that piece of garbage." },
        ["text"] = "Ти потурбував мене заради цього? Краще прив'язати до спини мертвого кролика й пробігти крізь троляче лігво, ніж носити цей шмат мотлоху.",
        ["npcs"] = { [1] = 5164 },
        ["roles"] = { ["greeting"] = true },
    },
    [840678476] = {
        ["english"] = { [1] = "To many of the Forsaken, the moon now holds the place in our hearts where sun once resided. However, if you choose to join the celebration, go to Moonglade in Kalimdor. You'll find druids in the throne room above Undercity that will transport you there." },
        ["text"] = "Для багатьох Відречених місяць тепер посідає в наших серцях місце, де колись було сонце. Та якщо захочеш долучитися до святкування, вирушай у Місячну галявину в Калімдорі. У тронній залі над Підмістям знайдеш друїдів, які перенесуть тебе туди.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [180418932] = {
        ["english"] = { [1] = "What are the Plates of Uldum?" },
        ["text"] = "Що таке Плити Ульдуму?",
        ["npcs"] = { [1] = 7918 },
        ["roles"] = { ["reply"] = true },
    },
    [1497911989] = {
        ["english"] = { [1] = "We have a lot of excess supplies, but we still need more before we can send an assualt into the Field of Strife." },
        ["text"] = "У нас багато зайвих припасів, але потрібно ще більше, перш ніж ми зможемо відправити наступ на Поле Чвар.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1839834395] = {
        ["english"] = { [1] = "Wait, don't tell me... $n, right?$b$bWhat can I do for you?$B" },
        ["text"] = "Стривай, не кажи мені... $n, так?$b$bЧим можу допомогти?$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1254019584] = {
        ["english"] = { [1] = "Well met, friend.  I am Officer Pureheart, and I am a proud member of a world-wide organization known as the Argent Dawn.  Our cause is simple - fight swifty and mercilessly against any element of evil that surfaces in Azeroth.  We are not a political body, nor do we ever wish to become one.  To that end we call both the Alliance and the Horde both as friends - friends in the cause of stamping out evil!$B$BFor the Dawn, my $g brother : sister;!" },
        ["text"] = "Вітаю, друже. Я офіцер Чистосердий і гордий член всесвітньої організації, відомої як Сріблястий Світанок. Наша мета проста — швидко й нещадно боротися з будь-яким злом, що з'являється в Азероті. Ми не політична організація й ніколи не прагнемо нею стати. Саме тому ми називаємо друзями і Альянс, і Орду — друзями у справі викорінення зла!$B$BЗа Світанок, $g брате : сестро;!",
        ["npcs"] = { [1] = 10840 },
        ["roles"] = { ["greeting"] = true },
    },
    [3344062804] = {
        ["english"] = { [1] = "What is it now, $c, I haven't got all day? The Horde has completed its collections and now waits only on the Alliance to organize themselves and do the same. Perhaps you should be out there looking for the pieces to the Scepter of the Shifting Sands so that you can ring the gong at the Scarab Dais, opening the gates to Ahn'Qiraj and thereby starting the war?" },
        ["text"] = "Що ще, $c, у мене немає цілого дня? Орда завершила збір і тепер чекає лише, доки Альянс організується й зробить те саме. Може, тобі варто шукати частини Скіпетра Мінливих Пісків, щоб ударити в гонг на Помості Скарабея, відчинити брами Ан'Кіражу й почати війну?",
        ["npcs"] = { [1] = 15529 },
        ["roles"] = { ["greeting"] = true },
    },
    [3591099002] = {
        ["english"] = { [1] = "What? You want something?" },
        ["text"] = "Що? Тобі щось треба?",
        ["npcs"] = { [1] = 3494 },
        ["roles"] = { ["greeting"] = true },
    },
    [2437751766] = {
        ["english"] = { [1] = "What abilities do Ruby Drakes have?" },
        ["text"] = "Які здібності мають рубінові драки?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1911199903] = {
        ["english"] = { [1] = "White security card insertion successful...$B$BDispensing security level beta unit.\010\01001010000 01101100 01100001 01111001 00100000 01110100 01101000 01100101 00100000 01010111 01100001 01110010 01100011 01100001 01110010 01100110 01110100 00100000 01110010 01101111 01101100 01100101 01110000 01101100 01100001 01111001 01101001 01101110 01100111 00100000 01100111 01100001 01101101 01100101" },
        ["text"] = "Білу картку безпеки успішно вставлено...$B$BВидача модуля рівня безпеки бета.\010\01001010000 01101100 01100001 01111001 00100000 01110100 01101000 01100101 00100000 01010111 01100001 01110010 01100011 01100001 01110010 01100110 01110100 00100000 01110010 01101111 01101100 01100101 01110000 01101100 01100001 01111001 01101001 01101110 01100111 00100000 01100111 01100001 01101101 01100101",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [111538720] = {
        ["english"] = { [1] = "What? I'm busy here." },
        ["text"] = "Що? Я тут зайнятий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1876164333] = {
        ["english"] = { [1] = "What? I don't know of any warlock trainers in Stormwind. \010\010Although... There have been some sightings of demonic activity over by The Slaughtered Lamb in the Mage Quarter. I suppose you could check there." },
        ["text"] = "Що? Я не знаю жодних наставників чорнокнижників у Штормовії. \010\010Хоча... біля «Зарізаного Ягняти» в Кварталі Магів помічали демонічну активність. Можеш перевірити там.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3157998547] = {
        ["english"] = { [1] = "We practitioners of the arcane and elemental ways follow a never ending path of discovery. Is that why you seek my counsel? You wish further training?" },
        ["text"] = "Ми, послідовники арканічного та стихійного мистецтва, йдемо безкінечним шляхом відкриттів. Саме тому ти шукаєш моєї поради? Хочеш продовжити навчання?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [464201189] = {
        ["english"] = { [1] = "Tirth's not himself these days, and neither is his assistant." },
        ["text"] = "Останнім часом Тірт сам не свій, та й його помічник теж.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2085045459] = {
        ["english"] = { [1] = "Well met, $N. We must be brief because there is much to do." },
        ["text"] = "Вітаю, $N. Треба говорити коротко, бо справ дуже багато.",
        ["npcs"] = { [1] = 4967 },
        ["roles"] = { ["greeting"] = true },
    },
    [1580039464] = {
        ["english"] = { [1] = "When I was young I trained hard to become an anchorite in the priesthood.  Female exarchs were practically unheard of.$B$BNowadays gender matters little - it is courage and conviction that make all the difference." },
        ["text"] = "У молодості я наполегливо тренувалася, щоб стати анахоретом у жрецтві. Жінки-екзархи тоді були майже нечуваним явищем.$B$BНині стать майже не має значення — усе вирішують відвага й переконання.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3664465391] = {
        ["english"] = { [1] = "We have been tending these worms for some time. I hope they will be fit in time for the ring event of this organization. You must face not one, but two jormungar, after all." },
        ["text"] = "Ми вже певний час доглядаємо цих червів. Сподіваюся, вони будуть у формі до виступу на арені цієї організації. Зрештою, тобі доведеться битися не з одним, а з двома йормунґарами.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2765780352] = {
        ["english"] = { [1] = "We're still making preparations. We won't be ready to go for a while." },
        ["text"] = "Ми все ще готуємося. До відправлення ще далеко.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3343127794] = {
        ["english"] = { [1] = "We've important work to do, $N.  Let us attack our enemies while their guard is down.  Let us show them that sin'dorei vengeance never forgets nor forgives." },
        ["text"] = "У нас важлива робота, $N. Удармо по ворогах, поки вони не насторожі. Покажімо їм, що помста сін'дорай не забуває й не пробачає.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1712914435] = {
        ["english"] = { [1] = "What?" },
        ["text"] = "Що?",
        ["npcs"] = { [1] = 987, [2] = 1404, [3] = 9177, [4] = 16116 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true },
    },
    [2266040763] = {
        ["english"] = { [1] = "Welcome, $c. Have you come to honor this flame?$b$bRemember: Our festival fires burn in every land with a Horde settlement. Make time to honor each of them, if you can.$b$bThe Alliance, too, burns fires of their own. You would do well to desecrate such unworthy efforts when you see them." },
        ["text"] = "Ласкаво просимо, $c. Прийшов вшанувати це полум'я?$b$bПам'ятай: наші святкові вогні горять у кожній землі, де є поселення Орди. Якщо зможеш, знайди час ушанувати кожне.$b$bАльянс теж палить свої вогні. Побачиш таке негідне полум'я — добре було б його осквернити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3561868726] = {
        ["english"] = { [1] = "Well, looks like we've gathered up everything that the Alliance is going to need; now we're just waiting on the Horde. I think soon I'm going to see if there's any Tigule & Foror's ice cream nearby." },
        ["text"] = "Схоже, Альянс уже зібрав усе потрібне; тепер чекаємо лише на Орду. Думаю, скоро піду пошукаю, чи не продають десь поблизу морозиво Тіґула й Форора.",
        ["npcs"] = { [1] = 15434 },
        ["roles"] = { ["greeting"] = true },
    },
    [1129386771] = {
        ["english"] = { [1] = "Welcome, friend, to the barbershop! Come for a cut? A coloring? Something else, perhaps?$B$BWe can groom facial hair, perform piercings, reshape tusks and horns, and even modify undead features!$B$BHave a seat and we'll get right to work. You're only a few coins away from a new, more attractive you..." },
        ["text"] = "Ласкаво просимо, друже, до перукарні! Прийшов підстригтися? Пофарбувати волосся? Може, щось інше?$B$BМи доглядаємо бороди й вуса, робимо пірсинг, змінюємо форму бивнів і рогів, а ще можемо підправити риси невмерлих!$B$BСідай, і ми одразу почнемо. Лише кілька монет відділяють тебе від нового, привабливішого вигляду...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2089217111] = {
        ["english"] = { [1] = "What goods have I earned the right to purchase for use in Warsong Gulch?" },
        ["text"] = "Які товари я заслужив право придбати для використання в Ущелині Пісні Війни?",
        ["npcs"] = { [1] = 14753, [2] = 14754 },
        ["roles"] = { ["reply"] = true },
    },
    [2799514117] = {
        ["english"] = { [1] = "What's your pleasure?  Pull up a seat and knock one back.$B$BI'm Boots, lead mixologist for B.O.O.M. and bartender extraordinaire!$B$BIf it's got kick, Ol' Boots can give it to ya." },
        ["text"] = "Чого душа бажає? Сідай та перекинь чарку.$B$BЯ Бутс, головний міксолог Б.У.М. і бармен найвищого ґатунку!$B$BЯкщо воно добряче б'є в голову, старий Бутс тобі це наллє.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [37859530] = {
        ["english"] = { [1] = "What do you know of it, Franzahl?" },
        ["text"] = "Що ти знаєш про це, Францалю?",
        ["npcs"] = { [1] = 14348 },
        ["roles"] = { ["reply"] = true },
    },
    [3584694930] = {
        ["english"] = { [1] = "Well yes, I do know a rare alchemical recipe.  Let me teach you!" },
        ["text"] = "Так, я справді знаю рідкісний алхімічний рецепт. Дозволь навчити тебе!",
        ["npcs"] = { [1] = 8696 },
        ["roles"] = { ["greeting"] = true },
    },
    [530755227] = {
        ["english"] = { [1] = "What's with the different speeds?" },
        ["text"] = "А навіщо різні швидкості?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1864481558] = {
        ["english"] = { [1] = "Warlock trainers in Magic Quarter in building on outer ring with Mages." },
        ["text"] = "Наставники чорнокнижників — у Кварталі Магії, в будівлі на зовнішньому кільці разом із магами.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [1689355212] = {
        ["english"] = { [1] = "Where is Elder Hammershout?" },
        ["text"] = "Де старійшина Молотокрик?",
        ["npcs"] = { [1] = 15557, [2] = 15565, [3] = 15598, [4] = 15871 },
        ["roles"] = { ["reply"] = true },
    },
    [25364896] = {
        ["english"] = { [1] = "Where is Elder Mistwalker?" },
        ["text"] = "Де старійшина Туманний Хода?",
        ["npcs"] = { [1] = 15556, [2] = 15581, [3] = 15604 },
        ["roles"] = { ["reply"] = true },
    },
    [2516246114] = {
        ["english"] = { [1] = "We join guild?  No?  Ok, you find Guild Master on east platform in Trade Quarter." },
        ["text"] = "Ми вступаємо в гільдію? Ні? Гаразд, майстра гільдії знайдеш на східній платформі в Торговому кварталі.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3298573089] = {
        ["english"] = { [1] = "What can I do?" },
        ["text"] = "Що я можу зробити?",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["reply"] = true },
    },
    [2020737340] = {
        ["english"] = { [1] = "What function do you serve?" },
        ["text"] = "Яку функцію ти виконуєш?",
        ["npcs"] = { [1] = 7918 },
        ["roles"] = { ["reply"] = true },
    },
    [3957479207] = {
        ["english"] = { [1] = "When you next go to the Molten Core, kill a Firelord for me, will you?" },
        ["text"] = "Коли наступного разу підеш до Вогняних Надр, убий для мене Володаря Вогню, гаразд?",
        ["npcs"] = { [1] = 13322 },
        ["roles"] = { ["greeting"] = true },
    },
    [462422731] = {
        ["english"] = { [1] = "What's it going to be, then?  Rum?  Ale?$B$BOr perhaps something else?" },
        ["text"] = "Ну то що буде? Ром? Ель?$B$BЧи, може, щось інше?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1632523477] = {
        ["english"] = { [1] = "We've almost consolidated our control over Sun's Reach.  If we manage to keep the harbor from getting any reinforcements we will certainly succeed.$B$BWe are $3238w percent done with our goal." },
        ["text"] = "Ми майже закріпили контроль над Сонячним Краєм. Якщо не допустимо підкріплень до гавані, то неодмінно переможемо.$B$BМи виконали $3238w відсотків нашої мети.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [235023833] = {
        ["english"] = { [1] = "What's an elf like you doing inside a cave like this?" },
        ["text"] = "Що такий ельф, як ти, робить у такій печері?",
        ["npcs"] = { [1] = 5353 },
        ["roles"] = { ["reply"] = true },
    },
    [1132640667] = {
        ["english"] = { [1] = "Why is everyone looking at me as if I crashed the ship?" },
        ["text"] = "Чому всі дивляться на мене так, ніби це я розбив корабель?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [563142706] = {
        ["english"] = { [1] = "Where is it ye would like to go $g lad : lass;? For just a few coin my Gryphons can get ye there faster than even the swiftest horse." },
        ["text"] = "Куди бажаєш вирушити, $g хлопче : дівчино;? За кілька монет мої грифони доправлять тебе туди швидше за найпрудкішого коня.",
        ["npcs"] = { [1] = 352 },
        ["roles"] = { ["greeting"] = true },
    },
    [3067729356] = {
        ["english"] = { [1] = "What're ye starin' at, $r? Come ta torment the condemned?" },
        ["text"] = "Чого витріщився, $r? Прийшов мучити засуджених?",
        ["npcs"] = { [1] = 3467 },
        ["roles"] = { ["greeting"] = true },
    },
    [1351614843] = {
        ["english"] = { [1] = "Welcome aboard the Maiden's Fancy. It should be smooth sailing all the way to port." },
        ["text"] = "Ласкаво просимо на борт «Примхи Діви». До самого порту плавання має бути спокійним.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4056024805] = {
        ["english"] = { [1] = "What it means to be a Hand of Argus... We are agents of the Light. We serve without question. We die without question." },
        ["text"] = "Що означає бути Десницею Арґуса... Ми — слуги Світла. Служимо без запитань. Помираємо без запитань.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3167677988] = {
        ["english"] = { [1] = "What'll it be, sweety?" },
        ["text"] = "Що бажаєш, любчику?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1461747655] = {
        ["english"] = { [1] = "What!" },
        ["text"] = "Що?!",
        ["npcs"] = { [1] = 10260 },
        ["roles"] = { ["greeting"] = true },
    },
    [2450600218] = {
        ["english"] = { [1] = "Welcome back, $N." },
        ["text"] = "З поверненням, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [204348992] = {
        ["english"] = { [1] = "Unfortunately we do not have one who teaches Tailoring here in Bloodhoof Village, but you can find a trainer in Thunder Bluff.  Follow the path north out of the village until you come to a set of elevators.  Take one up to the top of the rise and ask one of the Bluffwatchers there for directions." },
        ["text"] = "На жаль, у селищі Криваве Копито немає наставника кравецтва, але його можна знайти в Громовому Бескиді. Іди дорогою на північ від селища, доки не дійдеш до підіймачів. Піднімися одним із них нагору й запитай дорогу в одного з Вартових Бескиду.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [426308154] = {
        ["english"] = { [1] = "What you want?" },
        ["text"] = "Чого тобі?",
        ["npcs"] = { [1] = 3411 },
        ["roles"] = { ["greeting"] = true },
    },
    [2907028039] = {
        ["english"] = { [1] = "Truly, I envy you: To battle in the name of the Horde, at the forefront of conflict. Mine is a job of command.$B$BCertainly, in my youth, I lived out the dreams that make my old age bearable. I now revel in the glory of victory, the bitter taste of defeat - all through the soldiers I command.\010" },
        ["text"] = "Щиро кажучи, я тобі заздрю: битися в ім'я Орди на передовій самого конфлікту. Моє ж діло — командувати.$B$BБезперечно, в юності я здійснив мрії, завдяки яким тепер можу терпляче зносити старість. Нині я смакую славу перемоги й гіркоту поразки — через солдатів, якими командую.\010",
        ["npcs"] = { [1] = 9077 },
        ["roles"] = { ["greeting"] = true },
    },
    [1181981179] = {
        ["english"] = { [1] = "We're on orders from on high to destroy Rajaxx. Terminate with extreme prejudice if you want to get technical." },
        ["text"] = "Маємо наказ згори знищити Раджакса. Якщо вже говорити по-військовому — ліквідувати з особливою жорсткістю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3356862214] = {
        ["english"] = { [1] = "What you doin' wanderin' around here?  Why them small fries not in da shackles?!" },
        ["text"] = "Що ти тут блукаєш? Чого ті малявки не в кайданах?!",
        ["npcs"] = { [1] = 14325 },
        ["roles"] = { ["greeting"] = true },
    },
    [4285494967] = {
        ["english"] = { [1] = "Uldaman can be found at the very northern end of the Badlands." },
        ["text"] = "Ульдаман розташований на самому північному краю Безплідних країв.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [813607901] = {
        ["english"] = { [1] = "Use 8 necrotic runes and disrupt his ritual." },
        ["text"] = "Використай 8 некротичних рун і зірви його ритуал.",
        ["npcs"] = { [1] = 16230 },
        ["roles"] = { ["reply"] = true },
    },
    [1728100338] = {
        ["english"] = { [1] = "We've captured the armory, $N.  Let's not rest on our laurels, however.  The Legion sure will not." },
        ["text"] = "Ми захопили зброярню, $N. Але не час спочивати на лаврах. Легіон точно не відпочиватиме.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1907294134] = {
        ["english"] = { [1] = "What Sevine, Allistarj, and Grol did not realize was that just as their servants were bound to the land, so would they be... You see, the price for their own immortality was also imprisonment and eternal servitude under the command of Razelikh. The cruel cunning of Razelikh had emerged the victor once again.\010" },
        ["text"] = "Севіна, Аллістарж і Ґрол не усвідомлювали, що як їхні слуги були прив'язані до цієї землі, так само будуть прив'язані й вони... Розумієш, ціною їхнього безсмертя стали також ув'язнення й вічна служба під владою Разеліха. Жорстока хитрість Разеліха знову перемогла.\010",
        ["npcs"] = { [1] = 7783 },
        ["roles"] = { ["greeting"] = true },
    },
    [1778172098] = {
        ["english"] = { [1] = "Want to train with Borgus? Aye, I can tell ye where to find him. Head through the Square northwest of me forge, then take the western road. Ye'll find him in the second building on yer right." },
        ["text"] = "Хочеш тренуватися в Борґуса? Атож, можу сказати, де його знайти. Пройди через площу на північний захід від моєї кузні, потім зверни на західну дорогу. Він буде в другому будинку праворуч.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [169147572] = {
        ["english"] = { [1] = "When you give love tokens to townsfolk, you'll receive different gifts in return.  Some of those you'll want to keep and use, but others can be bundled together and given to your favorite hero!  Visit Kwee Q. Peddlefeet to turn them in.$B$BKwee can be found near Bolvar, Magni, or Tyrande." },
        ["text"] = "Коли даруєш мешканцям міста знаки кохання, натомість отримуєш різні подарунки. Деякі варто лишити й використати, а інші можна зібрати в пакунок і віддати улюбленому герою! Віднеси їх Кві К. Педалькіну.$B$BКві можна знайти біля Болвара, Маґні або Тіранди.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2293790698] = {
        ["english"] = { [1] = "What you be wanting? *hic*" },
        ["text"] = "Чого тобі треба? *гик*",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["greeting"] = true },
    },
    [3495616315] = {
        ["english"] = { [1] = "What want from Raze??" },
        ["text"] = "Чого хоче від Рейза??",
        ["npcs"] = { [1] = 8441 },
        ["roles"] = { ["greeting"] = true },
    },
    [3530844770] = {
        ["english"] = { [1] = "What tasty treats can we offer you?" },
        ["text"] = "Які смачні ласощі тобі запропонувати?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2422903531] = {
        ["english"] = { [1] = "Well met, I'm Azimi! I often make the walk out here to sell the men fresh fruit and water. Are you hungry, or perhaps thirsty?" },
        ["text"] = "Вітаю, я Азімі! Я часто приходжу сюди продавати чоловікам свіжі фрукти й воду. Ти голодний чи, може, хочеш пити?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1800392687] = {
        ["english"] = { [1] = "Tower Point holds the pass between the Field of Strife and the Horde territories to the south.$B$BIt is controlled by neither side." },
        ["text"] = "Вежова точка утримує прохід між Полем Чвар і територіями Орди на півдні.$B$BЇї не контролює жодна зі сторін.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [487571673] = {
        ["english"] = { [1] = "We use many animal pelts and skins in our creations. " },
        ["text"] = "У своїх виробах ми використовуємо багато хутра й шкур тварин. ",
        ["npcs"] = { [1] = 2855 },
        ["roles"] = { ["greeting"] = true },
    },
    [3747073403] = {
        ["english"] = { [1] = "What task?" },
        ["text"] = "Яке завдання?",
        ["npcs"] = { [1] = 14469 },
        ["roles"] = { ["reply"] = true },
    },
    [3180968018] = {
        ["english"] = { [1] = "Thrown" },
        ["text"] = "Метальна зброя",
        ["npcs"] = { [1] = 11865, [2] = 11867, [3] = 11869, [4] = 11870 },
        ["roles"] = { ["reply"] = true },
    },
    [475913568] = {
        ["english"] = { [1] = "Welcome to me camp, $r.$b$bShe don't look like much, but she's home fer now." },
        ["text"] = "Ласкаво просимо до мого табору, $r.$b$bВиглядає він не надто розкішно, але поки що це дім.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2476130227] = {
        ["english"] = { [1] = "Where is Elder High Mountain?" },
        ["text"] = "Де старійшина Висока Гора?",
        ["npcs"] = { [1] = 15572, [2] = 15575, [3] = 15582, [4] = 15597, [5] = 15604 },
        ["roles"] = { ["reply"] = true },
    },
    [2690376095] = {
        ["english"] = { [1] = "Toshley's Station is the best!  The solitude and supply of strange, Outland power sources is an ideal setting for extreme experiments!" },
        ["text"] = "Станція Тошлі — найкраще місце! Самота й запас дивних джерел енергії з Позамежжя створюють ідеальні умови для надзвичайних експериментів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2754493406] = {
        ["english"] = { [1] = "What should we do next?" },
        ["text"] = "Що нам робити далі?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3889109503] = {
        ["english"] = { [1] = "What roles?" },
        ["text"] = "Які ролі?",
        ["npcs"] = { [1] = 9077 },
        ["roles"] = { ["reply"] = true },
    },
    [1954840121] = {
        ["english"] = { [1] = "Where is Elder Starweave?" },
        ["text"] = "Де старійшина Зореплет?",
        ["npcs"] = { [1] = 15598, [2] = 15603, [3] = 15605 },
        ["roles"] = { ["reply"] = true },
    },
    [3775474245] = {
        ["english"] = { [1] = "Where better to look for a dark and brooding lot, than the dark section of Ironforge, aptly named The Forlorn Cavern.  Thistleheart is sure to be found there, likely summoning some manner of vile creature to do his bidding." },
        ["text"] = "Де ще шукати похмурий і задумливий народ, як не в похмурій частині Стальгорна, влучно названій Закинутою печерою. Тіслгарт точно там — мабуть, викликає якусь мерзенну тварюку виконувати його накази.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [3486238387] = {
        ["english"] = { [1] = "We are under direct orders from Cairne, $r. Do not interfere with the Commander's task." },
        ["text"] = "Ми діємо за прямим наказом Керна, $r. Не втручайся у справу Командира.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3840117898] = {
        ["english"] = { [1] = "What mysteries of the trade can I help you uncover today?" },
        ["text"] = "Які таємниці ремесла допомогти тобі розкрити сьогодні?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [342610378] = {
        ["english"] = { [1] = "What must I do?" },
        ["text"] = "Що я мушу зробити?",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["reply"] = true },
    },
    [3399829585] = {
        ["english"] = { [1] = "What am I doing?  Do you lack vision?  I am a dreamer, good $g sir : lady;, and I dream of a better future for us all.  Clearly, I am a visionary.$B$BThere are those, however, who seek to keep us mired in banality.  I told him that I was a dreamer, and Arch Druid Staghelm replied, \"Well, the world needs ditch diggers too.\"$B$BUntil such time as the shackles of banality are ripped from us, I will help the Cenarion Circle by shuffling these piles of dirt around." },
        ["text"] = "Що я роблю? Невже тобі бракує бачення? Я мрійник, $g пане : пані;, і мрію про краще майбутнє для всіх нас. Очевидно, я провидець.$B$BТа є ті, хто хоче, щоб ми й надалі грузли в банальності. Я сказав, що я мрійник, а архідруїд Оленеріг відповів: «Ну, світові потрібні й копачі канав». $B$BДоки кайдани банальності не буде зірвано, я допомагатиму Кенарієвому Колу, перекладаючи ці купи землі з місця на місце.",
        ["npcs"] = { [1] = 9047 },
        ["roles"] = { ["greeting"] = true },
    },
    [1386757712] = {
        ["english"] = { [1] = "What little remained of Thunderaan's essence was stored within a talisman of elemental binding. Ragnaros then shattered the talisman in two flawless pieces. The pieces assigned to his Lieutenants...\010" },
        ["text"] = "Те небагато, що лишилося від сутності Тундераана, було збережено в талісмані стихійного поневолення. Потім Раґнарос розколов талісман на дві бездоганні половини. Ці частини він віддав своїм лейтенантам...\010",
        ["npcs"] = { [1] = 14347 },
        ["roles"] = { ["greeting"] = true },
    },
    [759174965] = {
        ["english"] = { [1] = "What kin I do for ya, mon?" },
        ["text"] = "Чим можу допомогти, мон?",
        ["npcs"] = { [1] = 3154, [2] = 3406, [3] = 3407, [4] = 3408 },
        ["roles"] = { ["greeting"] = true },
    },
    [3608367202] = {
        ["english"] = { [1] = "We are launching an assault on Bash'ir Landing, to study their Crystalforge.  Help us if you can!  Our Skyguard Aether-tech will leave in about $4581d." },
        ["text"] = "Ми готуємо напад на Табір Баш'іра, щоб дослідити їхню Кришталеву кузню. Допоможи нам, якщо можеш! Наш ефіротех Небесної варти вирушить приблизно за $4581d.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2952165899] = {
        ["english"] = { [1] = "Well met, friend.  I am Officer Garush, and I am a proud member of a world-wide organization known as the Argent Dawn.  Our cause is to fight swiftly and mercilessly against any element of evil that surfaces in Azeroth.  We are not a political body, nor do we ever wish to become one.  Our cause is singular, and to that end we call both the Horde and Alliance as friends - friends in the cause of stamping out evil!$B$BFor the Dawn, my $g brother : sister;!" },
        ["text"] = "Вітаю, друже. Я офіцер Ґаруш і гордий член всесвітньої організації, відомої як Сріблястий Світанок. Наша мета — швидко й нещадно боротися з будь-яким злом, що з'являється в Азероті. Ми не політична організація й ніколи не прагнемо нею стати. Наша мета одна, і заради неї ми називаємо друзями і Орду, і Альянс — друзями у справі викорінення зла!$B$BЗа Світанок, $g брате : сестро;!",
        ["npcs"] = { [1] = 10839 },
        ["roles"] = { ["greeting"] = true },
    },
    [3193560141] = {
        ["english"] = { [1] = "We are a people without a home to call our own now." },
        ["text"] = "Тепер ми — народ без власної домівки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3058133089] = {
        ["english"] = { [1] = "Welcome to Blue Moon Odds and Ends, $c.  If you have any questions, please let me know." },
        ["text"] = "Ласкаво просимо до «Дрібничок Блакитного Місяця», $c. Якщо матимеш запитання — звертайся.",
        ["npcs"] = { [1] = 7683 },
        ["roles"] = { ["greeting"] = true },
    },
    [3552068597] = {
        ["english"] = { [1] = "Un'Goro Crater be far to the south of Kalimdor. Beyond the Thousand Needles in Tanaris. Look for the large floating stones... they mark the entrance to the Crater. But be careful... it is no easy path. The raptors are not far from the entrance." },
        ["text"] = "Кратер Ун'Ґоро далеко на півдні Калімдору. За Тисячею Голок, у Танарісі. Шукай великі ширяючі камені... вони позначають вхід до кратера. Але будь обережний... шлях нелегкий. Раптори блукають зовсім недалеко від входу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1509983469] = {
        ["english"] = { [1] = "Time was when I'd pull yer heart out ya just ta see da look on yer face...." },
        ["text"] = "Колись я б вирвав тобі серце просто заради того, щоб побачити вираз твого обличчя....",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [945908431] = {
        ["english"] = { [1] = "What happens when the Earthen destabilize?" },
        ["text"] = "Що відбувається, коли земельники дестабілізуються?",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [2800301555] = {
        ["english"] = { [1] = "We're celebrating spring during Noblegarden. Affirmation of life and all that." },
        ["text"] = "Під час Садочуду ми святкуємо весну. Утвердження життя й усе таке.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [238963260] = {
        ["english"] = { [1] = "Well, I declare! It's a new student! I'll gladly teach you everything I know once you have a little more skill. Go talk to Gretta Finespindle over there, would you? She'll have you up to speed in no time." },
        ["text"] = "О, дивіться-но! Новий учень! Я залюбки навчу тебе всього, що знаю, щойно ти трохи підвищиш майстерність. Поговори он там із Ґреттою Тонкопряд, добре? Вона швидко підтягне твої навички.",
        ["npcs"] = { [1] = 5127 },
        ["roles"] = { ["greeting"] = true },
    },
    [2033104895] = {
        ["english"] = { [1] = "What ISN'T there to do, you mean!$B$BEach of the innkeepers throughout the world are handing out trick-or-treat goodies, and many of the towns are decorated for the season!  Also, Sergeant Hartman in Southshore needs help against the Forsaken and their Wickerman Festival.$B$BOne more thing - I've heard that a sick little boy at the orphanage in Stormwind is looking for someone to help him gather treats for the holiday." },
        ["text"] = "Ти хотів сказати, чого тут НЕ робити!$B$BГосподарі таверн по всьому світу роздають ласощі за «цукерку чи капость», а багато міст прикрашені до свята! Крім того, сержант Гартман у Південнобережжі потребує допомоги проти Відречених та їхнього Свята Плетеного Чоловіка.$B$BІ ще одне — я чув, що хворий хлопчик у сиротинці Штормовію шукає когось, хто допоможе йому назбирати святкових ласощів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3513290615] = {
        ["english"] = { [1] = "Yah, mon, this be the time to be glad of life and spring. Ya collect lots of eggs yet?" },
        ["text"] = "Ага, мон, саме час радіти життю й весні. Багато яєць уже зібрав?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3968574720] = {
        ["english"] = { [1] = "We broke up afterward, that's what happened. Too much bad blood, I guess...it had been building for a while. And the thing with the amulet was the straw that broke the kodo's back.$B$BEver since then Valthalak's servants have been picking us off one by one. Most of the amulet piece holders are dead, their souls corrupted by the portion of Valthalak's spirit contained within it.$B$BThat's why I'm glad that you're here, $N. With your help we'll be able to recombine the amulet and return it to Lord Valthalak!" },
        ["text"] = "Після того ми розійшлися — ось що сталося. Надто багато неприязні, мабуть... вона накопичувалася вже давно. А історія з амулетом стала останньою краплею.$B$BВідтоді слуги Валталака винищують нас одного за одним. Більшість власників уламків амулета мертві, а їхні душі осквернені часткою духу Валталака, що містилася всередині.$B$BСаме тому я радий, що ти тут, $N. З твоєю допомогою ми зможемо з'єднати амулет і повернути його лорду Ваталак!",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [3409286299] = {
        ["english"] = { [1] = "Very well. It is done." },
        ["text"] = "Гаразд. Готово.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [598285671] = {
        ["english"] = { [1] = "What is this plan?" },
        ["text"] = "Що це за план?",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["reply"] = true },
    },
    [1384155501] = {
        ["english"] = { [1] = "Will you help us in our time of great need at Arathi Basin, $c?  The chance for increased honor and standing is greater than ever, and your assistance is sure to help to turn the tide against The Defilers.  Can we count on you?" },
        ["text"] = "Допоможеш нам у скрутний час у Низині Араті, $c? Шанс здобути більше честі й вищий статус як ніколи великий, а твоя допомога точно допоможе переломити хід боротьби проти Осквернителів. Можемо на тебе розраховувати?",
        ["npcs"] = { [1] = 14991 },
        ["roles"] = { ["greeting"] = true },
    },
    [268912615] = {
        ["english"] = { [1] = "Unexpected that you are all capable of such organization. Both the Alliance and the Horde have completed their preparations for the Ahn'Qiraj War. Even as we speak the materiel is being shipped over to Silithus and should all arrive within $2113w days. Then it is up to the one who is going to reassemble the Scepter of the Shifting Sands to beat on the gong at the Scarab Dais and open the gates of Ahn'Qiraj. That is when the war will truly begin!" },
        ["text"] = "Неочікувано, що ви всі здатні на таку організацію. І Альянс, і Орда завершили приготування до війни за Ан'Кіраж. Просто зараз припаси перевозять до Силітуса, і всі вони мають прибути протягом $2113w днів. Далі все залежатиме від того, хто збере докупи Скіпетр Мінливих Пісків, ударить у гонг на Помості Скарабея й відчинить брами Ан'Кіражу. От тоді війна почнеться по-справжньому!",
        ["npcs"] = { [1] = 15539, [2] = 15707 },
        ["roles"] = { ["greeting"] = true },
    },
    [906556831] = {
        ["english"] = { [1] = "What is the ultimate ability of the Emerald Drake?" },
        ["text"] = "Яка найпотужніша здібність Смарагдового драка?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3141878196] = {
        ["english"] = { [1] = "We finally understood what the screams were from. The Butcher exposed us to pain that we did not know existed. He used us in countless experiments, attempting to devise a plague.$B$BThe days turned to weeks. We would have died on the first day had it not been for that cruel bastard keeping us alive through magical means." },
        ["text"] = "Нарешті ми зрозуміли, звідки лунали крики. М'ясник показав нам біль, про існування якого ми навіть не знали. Він проводив на нас незліченні досліди, намагаючись створити чуму.$B$BДні ставали тижнями. Ми померли б уже першого дня, якби той жорстокий виродок не підтримував у нас життя чарами.",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["greeting"] = true },
    },
    [1339043251] = {
        ["english"] = { [1] = "Uldum is a research facility for the Creators in their continuing efforts to enhance the biosphere of Azeroth.  Specific information regarding their work as it relates to Uldum is restricted to those individuals who possess the Plates of Uldum in their disc sets.$B$BData repositories inside the Uldum complex have been programmed to address specific experiments and data compilations; please refer to them for detailed information." },
        ["text"] = "Ульдум — дослідницький комплекс Творців, де вони продовжують роботу над удосконаленням біосфери Азероту. Докладні відомості про їхні роботи в Ульдумі доступні лише тим, хто має Плити Ульдуму у своєму комплекті дисків.$B$BСховища даних усередині комплексу Ульдум запрограмовані на окремі експерименти та добірки даних; зверніться до них по детальнішу інформацію.",
        ["npcs"] = { [1] = 7918 },
        ["roles"] = { ["greeting"] = true },
    },
    [459899451] = {
        ["english"] = { [1] = "What is it? Can't you see that I'm busy?" },
        ["text"] = "Що таке? Не бачиш, що я зайнятий?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3402591825] = {
        ["english"] = { [1] = "What is it?" },
        ["text"] = "Що таке?",
        ["npcs"] = { [1] = 5875 },
        ["roles"] = { ["greeting"] = true },
    },
    [116281021] = {
        ["english"] = { [1] = "What brings you here, $N?  We don't see too many people around these parts.  With good reason, I suppose." },
        ["text"] = "Що привело тебе сюди, $N? У цих краях нечасто бачимо людей. І, мабуть, не без причини.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2709258662] = {
        ["english"] = { [1] = "Walking down the street! Looking at my feet! Watching the leaves, fall off of the trees!" },
        ["text"] = "Йду собі вулицею! Дивлюсь собі під ноги! Дивлюся, як листя падає з дерев!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [428337966] = {
        ["english"] = { [1] = "What? Why are you bothering me? Why, I bet you can't even create a high quality robe! Go talk to Snang and come back when you're worthy of my talents!" },
        ["text"] = "Що? Чому ти мені докучаєш? Та ти, певно, навіть якісної мантії створити не можеш! Іди поговори зі Снанґом і повернися, коли будеш гідний моїх талантів!",
        ["npcs"] = { [1] = 2627, [2] = 3363 },
        ["roles"] = { ["greeting"] = true },
    },
    [790514749] = {
        ["english"] = { [1] = "Welcome, adventurer. You've come just in the nick of time." },
        ["text"] = "Ласкаво просимо, шукачу пригод. Ти прибув саме вчасно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3382617218] = {
        ["english"] = { [1] = "What is it you seek at my forge? Is it training? Do you perhaps seek the secrets of steel? The mysteries of the forge? Speak up Grunt!" },
        ["text"] = "Чого ти шукаєш у моїй кузні? Навчання? Може, таємниці сталі? Загадки горна? Говори, рубако!",
        ["npcs"] = { [1] = 3355 },
        ["roles"] = { ["greeting"] = true },
    },
    [627316936] = {
        ["english"] = { [1] = "We've taken the harbor, and this ship is a nice bonus. Too bad she's not yet sea-worthy.$B$BIn the meantime, I've been instructed to oversee the disruption of the naga on the Greengill Coast.$B$BThink you can help me out?" },
        ["text"] = "Ми захопили гавань, а цей корабель — приємний бонус. Шкода, що він ще не готовий до плавання.$B$BТим часом мені доручили керувати діями проти наг на узбережжі Зеленозябрових.$B$BДопоможеш?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4109776357] = {
        ["english"] = { [1] = "Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to teach you.$B$BIt never hurts to reaffirm one's place within what I like to call the Great Balance.  As preservers of this balance, we must strive to continually keep our minds clear and our hearts strong.  Training helps us in this regard." },
        ["text"] = "Ласкаво просимо, $g брате : сестро;. Якщо ти прийшов тренуватися, я із задоволенням тебе навчу.$B$BНіколи не завадить знову утвердити своє місце в тому, що я називаю Великою Рівновагою. Як її хранителі, ми повинні постійно тримати розум ясним, а серце сильним. Тренування допомагає нам у цьому.",
        ["npcs"] = { [1] = 3033 },
        ["roles"] = { ["greeting"] = true },
    },
    [1816277053] = {
        ["english"] = { [1] = "What is it then? Can't you see I'm a busy dwarf?" },
        ["text"] = "Ну що ще? Не бачиш, я зайнятий дворф?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2383565136] = {
        ["english"] = { [1] = "Uni-brow" },
        ["text"] = "Зрощені брови",
        ["npcs"] = { [1] = 10578 },
        ["roles"] = { ["reply"] = true },
    },
    [3022296670] = {
        ["english"] = { [1] = "What are you doing there?" },
        ["text"] = "Що ти там робиш?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2081254316] = {
        ["english"] = { [1] = "We've done it, $g lad : lass;! The Alliance and the Horde have completed gathering everything that we think we'll need for the Ahn'Qiraj War. Right now the final goods are being taken over to Cenarion Hold in Silithus and all of it will arrive within $2113w days. After that, some brave $g hero : heroine; is going to need to ring the Scarab Gong with the Scepter of the Shifting Sands to open the gates to Ahn'Qiraj. When those gates open, the war begins!" },
        ["text"] = "Ми це зробили, $g хлопче : дівчино;! Альянс і Орда зібрали все, що, на нашу думку, знадобиться для війни за Ан'Кіраж. Просто зараз останні вантажі перевозять до Кенарійської цитаделі в Силітусі, і все прибуде протягом $2113w днів. Після цього якомусь відважному $g героєві : героїні; доведеться вдарити Скіпетром Мінливих Пісків у Гонг Скарабея, щоб відчинити брами Ан'Кіражу. Коли брами відчиняться — почнеться війна!",
        ["npcs"] = { [1] = 15701, [2] = 15703 },
        ["roles"] = { ["greeting"] = true },
    },
    [4086452129] = {
        ["english"] = { [1] = "What is it that you want, lemming? Get out of my sight before you find out why I am known as the Wrathcaster." },
        ["text"] = "Чого тобі треба, лемінгу? Зникни з моїх очей, поки не дізнався, чому мене звуть Заклиначем Гніву.",
        ["npcs"] = { [1] = 16133 },
        ["roles"] = { ["greeting"] = true },
    },
    [2885258662] = {
        ["english"] = { [1] = "Welcome to Fairbreeze Village.  Silvermoon's all but given up on us, but we refuse to leave.  This is our home." },
        ["text"] = "Ласкаво просимо до селища Чистий Вітер. Срібномісяць майже махнув на нас рукою, але ми не підемо. Це наш дім.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3667565177] = {
        ["english"] = { [1] = "Why should I bother fixing the trap?  Why not just eliminate the guard the old fashioned way?" },
        ["text"] = "Навіщо мені лагодити пастку? Чому просто не усунути вартового старим добрим способом?",
        ["npcs"] = { [1] = 14338 },
        ["roles"] = { ["reply"] = true },
    },
    [483527959] = {
        ["english"] = { [1] = "What is happening to everyone?  I feel... cold..." },
        ["text"] = "Що з усіма відбувається? Мені... холодно...",
        ["npcs"] = { [1] = 10778 },
        ["roles"] = { ["greeting"] = true },
    },
    [12048061] = {
        ["english"] = { [1] = "Well, aren't you the smarty-pants? Ye know more than I do, I can tell ye that! Don't go getting' a big head, but if ye want to keep learnin', have a chat with Georgio Bolero in Stormwind. They say he knows his tailorin'!" },
        ["text"] = "О, та ти розумник! Знаєш більше за мене, це точно! Тільки не задирай носа, а якщо хочеш вчитися далі — поговори з Джорджіо Болеро в Штормовії. Кажуть, він знається на кравецтві!",
        ["npcs"] = { [1] = 5153 },
        ["roles"] = { ["greeting"] = true },
    },
    [2601780251] = {
        ["english"] = { [1] = "What be happening?$B$BYou here to eat, mon? Or maybe to learn cooking from the best, eh?" },
        ["text"] = "Що відбувається?$B$BТи прийшов поїсти, мон? Чи, може, навчитися готувати в найкращого, га?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2150454135] = {
        ["english"] = { [1] = "Use the outhouse." },
        ["text"] = "Скористатися нужником.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [4127135671] = {
        ["english"] = { [1] = "What is Dreadnaught armor?" },
        ["text"] = "Що таке обладунок Дредноута?",
        ["npcs"] = { [1] = 16112 },
        ["roles"] = { ["reply"] = true },
    },
    [2236968224] = {
        ["english"] = { [1] = "To Malyfous, I assume." },
        ["text"] = "До Маліфуса, гадаю.",
        ["npcs"] = { [1] = 10776 },
        ["roles"] = { ["reply"] = true },
    },
    [509756693] = {
        ["english"] = { [1] = "What is Atiesh?", [2] = "What is Atiesh?\010" },
        ["text"] = "Що таке Атієш?",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["reply"] = true },
    },
    [919263168] = {
        ["english"] = { [1] = "What is an Alliance Commendation Signet?" },
        ["text"] = "Що таке Печатка Відзнаки Альянсу?",
        ["npcs"] = { [1] = 15383, [2] = 15431, [3] = 15432, [4] = 15434, [5] = 15437, [6] = 15445, [7] = 15446, [8] = 15448, [9] = 15450, [10] = 15451, [11] = 15452, [12] = 15453, [13] = 15455, [14] = 15456, [15] = 15457 },
        ["roles"] = { ["reply"] = true },
    },
    [3013173147] = {
        ["english"] = { [1] = "What are you doing out here?" },
        ["text"] = "Що ти робиш тут, назовні?",
        ["npcs"] = { [1] = 9047 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true },
    },
    [4048069728] = {
        ["english"] = { [1] = "What is a \"resilient foundation of construction\"?" },
        ["text"] = "Що таке «стійка основа конструкції»?",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [279200956] = {
        ["english"] = { [1] = "Uh... I sorry I attack you boss.  You no kill me, please OK!?  You da king now, and I help make your tribute better!" },
        ["text"] = "Е-е... я вибачай, що напав на тебе, бос. Ти мене не вбивай, добре!? Тепер ти король, ти новий бос! А я допоможу зробити твою данину кращою!",
        ["npcs"] = { [1] = 14324, [2] = 14353 },
        ["roles"] = { ["greeting"] = true },
    },
    [3152017178] = {
        ["english"] = { [1] = "Welcome to the Stormwind Guild Registry offices. What can I help you with today?" },
        ["text"] = "Ласкаво просимо до відділення реєстрації гільдій Штормовію. Чим можу допомогти сьогодні?",
        ["npcs"] = { [1] = 4974, [2] = 5193 },
        ["roles"] = { ["greeting"] = true },
    },
    [449581199] = {
        ["english"] = { [1] = "What if I don't like drinking...  Is there another way I can help out?" },
        ["text"] = "А якщо я не люблю пити... Є інший спосіб допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2916100748] = {
        ["english"] = { [1] = "What I wouldn't give to be out on the open plains on a day like this... but, my duty binds me." },
        ["text"] = "Чого б я тільки не віддав, щоб у такий день бути на відкритих рівнинах... але мене тримає обов'язок.",
        ["npcs"] = { [1] = 11071 },
        ["roles"] = { ["greeting"] = true },
    },
    [318541074] = {
        ["english"] = { [1] = "What high-stress environments would cause the Earthen to destabilize?" },
        ["text"] = "Які умови сильного стресу можуть спричинити дестабілізацію земельників?",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [1669305534] = {
        ["english"] = { [1] = "Welcome to our shop.  We have everything you need... if you need alchemy supplies." },
        ["text"] = "Ласкаво просимо до нашої крамниці. У нас є все, що тобі потрібно... якщо тобі потрібне алхімічне приладдя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1495701693] = {
        ["english"] = { [1] = "What happens if your snot freezes in your nose?" },
        ["text"] = "Що буде, якщо соплі замерзнуть у носі?",
        ["npcs"] = { [1] = 14305 },
        ["roles"] = { ["greeting"] = true },
    },
    [1069820375] = {
        ["english"] = { [1] = "Well, well... look what the cat brung in... and how can I help you, $c?" },
        ["text"] = "Ну-ну... і кого це кішка принесла... Чим можу допомогти, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3040787930] = {
        ["english"] = { [1] = "What happened to him in the first place?  When I... encountered him, he was rather malicious." },
        ["text"] = "А що з ним узагалі сталося? Коли я... зустрів його, він був доволі зловісним.",
        ["npcs"] = { [1] = 5353 },
        ["roles"] = { ["reply"] = true },
    },
    [183700846] = {
        ["english"] = { [1] = "What brings you all the way up here, little $r?" },
        ["text"] = "Що привело тебе аж сюди, маленький $r?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2543129729] = {
        ["english"] = { [1] = "What happened to her after that?" },
        ["text"] = "Що сталося з нею після того?",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["reply"] = true },
    },
    [118469253] = {
        ["english"] = { [1] = "Want us to help with something? What we help with? We good at helping." },
        ["text"] = "Хочеш, щоб ми з чимось допомогли? З чим допомогти? Ми добре допомагаємо.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1214293965] = {
        ["english"] = { [1] = "What happened here, spirit?" },
        ["text"] = "Що тут сталося, духу?",
        ["npcs"] = { [1] = 14358 },
        ["roles"] = { ["reply"] = true },
    },
    [1843886630] = {
        ["english"] = { [1] = "We're preparing for war, $c. We've taken all that we're going to from the Silithid and their masters in Ahn'Qiraj. To get ready for it we're collecting all sorts of material. I'm in charge of gathering Arthas' Tears. Not sure what we need them for though. If you ask me I don't want anything to do with that madman, even if it is just a flower named after him.$B$BStill, I'm my father's daughter, and a soldier, so I do what I'm told. Currently we have $2057w and need to collect a grand total of $2058w." },
        ["text"] = "Ми готуємося до війни, $c. Досить уже терпіти силітидів та їхніх господарів з Ан'Кіражу. Для підготовки ми збираємо всілякі матеріали. Я відповідаю за Сльози Артаса. Щоправда, навіщо вони нам — не знаю. Як на мене, я б не хотіла мати нічого спільного з тим божевільним, навіть якщо це всього лише квітка, названа на його честь.$B$BТа я донька свого батька й солдат, тому виконую наказ. Наразі в нас $2057w, а загалом треба зібрати $2058w.",
        ["npcs"] = { [1] = 15445 },
        ["roles"] = { ["greeting"] = true },
    },
    [1310523075] = {
        ["english"] = { [1] = "Valley of Trials will temper even the weakest into a warrior worthy to join the Horde. Those who cannot rise to its tests will be left to bake in the scorching desert sun." },
        ["text"] = "Долина Випробувань загартує навіть найслабшого й зробить із нього воїна, гідного вступити до Орди. Ті, хто не впорається з її випробуваннями, залишаться пектися під палючим сонцем пустелі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3382876231] = {
        ["english"] = { [1] = "What Guardian? I don't understand any of this." },
        ["text"] = "Який Вартовий? Я нічого з цього не розумію.",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["reply"] = true },
    },
    [39769868] = {
        ["english"] = { [1] = "What, may I ask, are you doing here?  Put on your student's attire, and study!" },
        ["text"] = "Дозволь запитати, що ти тут робиш? Одягни учнівське вбрання й учися!",
        ["npcs"] = { [1] = 10432 },
        ["roles"] = { ["greeting"] = true },
    },
    [2916789597] = {
        ["english"] = { [1] = "What's needed for the cauldron at the Writhing Haunt?" },
        ["text"] = "Що потрібно для котла в Корчистому Пристанищі?",
        ["npcs"] = { [1] = 11056, [2] = 11057 },
        ["roles"] = { ["reply"] = true },
    },
    [3931011235] = {
        ["english"] = { [1] = "Time to play some troll tag, mon!" },
        ["text"] = "Час трохи побавитися в тролячу квач, мон!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1365605492] = {
        ["english"] = { [1] = "Welcome to my kitchen! We prepare some of the finest food in Dalaran here." },
        ["text"] = "Ласкаво просимо на мою кухню! Тут ми готуємо одні з найкращих страв у Даларані.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1354709520] = {
        ["english"] = { [1] = "To catch Gahz'ranka, you'll need a special Mudskunk lure.  I make 'em myself!$B$BBut you need more than just the lure; you need some mudskunks too... you need to place them in the lure to give it a rank old smell!$B$BWhen you have the mudskunks, throw the lure off Pagle's Point in Zul'Gurub... and then grab a drink and wait... but not too long, because Gahz'ranka is sure to come a'stomping!" },
        ["text"] = "Щоб упіймати Газ'ранку, тобі знадобиться особлива приманка з багноскунсів. Я роблю її власноруч!$B$BАле самої приманки замало — потрібні ще й багноскунси... їх треба покласти всередину, щоб надати їй добрячого старого смороду!$B$BКоли матимеш багноскунсів, кинь приманку з точки Пеґла в Зул'Ґурубі... тоді налий собі чогось випити й чекай... тільки недовго, бо Газ'ранка неодмінно притупає!",
        ["npcs"] = { [1] = 12919 },
        ["roles"] = { ["greeting"] = true },
    },
    [1697414521] = {
        ["english"] = { [1] = "Welcome to the camp, $c." },
        ["text"] = "Ласкаво просимо до табору, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3591802853] = {
        ["english"] = { [1] = "Where is Elder Goldwell?" },
        ["text"] = "Де старійшина Золотий Колодязь?",
        ["npcs"] = { [1] = 15558, [2] = 15567, [3] = 15871 },
        ["roles"] = { ["reply"] = true },
    },
    [1123419688] = {
        ["english"] = { [1] = "Us no like paladins. Elf lady come to city, stay in Royal Quarter. Her paladin. You talk, learn paladin things." },
        ["text"] = "Ми не любимо паладинів. Ельфійка прийшла в місто, живе в Королівському кварталі. Вона паладин. Поговориш — навчишся паладинських справ.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [224594773] = {
        ["english"] = { [1] = "What does it look like?  The ground is frozen like a rock!$B$BThe wheels on these meatwagons were built to go over mud at best.  We're going to need an abomination and some chains to salvage them." },
        ["text"] = "На що це схоже? Земля промерзла, мов камінь!$B$BКолеса цих м'ясних возів у кращому разі розраховані на багнюку. Щоб їх витягти, нам знадобляться потвора й кілька ланцюгів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2797231595] = {
        ["english"] = { [1] = "We cannot thank you enough for everything you've done to protect our family, $N.$B$BAnd, you do realize that we were joking before when we offered to sell you one of our sons?  No, really... although we do feel a couple more headaches coming on.$B$BJunior, be still, will you?!" },
        ["text"] = "Нам не вистачить слів, щоб подякувати тобі за все, що ти зробив для захисту нашої родини, $N.$B$BІ ти ж розумієш, що ми жартували, коли пропонували продати тобі одного з наших синів? Справді... хоча, здається, у нас знову починається головний біль.$B$BМолодший, та сиди ж спокійно!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1345649970] = {
        ["english"] = { [1] = "What does \"zug zug\" mean?" },
        ["text"] = "Що означає «зук-зук»?",
        ["npcs"] = { [1] = 14444 },
        ["roles"] = { ["greeting"] = true },
    },
    [1934197222] = {
        ["english"] = { [1] = "What do you want?" },
        ["text"] = "Чого тобі?",
        ["npcs"] = { [1] = 11177 },
        ["roles"] = { ["greeting"] = true },
    },
    [1721133409] = {
        ["english"] = { [1] = "What do you want, $c? I'm running late, and my employer doesn't look kindly on tardiness." },
        ["text"] = "Чого тобі, $c? Я запізнююся, а мій роботодавець не любить запізнень.",
        ["npcs"] = { [1] = 6497 },
        ["roles"] = { ["greeting"] = true },
    },
    [1087375110] = {
        ["english"] = { [1] = "We shall be in your debt $c.  Look for Donal Osgood in the Hall of Arms.  He will be more than happy to aid you in your journey to Arathi Basin." },
        ["text"] = "Ми будемо в боргу перед тобою, $c. Шукай Донала Осґуда в Залі Зброї. Він залюбки допоможе тобі вирушити до Низини Араті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2910457474] = {
        ["english"] = { [1] = "What do you seek, $c?" },
        ["text"] = "Чого ти шукаєш, $c?",
        ["npcs"] = { [1] = 11558 },
        ["roles"] = { ["greeting"] = true },
    },
    [3504618553] = {
        ["english"] = { [1] = "What do you represent, spirit?" },
        ["text"] = "Кого ти представляєш, духу?",
        ["npcs"] = { [1] = 11956 },
        ["roles"] = { ["reply"] = true },
    },
    [1262318310] = {
        ["english"] = { [1] = "Ya may not follow the ways of the Light like a Knight of the Silver Hand, but ya can always ask us for aid." },
        ["text"] = "Можеш і не йти шляхом Світла, як Лицар Срібної Десниці, але завжди можеш просити нас про допомогу.",
        ["npcs"] = { [1] = 926, [2] = 1232, [3] = 5147, [4] = 5148, [5] = 5149 },
        ["roles"] = { ["greeting"] = true },
    },
    [3227807520] = {
        ["english"] = { [1] = "Well now, $g lad : lass;, it looks like the Alliance has already gathered up all that we need for our part of the war. I know that the blacksmiths, engineers and everyone else is busy with the final preparations, and as soon as the Horde assembles all of their goods, it will all be sent to Silithus for the war." },
        ["text"] = "Ну що, $g хлопче : дівчино;, схоже, Альянс уже зібрав усе потрібне для своєї частини війни. Знаю, що ковалі, інженери та всі інші завершують останні приготування, і щойно Орда збере свої припаси, усе відправлять до Силітуса на війну.",
        ["npcs"] = { [1] = 15446 },
        ["roles"] = { ["greeting"] = true },
    },
    [1401611015] = {
        ["english"] = { [1] = "When I first set up my rogue academy in Shattrath, it wasn't nearly this crowded. Then, the refugees started flooding in and the naaru needed every available building to house them.$B$BI've closed the doors to my academy for now, but it's not permanent. I'll find a new place to set up.$B$BThen, a new generation of rogues will learn such staples as the gouge'n grin, combat looting, and blaming someone else for breaking polymorph. And who can forget the central rule of roguery --- real rogues don't feint." },
        ["text"] = "Коли я вперше відкрив свою академію розбійників у Шаттраті, тут не було так людно. Потім почали прибувати біженці, й наару знадобилася кожна вільна будівля, щоб їх розмістити.$B$BПоки що я закрив академію, але це не назавжди. Знайду нове місце.$B$BТоді нове покоління розбійників опанує такі основи, як «виколи й усміхнися», бойове мародерство та звинувачення когось іншого в тому, що поліморфію зірвали. І хто забуде головне правило розбійника — справжні розбійники не фінтують.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [684781834] = {
        ["english"] = { [1] = "What do you mean?" },
        ["text"] = "Що ти маєш на увазі?",
        ["npcs"] = { [1] = 3144, [2] = 4542, [3] = 11216 },
        ["roles"] = { ["reply"] = true },
    },
    [3511838026] = {
        ["english"] = { [1] = "We need adventurers to assist us, $N. Will you help?" },
        ["text"] = "Нам потрібна допомога шукачів пригод, $N. Допоможеш?",
        ["npcs"] = { [1] = 8879 },
        ["roles"] = { ["greeting"] = true },
    },
    [741369887] = {
        ["english"] = { [1] = "With the cauldrons breeched, we are now able to introduce the counter agent into the environment.  This should give the scourge a taste of their own medicine, as it were!$B$BCheck with Apothecary Dithers on information regarding the reagents needed to use in the cauldrons.  I will be handling all information reports on how we are doing overall in turning the plague against the Scourge!" },
        ["text"] = "Котли пробито, тож тепер ми можемо ввести протидійний реагент у довкілля. Нехай Скара скуштує власних ліків!$B$BЗапитай аптекаря Дітерса про реагенти, потрібні для котлів. Я збиратиму всі звіти про наш загальний успіх у поверненні чуми проти Скари!",
        ["npcs"] = { [1] = 11055 },
        ["roles"] = { ["greeting"] = true },
    },
    [914959689] = {
        ["english"] = { [1] = "Welcome! Step right up, don't be shy. This here is my pride and joy... the Blastenheimer 5000 Ultra Cannon! Ain't she pretty? You look a little big around the mid section, but I think you'll fit. Flying is so much fun, want to learn how?" },
        ["text"] = "Вітаю! Підходь ближче, не соромся. Ось моя гордість і радість... Ультрагармата Бластенгаймера 5000! Красуня, еге ж? Ти трохи широкий у талії, але, думаю, вмістишся. Літати так весело — хочеш дізнатися як?",
        ["npcs"] = { [1] = 15303 },
        ["roles"] = { ["greeting"] = true },
    },
    [1638217621] = {
        ["english"] = { [1] = "War is upon us, $N.  It's time for every member of the Horde to answer the call and join the fight against the cowardly Alliance." },
        ["text"] = "Війна вже тут, $N. Настав час кожному члену Орди відповісти на заклик і вступити в бій проти боягузливого Альянсу.",
        ["npcs"] = { [1] = 15350 },
        ["roles"] = { ["greeting"] = true },
    },
    [3377490539] = {
        ["english"] = { [1] = "What do you mean by \"pure?\"" },
        ["text"] = "Що ти маєш на увазі під «чистим»?",
        ["npcs"] = { [1] = 9616 },
        ["roles"] = { ["reply"] = true },
    },
    [1972680089] = {
        ["english"] = { [1] = "What do you know of it?" },
        ["text"] = "Що ти про це знаєш?",
        ["npcs"] = { [1] = 14347 },
        ["roles"] = { ["reply"] = true },
    },
    [2021293273] = {
        ["english"] = { [1] = "What's wrong, bonebag? Looking for someone else? I'm all you've got now, so if you want something, make it quick." },
        ["text"] = "Що таке, кістяний мішку? Шукаєш когось іншого? Тепер у тебе є лише я, тож якщо щось треба — швидше.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1031179655] = {
        ["english"] = { [1] = "Where is Elder Winterhoof?" },
        ["text"] = "Де старійшина Зимове Копито?",
        ["npcs"] = { [1] = 15557, [2] = 15577, [3] = 15593, [4] = 15596 },
        ["roles"] = { ["reply"] = true },
    },
    [452113575] = {
        ["english"] = { [1] = "When the Darkmoon Faire arrives, where will it be located?" },
        ["text"] = "Коли прибуде ярмарок Темного Місяця, де він буде?",
        ["npcs"] = { [1] = 14843 },
        ["roles"] = { ["reply"] = true },
    },
    [2841651298] = {
        ["english"] = { [1] = "What brings you to the Tower?" },
        ["text"] = "Що привело тебе до Вежі?",
        ["npcs"] = { [1] = 11072 },
        ["roles"] = { ["greeting"] = true },
    },
    [1804061001] = {
        ["english"] = { [1] = "What do I care if these she-wolves and the frost giants kill each other every day?$B$BNo, no... I want Thorim to break out of his stupor and rally all his allies to retake Ulduar.$B$BThe world will be torn asunder if he fails to accomplish this!$B$BAnd of course, I'll reward you appropriately." },
        ["text"] = "Та що мені до того, якщо ці вовчиці й крижані велетні щодня вбивають одне одного?$B$BНі, ні... Я хочу, щоб Торім вирвався зі свого заціпеніння й зібрав усіх союзників, щоб відбити Ульдуар.$B$BЯкщо він не впорається, світ буде розірваний навпіл!$B$BІ, звісно, я належно тебе винагороджу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2893666758] = {
        ["english"] = { [1] = "Where is Elder Skychaser?" },
        ["text"] = "Де старійшина Небогін?",
        ["npcs"] = { [1] = 15565, [2] = 15576, [3] = 15593 },
        ["roles"] = { ["reply"] = true },
    },
    [1176448729] = {
        ["english"] = { [1] = "Welcome to the Grim Guzzler!" },
        ["text"] = "Ласкаво просимо до «Похмурого Наливальника»!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [338940648] = {
        ["english"] = { [1] = "What are Darkmoon Faire Prize Tickets and how do I get them?" },
        ["text"] = "Що таке призові квитки ярмарку Темного Місяця і як їх отримати?",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["reply"] = true },
    },
    [2339154219] = {
        ["english"] = { [1] = "What demands?" },
        ["text"] = "Які вимоги?",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["reply"] = true },
    },
    [131014342] = {
        ["english"] = { [1] = "What are you lookin' at?" },
        ["text"] = "Чого витріщився?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1840821161] = {
        ["english"] = { [1] = "What deal?" },
        ["text"] = "Яка угода?",
        ["npcs"] = { [1] = 10918 },
        ["roles"] = { ["reply"] = true },
    },
    [1455798642] = {
        ["english"] = { [1] = "Well met, $r. I am here as a resource of advice for the High Executor to make use of as he will. I am confident that together we can forge the Horde into something that is even stronger than before and turn back the Scourge menace once and for all!" },
        ["text"] = "Вітаю, $r. Я тут, щоб за потреби давати поради Верховному Виконавцю. Упевнений, разом ми зробимо Орду сильнішою, ніж будь-коли, й назавжди відкинемо загрозу Скари!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3267427999] = {
        ["english"] = { [1] = "What's needed for the cauldron at Dalson's Tears?" },
        ["text"] = "Що потрібно для котла на Сльозах Далсонів?",
        ["npcs"] = { [1] = 11056, [2] = 11057 },
        ["roles"] = { ["reply"] = true },
    },
    [2328286379] = {
        ["english"] = { [1] = "We have only a small foothold on this continent for now, but the humans can't fight us off forever. Then they'll pay for enslaving us. We'll cut their lying tongues out for their treachery." },
        ["text"] = "Поки що на цьому континенті в нас лише невеликий плацдарм, але люди не зможуть відбиватися від нас вічно. Тоді вони заплатять за те, що поневолили нас. За їхню зраду ми повирізаємо їм брехливі язики.",
        ["npcs"] = { [1] = 1385 },
        ["roles"] = { ["greeting"] = true },
    },
    [2597082699] = {
        ["english"] = { [1] = "Well, ye won't have much luck with finding a tailor out here.  Ironforge is home to a quite a few talented tailors though.  Why don't ye go ask a guard there." },
        ["text"] = "Тут кравця навряд чи знайдеш. Зате в Стальгорні є чимало талановитих кравців. Чому б не спитати тамтешнього вартового?",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [3761128825] = {
        ["english"] = { [1] = "Welcome, $g sir : my lady;. This is a much better camp than the one that I used to have.$B$BIt's good to have company. They've been nice enough to teach me some of their fighting techniques so that I can hold my own against the Horde." },
        ["text"] = "Ласкаво просимо, $g пане : моя пані;. Цей табір значно кращий за той, що був у мене раніше.$B$BДобре мати товариство. Вони були досить люб'язні, щоб навчити мене кількох бойових прийомів, аби я міг постояти за себе проти Орди.",
        ["npcs"] = { [1] = 3846 },
        ["roles"] = { ["greeting"] = true },
    },
    [625931356] = {
        ["english"] = { [1] = "What could be worse than death?" },
        ["text"] = "Що може бути гірше за смерть?",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["reply"] = true },
    },
    [120668801] = {
        ["english"] = { [1] = "What corruption?" },
        ["text"] = "Яке осквернення?",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["reply"] = true },
    },
    [1821740962] = {
        ["english"] = { [1] = "Well now, ye'll need papers to form a guild, and Jondor Steelbrow can help you get started with the process.  He can be found over at the Ironforge Visitor's Center when yer ready to get started." },
        ["text"] = "Ну що, для створення гільдії тобі знадобляться документи, а Джондор Сталебров допоможе почати оформлення. Коли будеш готовий, знайдеш його в Центрі відвідувачів Стальгорна.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [649033931] = {
        ["english"] = { [1] = "Welcome to the Pig and Whistle! Grab a drink my friend and pull up a seat, the more the merrier!" },
        ["text"] = "Ласкаво просимо до «Свині й Свистка»! Бери кухоль, друже, сідай до нас — що більше народу, то веселіше!",
        ["npcs"] = { [1] = 1327 },
        ["roles"] = { ["greeting"] = true },
    },
    [916388844] = {
        ["english"] = { [1] = "Wanna buy a cockroach?" },
        ["text"] = "Хочеш купити таргана?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2415244456] = {
        ["english"] = { [1] = "Vanndar Stormpike is the general of the Alliance military in Alterac, and directs his forces from Dun Baldar.$B$BIf he is defeated then the Alliance will surely lose the battle for Alterac." },
        ["text"] = "Ванндар Грозова Вершина — генерал військ Альянсу в Альтераку, який керує силами з Дун-Балдара.$B$BЯкщо його буде переможено, Альянс напевно програє битву за Альтерак.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3879783332] = {
        ["english"] = { [1] = "What can you do at an inn?$B$BWell when you stay at an inn, you rest very comfortably.  Because of this, you will become \"well rested\" much more quickly than you would in the wilderness.  When you are well rested, you learn more from experience.$B$BYou may also speak with any innkeeper to get a hearthstone, and can later use the hearthstone in order to quickly return to that inn." },
        ["text"] = "Що можна робити в таверні?$B$BКоли ти зупиняєшся в таверні, то відпочиваєш дуже комфортно. Завдяки цьому стан «добре відпочив» набувається значно швидше, ніж у дикій місцевості. А коли добре відпочив, здобуваєш більше з досвіду.$B$BТакож можна поговорити з будь-яким господарем таверни, щоб отримати камінь повернення, а потім використовувати його для швидкого повернення до цієї таверни.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 2352, [4] = 2388, [5] = 5688, [6] = 5814, [7] = 6727, [8] = 6734, [9] = 6736, [10] = 6737, [11] = 6739, [12] = 6741, [13] = 6747, [14] = 6790, [15] = 6928, [16] = 6929, [17] = 6930, [18] = 7731, [19] = 9356, [20] = 12196, [21] = 14731, [22] = 16256 },
        ["roles"] = { ["greeting"] = true },
    },
    [1445962188] = {
        ["english"] = { [1] = "With all due respect, Warchief - why not allow them to be destroyed? Does this not strengthen our position?", [2] = "With all due respect, Warchief - why not allow them to be destroyed? Does this not strengthen our position?\010" },
        ["text"] = "З усією повагою, Вождю — чому не дозволити їх знищити? Хіба це не зміцнить нашу позицію?",
        ["npcs"] = { [1] = 4949 },
        ["roles"] = { ["reply"] = true },
    },
    [2684651509] = {
        ["english"] = { [1] = "Warchief Thrall himself asked me to come out here. I was honored to obey, and it's no hardship. I couldn't have asked for a better posting than Stonard. Just about any herb I might need grows in the muck here." },
        ["text"] = "Сам вождь Тралл попросив мене прибути сюди. Для мене було честю коритися, та й це зовсім не тягар. Кращого призначення, ніж Стонард, я й бажати не міг. У цьому багні росте майже кожна трава, яка мені може знадобитися.",
        ["npcs"] = { [1] = 1386 },
        ["roles"] = { ["greeting"] = true },
    },
    [3823556983] = {
        ["english"] = { [1] = "What can other weapon masters teach?" },
        ["text"] = "Чого можуть навчити інші майстри зброї?",
        ["npcs"] = { [1] = 2704, [2] = 11865, [3] = 11866, [4] = 11867, [5] = 11868, [6] = 11869, [7] = 11870, [8] = 13084 },
        ["roles"] = { ["reply"] = true },
    },
    [2036961567] = {
        ["english"] = { [1] = "Try some of this cherry pie, it will put a smile on your face, ten miles wide." },
        ["text"] = "Спробуй цього вишневого пирога — усмішка розтягнеться від вуха до вуха.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [703206904] = {
        ["english"] = { [1] = "What is E'ko?" },
        ["text"] = "Що таке Е'ко?",
        ["npcs"] = { [1] = 10307 },
        ["roles"] = { ["reply"] = true },
    },
    [641081138] = {
        ["english"] = { [1] = "Well, I've seen better. But, you have potential, I won't deny it. Pay attention and you just might learn something!" },
        ["text"] = "Ну, бачив я й краще. Але потенціал у тебе є, не заперечую. Слухай уважно — і, може, чогось навчишся!",
        ["npcs"] = { [1] = 4616 },
        ["roles"] = { ["greeting"] = true },
    },
    [3364298469] = {
        ["english"] = { [1] = "What can I purchase?" },
        ["text"] = "Що можна придбати?",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["reply"] = true },
    },
    [1933638899] = {
        ["english"] = { [1] = "What can I do for you, $N?  Make it quick, I don't have all day!" },
        ["text"] = "Чим можу допомогти, $N? Швидше, у мене немає цілого дня!",
        ["npcs"] = { [1] = 16416 },
        ["roles"] = { ["greeting"] = true },
    },
    [1744719116] = {
        ["english"] = { [1] = "To celebrate the birth of yet another deadly enemy is an odd thing, to say the least. Still, we will join our allies in their festivities." },
        ["text"] = "Святкувати народження ще одного смертельно небезпечного ворога — щонайменше дивно. Та все ж ми приєднаємося до наших союзників у святкуванні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [897894039] = {
        ["english"] = { [1] = "We serve Thrall with great pride.  We'll travel as far as is needed to vanquish the enemy." },
        ["text"] = "Ми з великою гордістю служимо Траллу. Підемо хоч на край світу, якщо це потрібно, щоб здолати ворога.",
        ["npcs"] = { [1] = 15612 },
        ["roles"] = { ["greeting"] = true },
    },
    [3793331283] = {
        ["english"] = { [1] = "What can I do for you my child?" },
        ["text"] = "Чим можу допомогти тобі, дитя моє?",
        ["npcs"] = { [1] = 4138 },
        ["roles"] = { ["greeting"] = true },
    },
    [4151289791] = {
        ["english"] = { [1] = "Who are the Creators?" },
        ["text"] = "Хто такі Творці?",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [1485989121] = {
        ["english"] = { [1] = "Too bad we can't skin the humans and their allies. All that skin is just going to waste. Still, who'd want to wear the flimsy leather you could make out of it?" },
        ["text"] = "Шкода, що ми не можемо знімати шкури з людей та їхніх союзників. Стільки шкіри марнується. Хоча хто б захотів носити ту хлипку шкіру, яка з них вийшла б?",
        ["npcs"] = { [1] = 5811 },
        ["roles"] = { ["greeting"] = true },
    },
    [2472456031] = {
        ["english"] = { [1] = "What can a guy like me be doin' for a $r like you at a time like this?$B" },
        ["text"] = "Що такий хлопець, як я, може зробити для такого $r, як ти, в такий час?$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [121856474] = {
        ["english"] = { [1] = "Why have I been sent back to this particular place and time?" },
        ["text"] = "Чому мене повернули саме в це місце й час?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [566600610] = {
        ["english"] = { [1] = "Welcome to the Bank of Silvermoon, $g sir : ma'am;. Would you care to access the depository?" },
        ["text"] = "Ласкаво просимо до банку Срібномісяця, $g пане : пані;. Бажаєте отримати доступ до сховища?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [365009989] = {
        ["english"] = { [1] = "We may be working together, but that only increases the need for discretion. Once again, be mindful of your words and actions.$B$BI can guarantee we're far from the only ones out here." },
        ["text"] = "Можливо, ми й працюємо разом, але це лише посилює потребу в обережності. Ще раз: стеж за словами й учинками.$B$BЗапевняю, ми тут далеко не єдині.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4062330343] = {
        ["english"] = { [1] = "What brings you to a bunch of old, washed-up desert dogs like us?" },
        ["text"] = "Що привело тебе до купки старих, списаних пустельних псів на кшталт нас?",
        ["npcs"] = { [1] = 4618 },
        ["roles"] = { ["greeting"] = true },
    },
    [537101929] = {
        ["english"] = { [1] = "What assistance can I offer in your studies?" },
        ["text"] = "Чим я можу допомогти у твоїх дослідженнях?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3163212973] = {
        ["english"] = { [1] = "What followed were a series of tragic events, leading to the death of every Kirin Tor mage that came into contact with Atiesh.$B$BYou see, it was an artifact with sentience. A sentience granted to it by Sargeras..." },
        ["text"] = "Далі сталася низка трагічних подій, що призвели до смерті кожного мага Кірін-Тору, який контактував з Атієшем.$B$BРозумієш, це був артефакт із власною свідомістю. Свідомістю, яку дарував йому Сарґерас...",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["greeting"] = true },
    },
    [1343436993] = {
        ["english"] = { [1] = "What are you still doing here? Go back to town!" },
        ["text"] = "Що ти досі тут робиш? Повертайся до міста!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3127536296] = {
        ["english"] = { [1] = "What are you looking for?" },
        ["text"] = "Що ти шукаєш?",
        ["npcs"] = { [1] = 1423, [2] = 1496, [3] = 1652, [4] = 1735, [5] = 1738, [6] = 1742, [7] = 1743, [8] = 1744, [9] = 1745, [10] = 1746, [11] = 2209, [12] = 2210, [13] = 3084, [14] = 3212, [15] = 3215, [16] = 3217, [17] = 3218, [18] = 3219, [19] = 3220, [20] = 3221, [21] = 3222, [22] = 3223, [23] = 3224, [24] = 3296, [25] = 5624, [26] = 5725, [27] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [2142031870] = {
        ["english"] = { [1] = "Well, now that you mention it, yeah, I did see something I thought was a little strange yesterday afternoon!$B$BI was running past some old troll ruins southeast of here; well, I wasn't really running, more like hopping... The sand's so hot!$B$BAnyway, so I was hopping past the ruins, when I noticed a camp set up there. Seems like a funny place to set up camp, if you ask me... I would have poked around a little more but one of those crazy big vultures chased me off." },
        ["text"] = "Ну, раз уже ти згадав, то так — учора після обіду я побачив дещо дивне!$B$BЯ пробігав повз старі тролячі руїни на південний схід звідси; хоча ні, не біг, а радше підстрибував... Пісок такий гарячий!$B$BТак от, стрибаю я повз руїни й бачу — там розбили табір. Дивне місце для табору, як на мене... Я б придивився ближче, але один із тих скажених велетенських стерв'ятників мене прогнав.",
        ["npcs"] = { [1] = 7564 },
        ["roles"] = { ["greeting"] = true },
    },
    [4181059103] = {
        ["english"] = { [1] = "When you have not a healer to tend to your wounds, the knowledge of First Aid can be a lifesaver.  I would consult Dannelor over at the Craftsmen's Terrace for instruction on this skill." },
        ["text"] = "Коли поруч немає цілителя, який подбає про рани, знання першої допомоги може врятувати життя. Раджу звернутися до Даннелора на Терасі Ремісників, щоб навчитися цього вміння.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [860403150] = {
        ["english"] = { [1] = "What is a \"subterranean being matrix\"?" },
        ["text"] = "Що таке «матриця підземної істоти»?",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [2124806355] = {
        ["english"] = { [1] = "What are you doing here?  Shouldn't you be working on the energy pipeline?$B$BWe've more than doubled the amount of energy we're sending to Tempest Keep and can't afford anyone loafing.  We don't want another Ultris to happen here." },
        ["text"] = "Що ти тут робиш? Хіба не треба працювати над енергопроводом?$B$BМи більш ніж удвічі збільшили кількість енергії, яку надсилаємо до Фортеці Бур, і не можемо дозволити нікому байдикувати. Не хочемо повторення того, що сталося з Ультрісом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [110543129] = {
        ["english"] = { [1] = "Welcome aboard $c.  Take a load off and enjoy the trip.  Aboard \"The Purple Princess\" we want you to relax.  We have vending machines down below if there's anything you might need while aboard." },
        ["text"] = "Ласкаво просимо на борт, $c. Влаштовуйся зручніше й насолоджуйся подорожжю. На «Пурпуровій Принцесі» ми хочемо, щоб ти відпочивав. Унизу є торгові автомати, якщо під час подорожі тобі щось знадобиться.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2899282050] = {
        ["english"] = { [1] = "We must make sure not to lose any more souls to the seas." },
        ["text"] = "Ми мусимо подбати, щоб море більше не забрало жодної душі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2549176773] = {
        ["english"] = { [1] = "What are you doing all the way back here? You need to get back to Stratholme immediately! Shall I teleport you to Stratholme?" },
        ["text"] = "Що ти робиш аж тут позаду? Негайно повертайся до Стратгольма! Телепортувати тебе туди?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2749839143] = {
        ["english"] = { [1] = "Welcome to the Allerian Stronghold, $N." },
        ["text"] = "Ласкаво просимо до Бастіону Аллерії, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [76024044] = {
        ["english"] = { [1] = "Well met, $c. Even now, the Horde attacks Warsong Gulch. Will you fight alongside the Alliance there?" },
        ["text"] = "Вітаю, $c. Навіть зараз Орда атакує Ущелину Пісні Війни. Битимешся там пліч-о-пліч з Альянсом?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [808684369] = {
        ["english"] = { [1] = "Where is Elder Runetotem?" },
        ["text"] = "Де старійшина Рунічний Тотем?",
        ["npcs"] = { [1] = 15579, [2] = 15582, [3] = 15588, [4] = 15597 },
        ["roles"] = { ["reply"] = true },
    },
    [281566315] = {
        ["english"] = { [1] = "Welcome to our tent. May I assist you?" },
        ["text"] = "Ласкаво просимо до нашого намету. Чим можу допомогти?",
        ["npcs"] = { [1] = 3704 },
        ["roles"] = { ["greeting"] = true },
    },
    [2567298876] = {
        ["english"] = { [1] = "Welcome to Dolanaar, $c. Let me know if you need any recipes or basic cooking ingredients." },
        ["text"] = "Ласкаво просимо до Доланаара, $c. Якщо потрібні рецепти чи базові кулінарні інгредієнти — звертайся.",
        ["npcs"] = { [1] = 4265 },
        ["roles"] = { ["greeting"] = true },
    },
    [3369634951] = {
        ["english"] = { [1] = "Well met, $c. I hope you are here to inquire on the Ahn'Qiraj war effort. We are going to need a great deal of assistance.$B$BThe war effort is a united effort between the Alliance and Horde to prepare for the upcoming war against the Silithid and their masters in Ahn'Qiraj. In the Military Ward of Ironforge, we are collecting all manner of goods to create our war materiel from, and these gathering tasks are what we need your help with.$B$BCan I convince you to speak with our commander about pitching in?" },
        ["text"] = "Вітаю, $c. Сподіваюся, ти прийшов дізнатися про військові приготування до Ан'Кіражу. Нам знадобиться величезна допомога.$B$BЦі приготування — спільні зусилля Альянсу й Орди перед майбутньою війною проти силітидів і їхніх господарів у Ан'Кіражі. У Військовому кварталі Стальгорна ми збираємо всілякі матеріали для військових припасів, і саме з цим потрібна твоя допомога.$B$BПереконати тебе поговорити з нашим командиром і долучитися?",
        ["npcs"] = { [1] = 15707, [2] = 15708, [3] = 15709 },
        ["roles"] = { ["greeting"] = true },
    },
    [1033709591] = {
        ["english"] = { [1] = "When Hallow's End is over we'll smash all these pumpkins. That'll be the greatest day I've ever known!" },
        ["text"] = "Коли Ніч усіх святих закінчиться, ми розтрощимо всі ці гарбузи. Це буде найкращий день у моєму житті!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1476031263] = {
        ["english"] = { [1] = "What did you say earlier?" },
        ["text"] = "Що ти казав раніше?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [4266408007] = {
        ["english"] = { [1] = "Try not to draw too much attention, I'm waiting for the King to grant me audience.  Not that I mind waiting, I feel pretty safe around all these burly guards." },
        ["text"] = "Намагайся не привертати зайвої уваги. Я чекаю, поки Король дозволить мені аудієнцію. Хоча чекати не так уже й погано — серед усіх цих кремезних вартових я почуваюся цілком безпечно.",
        ["npcs"] = { [1] = 16013 },
        ["roles"] = { ["greeting"] = true },
    },
    [2798172658] = {
        ["english"] = { [1] = "We've been so wrapped up in this war, some of us forgot to make time for love." },
        ["text"] = "Ми так загрузли в цій війні, що дехто з нас забув залишати час для кохання.",
        ["npcs"] = { [1] = 68, [2] = 277, [3] = 279, [4] = 297, [5] = 338, [6] = 340, [7] = 482, [8] = 483, [9] = 1141, [10] = 1212, [11] = 1257, [12] = 1275, [13] = 1285, [14] = 1286, [15] = 1287, [16] = 1289, [17] = 1291, [18] = 1294, [19] = 1295, [20] = 1297, [21] = 1298, [22] = 1299, [23] = 1301, [24] = 1304, [25] = 1307, [26] = 1308, [27] = 1309, [28] = 1310, [29] = 1312, [30] = 1313, [31] = 1314, [32] = 1315, [33] = 1316, [34] = 1318, [35] = 1319, [36] = 1320, [37] = 1321, [38] = 1323, [39] = 1324, [40] = 1328, [41] = 1333, [42] = 1339, [43] = 1341, [44] = 1347, [45] = 1348, [46] = 1349, [47] = 1350, [48] = 1351, [49] = 1395, [50] = 1402, [51] = 1405, [52] = 1413, [53] = 1414, [54] = 1415, [55] = 1427, [56] = 1428, [57] = 1431, [58] = 1440, [59] = 1444, [60] = 1477, [61] = 1478, [62] = 1646, [63] = 1721, [64] = 1976, [65] = 2330, [66] = 2504, [67] = 2795, [68] = 2808, [69] = 3518, [70] = 3626, [71] = 3627, [72] = 3629, [73] = 4078, [74] = 4959, [75] = 4960, [76] = 4981, [77] = 4984, [78] = 5081, [79] = 5386, [80] = 5483, [81] = 5494, [82] = 5565, [83] = 6171, [84] = 6173, [85] = 6174, [86] = 6175, [87] = 6272, [88] = 6740, [89] = 7295, [90] = 7798, [91] = 7917, [92] = 8931, [93] = 11827, [94] = 11828, [95] = 12336, [96] = 12805, [97] = 14423, [98] = 14438, [99] = 14439, [100] = 14497, [101] = 16002, [102] = 16105, [103] = 16106 },
        ["roles"] = { ["greeting"] = true },
    },
    [408979863] = {
        ["english"] = { [1] = "Welcome, $c. Have you come to honor this flame?$b$bRemember: Our festival fires burn in every land with an Alliance settlement. Make time to honor each of them, if you can.$b$bThe Horde, too, burns fires of their own. You would do well to desecrate such unworthy efforts when you see them." },
        ["text"] = "Ласкаво просимо, $c. Прийшов вшанувати це полум'я?$b$bПам'ятай: наші святкові вогні горять у кожній землі, де є поселення Альянсу. Якщо зможеш, знайди час ушанувати кожне.$b$bОрда теж палить свої вогні. Побачиш таке негідне полум'я — добре було б його осквернити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2628137959] = {
        ["english"] = { [1] = "We've sworn to do our very best to protect the passengers of The Bravery. The sea lane between Auberdine to Stormwind Harbor must remain safe." },
        ["text"] = "Ми присягнули зробити все можливе, щоб захистити пасажирів «Відваги». Морський шлях між Аубердіном і Штормовійською гаванню має залишатися безпечним.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3276255518] = {
        ["english"] = { [1] = "We've gotta find out what the Qiraji are feeding those monsters! Look at the size of 'em!" },
        ["text"] = "Треба з'ясувати, чим кіражі годують тих чудовиськ! Ти тільки поглянь на їхні розміри!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3982671801] = {
        ["english"] = { [1] = "What may I do for you, $GSir:Dame;?" },
        ["text"] = "Чим можу прислужитися, $GПане:Пані;?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4145022581] = {
        ["english"] = { [1] = "We will fight when you are ready, $N." },
        ["text"] = "Ми битимемося, коли ти будеш готовий, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1717215797] = {
        ["english"] = { [1] = "Ugh, I should never have volunteered to be a specialist. They always ask us to do the impossible!" },
        ["text"] = "Уф, не слід було зголошуватися в спеціалісти. Нас завжди просять зробити неможливе!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1662324687] = {
        ["english"] = { [1] = "What is it, $c?" },
        ["text"] = "Що таке, $c?",
        ["npcs"] = { [1] = 8582 },
        ["roles"] = { ["greeting"] = true },
    },
    [3049473675] = {
        ["english"] = { [1] = "What a story! So she went into Hive'Regal and that was the last you saw of her?" },
        ["text"] = "Оце історія! То вона пішла до Вулика Реґал, і відтоді ти її не бачив?",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["reply"] = true },
    },
    [4143680753] = {
        ["english"] = { [1] = "When I was last in the halls, Talon King Ikiss carried Terokk's Quill with him, as a sign of his authority.$B$BMy brother, Darkweaver Syth, wore Terokk's Mask during our rituals.$B$BAs for the Saga of Terokk, there's no way of knowing exactly where it is, but they usually kept it at the center of one of their rune circles in the great vaulted halls." },
        ["text"] = "Коли я востаннє був у залах, Король Кігтів Ікісс носив із собою Перо Терокка як знак своєї влади.$B$BМій брат, Темноткач Сит, носив Маску Терокка під час наших ритуалів.$B$BЩодо Саги про Терокка — неможливо знати, де вона точно, але зазвичай її тримали в центрі одного з рунічних кіл у великих склепінчастих залах.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2413128513] = {
        ["english"] = { [1] = "Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.$B$BWe are the preservers of the balance, now and forever, as Malfurion lies in the Dreaming.  Never forget this." },
        ["text"] = "Ласкаво просимо, $g брате : сестро;. Якщо ти прийшов тренуватися, я із задоволенням тебе навчу.$B$BМи — хранителі рівноваги нині й навіки, поки Малфуріон перебуває у Сні. Ніколи цього не забувай.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2525787841] = {
        ["english"] = { [1] = "We took her to the Commander with hopes that the druids of the Circle could fix her up. Sure enough, they were able to wake her up. We figured our business with the Circle was done and we could get back to work.$B$BA few weeks passed and everything was going fine. Brann was still around back then so we had a bit of order in our work structure. Then one day, out of the blue, she appeared back at our camp.\010" },
        ["text"] = "Ми відвели її до Командира, сподіваючись, що друїди Кола зможуть їй допомогти. І справді — їм вдалося її розбудити. Ми вирішили, що наші справи з Колом завершені й можна повертатися до роботи.$B$BМинуло кілька тижнів, і все йшло добре. Бранн тоді ще був із нами, тож у роботі панував бодай якийсь порядок. А потім одного дня вона раптом знову з'явилася в нашому таборі.\010",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["greeting"] = true },
    },
    [2547813032] = {
        ["english"] = { [1] = "Train hard, train every day. And when you have perfected your skills, return to me." },
        ["text"] = "Тренуйся завзято, тренуйся щодня. А коли доведеш свою майстерність до досконалості — повернися до мене.",
        ["npcs"] = { [1] = 11074 },
        ["roles"] = { ["greeting"] = true },
    },
    [1997659367] = {
        ["english"] = { [1] = "Well, you didn't come all this way out here to jaw over a cup of tea. Let's see how you might be able to help get us out of this situation." },
        ["text"] = "Ти ж не заради балачок за чашкою чаю пройшов сюди весь цей шлях. Подивімося, як ти можеш допомогти нам вибратися з цієї халепи.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2669215490] = {
        ["english"] = { [1] = "Well, you can find Theridan or Maldryn by the moonwell in the Park.  Just head to the western area of Stormwind, north of the Mage District, but west of the Cathedral Square." },
        ["text"] = "Терідана або Малдрина знайдеш біля місячного колодязя в Парку. Просто йди до західної частини Штормовію, на північ від Кварталу Магів, але західніше Соборної площі.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1847148059] = {
        ["english"] = { [1] = "We require da help of allies on da islands.$B$BZen'tabra has been watching over da animals of de Islands for some time now.  We'd need her help and da help of da animal creatures.$B$BBwonsamdi is a powerful loa dat controls de spirits of de dead on da islands.  His blessing is crucial for our attack.$B$BOnce our allies have joined us, Zalazane and his army of mind-controlled trolls will have no chance!  Then, da Echo Isles will be de Darkspears!" },
        ["text"] = "Нам треба допомога союзників на островах.$B$BЗен'табра вже давно наглядає за тваринами островів. Нам знадобиться її допомога та допомога звірів.$B$BБвонсамді — могутній лоа, що керує духами мертвих на островах. Його благословення життєво важливе для нашого нападу.$B$BКоли союзники приєднаються до нас, у Залазейна та його армії підконтрольних розуму тролів не буде жодного шансу! Тоді Острови Відлуння знову стануть Темносписовими!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [182484818] = {
        ["english"] = { [1] = "Well, well, moving up in the world are we? You're looking for the Champions' Hall, and you'll find it on the southeast end of Old Town. If you're an officer you can enter the hall, otherwise you can still speak to Officer Areyn standing outside. Good luck!" },
        ["text"] = "Ого, піднімаємося в житті, еге? Ти шукаєш Залу Чемпіонів — вона в південно-східній частині Старого міста. Якщо ти офіцер, зможеш увійти всередину, а якщо ні — усе одно можеш поговорити з офіцером Арейн, яка стоїть зовні. Удачі!",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2282440699] = {
        ["english"] = { [1] = "Us want lots of pets.  Anya Maulray help you take care of them.  You find her at inn, upper ring of Trade Quarter." },
        ["text"] = "Ми хочемо багато вихованців. Аня Молрей допоможе тобі про них дбати. Знайдеш її в таверні на верхньому кільці Торгового кварталу.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [1994801744] = {
        ["english"] = { [1] = "What can I say, $c? You're a true $g hero : heroine;! Not only have you personally saved many of my rangers, but you've dealt a decisive blow against the Shadowpine trolls. Are you sure that you don't want to stay here and be one of my Farstriders?$B$BFare well, $N." },
        ["text"] = "Що я можу сказати, $c? Ти справжній $g герой : героїня;! Ти не лише особисто врятував багатьох моїх далекоходців, а й завдав вирішального удару тролям Тіньової Сосни. Точно не хочеш залишитися тут і стати одним із моїх далекоходців?$B$BЩасливої дороги, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1420294152] = {
        ["english"] = { [1] = "Welcome to my forge, Blacksmith. Let me share with you a little secret. No one, no one in the world can you trust. Not men, not women, not beasts ... this you can trust, Steel." },
        ["text"] = "Ласкаво просимо до моєї кузні, коваль. Поділюся з тобою маленькою таємницею. Нікому, нікому у світі не можна довіряти. Ні чоловікам, ні жінкам, ні звірам... а ось цьому можна довіряти — сталі.",
        ["npcs"] = { [1] = 3355 },
        ["roles"] = { ["greeting"] = true },
    },
    [3293753139] = {
        ["english"] = { [1] = "Well well, not too bad. Maybe I CAN show you a few things..." },
        ["text"] = "Ну-ну, не так уже й погано. Може, я таки зможу показати тобі кілька речей...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1824275831] = {
        ["english"] = { [1] = "What?!  What did ye say?!  How dare ye!  Me beer can stand up to any of that rot they serve at Brewfest!$B$BYou'll pay for this insult, $c!" },
        ["text"] = "Що?! Що ти сказав?! Як ти смієш! Моє пиво не гірше за будь-яке те помийво, що подають на Хмільному фестивалі!$B$BТи заплатиш за цю образу, $c!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1512063502] = {
        ["english"] = { [1] = "Well this is troublesome! How am I supposed to collect the ore samples for the magisters if the mines have been overrun with gnoll vermin?" },
        ["text"] = "Оце халепа! Як мені збирати зразки руди для магістрів, якщо копальні кишать паразитами-ґнолами?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4079586748] = {
        ["english"] = { [1] = "Truth be told, I never liked that gnome..." },
        ["text"] = "Правду кажучи, той гном мені ніколи не подобався...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3318388817] = {
        ["english"] = { [1] = "Where is Elder Ironband?" },
        ["text"] = "Де старійшина Залізна Смуга?",
        ["npcs"] = { [1] = 15549, [2] = 15558, [3] = 15560, [4] = 15564, [5] = 15569, [6] = 15579, [7] = 15580, [8] = 15871 },
        ["roles"] = { ["reply"] = true },
    },
    [278643549] = {
        ["english"] = { [1] = "Time is of the essence here, $n. Are you prepared to be tested?" },
        ["text"] = "Часу обмаль, $n. Готовий пройти випробування?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [737508154] = {
        ["english"] = { [1] = "We, his sworn servants, do his bidding and enforce his iron-rule. Cut off from the energies of his fiery realm, Ragnaros is but a shadow of his true self. However, he has more than enough strength to be your end.      \010" },
        ["text"] = "Ми, його присяжні слуги, виконуємо його волю й підтримуємо його залізну владу. Відрізаний від енергії свого вогняного царства, Раґнарос — лише тінь своєї істинної могутності. Та навіть цього більш ніж достатньо, щоб покласти тобі край.      ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [874173918] = {
        ["english"] = { [1] = "Welcome to Stormwind. Took a long time to rebuild her but it was well worth it. So are you visiting, or are you here on business?" },
        ["text"] = "Ласкаво просимо до Штормовію. Довго ми його відбудовували, але воно того варте. Ти просто в гості чи у справах?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1368285864] = {
        ["english"] = { [1] = "We plaguebringers tend to be slightly more practical than the average apothecary.  After all, we deal with the logistics of deploying the plague.$B$BThat doesn't mean our theoretical background isn't rock solid.  We just prefer... hands on tasks." },
        ["text"] = "Ми, чумоносці, зазвичай трохи практичніші за пересічних аптекарів. Зрештою, ми займаємося логістикою розгортання чуми.$B$BЦе не означає, що наша теоретична підготовка слабка. Ми просто віддаємо перевагу... практичним завданням.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3244128533] = {
        ["english"] = { [1] = "Well then, I spose I be owin' ya my thanks, $r.$b$bTruth is, I thought I'd swallowed me last tankard 'til ye showed up." },
        ["text"] = "Ну що ж, гадаю, я тобі винен подяку, $r.$b$bПравду кажучи, я думав, що вже випив свій останній кухоль, аж поки ти не з'явився.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [857721911] = {
        ["english"] = { [1] = "Warsong Gulch you say?  Well then, you'll be wanting to speak with fair Lylandris over in the Hall of Arms.", [2] = "Warsong Gulch you say? Well then, you'll be wanting to speak with fair Lylandris over in the Hall of Arms." },
        ["text"] = "Ущелина Пісні Війни, кажеш? Тоді тобі треба поговорити з прекрасною Ліландріс у Залі Зброї.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1064110116] = {
        ["english"] = { [1] = "What can you tell me about the bear - Ursangous?", [2] = "What can you tell me about the bear - Ursangous?\010" },
        ["text"] = "Що можеш розповісти про ведмедя Урсанґуса?",
        ["npcs"] = { [1] = 12696 },
        ["roles"] = { ["reply"] = true },
    },
    [353768584] = {
        ["english"] = { [1] = "What do you need, $c?" },
        ["text"] = "Що тобі потрібно, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1407927119] = {
        ["english"] = { [1] = "Where is Elder Skyseer?" },
        ["text"] = "Де старійшина Небопровидець?",
        ["npcs"] = { [1] = 15573, [2] = 15578, [3] = 15586, [4] = 15604 },
        ["roles"] = { ["reply"] = true },
    },
    [3261743431] = {
        ["english"] = { [1] = "Well met, fellow Mohawk $GBrother:Sister;." },
        ["text"] = "Вітаю, побратиме-могавку, $GБрате:Сестро;.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2400760897] = {
        ["english"] = { [1] = "We must maintain a state of vigilance, $c! Between Dar'Khan the Betrayer and his Scourge, and the Shadowpine trolls backed by the might of Zul'Aman, we're barely keeping our heads above water here. We really shouldn't have to be dividing our attentions!$B$BI hope you're here to help." },
        ["text"] = "Ми маємо постійно бути напоготові, $c! Між Дар'Ханом Зрадником і його Скарою та тролями Тіньової Сосни, яких підтримує міць Зул'Амана, ми тут ледве тримаємося на плаву. Нам справді не варто ще й розпорошувати увагу!$B$BСподіваюся, ти прийшов допомогти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3108284066] = {
        ["english"] = { [1] = "Use engineering to access hidden schematics!" },
        ["text"] = "Скористайся інженерією, щоб отримати доступ до прихованих схем!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3625867848] = {
        ["english"] = { [1] = "What can I be helping you with?" },
        ["text"] = "Чим я можу тобі допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [426785215] = {
        ["english"] = { [1] = "What could you possibly need a bank for?  Very well, you'll need to go through the Ruins of Lordaeron to the south of Brill.  In the back are a set of elevators leading down into the Undercity.  When you get there stop any of those lumbering Abominations they like to call an Undercity Guardian and ask it for better directions." },
        ["text"] = "Навіщо тобі взагалі банк? Гаразд, треба пройти через Руїни Лордерону на південь від Брілля. У задній частині є підіймачі до Підмістя. Коли дістанешся туди, зупини одну з тих незграбних потвор, яких вони люблять називати Вартовими Підмістя, і попроси точніший шлях.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [4173387963] = {
        ["english"] = { [1] = "Well met, $c.$B$BI train Aspirants in the art of mounted close combat." },
        ["text"] = "Вітаю, $c.$B$BЯ навчаю претендентів мистецтва ближнього бою верхи.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2515196751] = {
        ["english"] = { [1] = "Welcome back, $N.  You've proven a worthy ally against Ragnaros and your presence is always welcome among us." },
        ["text"] = "З поверненням, $N. Ти довів, що є гідним союзником у боротьбі проти Раґнароса, і тобі тут завжди раді.",
        ["npcs"] = { [1] = 13278 },
        ["roles"] = { ["greeting"] = true },
    },
    [628036939] = {
        ["english"] = { [1] = "We, the Zandalarian trolls, traveled here from distant islands, for we cannot ignore the threat that now faces our world.$B$BThe leader of our expedition, Molthor, brought us to the Yojamba Isle, along the northern coasts of Stranglethorn, and even now recruits brave heroes to venture into the ancient troll city... Zul'Gurub." },
        ["text"] = "Ми, зандаларські тролі, прибули сюди з далеких островів, бо не можемо ігнорувати загрозу, що нині постала перед нашим світом.$B$BОчільник нашої експедиції, Молтор, привів нас на острів Йоджамба біля північного узбережжя Тернистої долини й просто зараз набирає хоробрих героїв, готових вирушити до стародавнього міста тролів... Зул'Ґуруба.",
        ["npcs"] = { [1] = 15076 },
        ["roles"] = { ["greeting"] = true },
    },
    [3626354801] = {
        ["english"] = { [1] = "Where could she possibly be? I sent my apprentice, Shatharia, to the Underlight Mines to the west quite some time ago. We need those ore samples back, and fast or our experiment is going to fail!" },
        ["text"] = "Де ж вона може бути? Я вже досить давно відправив свою ученицю Шатарію до копалень Підсвіття на захід. Нам терміново потрібні ті зразки руди, інакше експеримент провалиться!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1286327211] = {
        ["english"] = { [1] = "Where is Elder Bladesing?" },
        ["text"] = "Де старійшина Клинкоспів?",
        ["npcs"] = { [1] = 15570, [2] = 15583 },
        ["roles"] = { ["reply"] = true },
    },
    [3984203272] = {
        ["english"] = { [1] = "We must focus if we are to spawn our dragonflight!" },
        ["text"] = "Ми повинні зосередитися, якщо хочемо породити нашу драконячу зграю!",
        ["npcs"] = { [1] = 707, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096 },
        ["roles"] = { ["greeting"] = true },
    },
    [974319154] = {
        ["english"] = { [1] = "Well met, $c. You may speak to me unless you have direct business with my mistress Magatha.$B$BI deal with most of her tasks for her so she can concentrate on more important matters. Perhaps there are some things we could discuss before you seek audience with her?" },
        ["text"] = "Вітаю, $c. Можеш говорити зі мною, якщо в тебе немає безпосередньої справи до моєї господині Маґати.$B$BЯ виконую більшість її доручень, щоб вона могла зосередитися на важливіших справах. Можливо, нам є що обговорити, перш ніж ти попросиш у неї аудієнції?",
        ["npcs"] = { [1] = 11833 },
        ["roles"] = { ["greeting"] = true },
    },
    [915178722] = {
        ["english"] = { [1] = "Tucked away in the Mage Quarter, there is a little shop called Alchemy Needs.  You're bound to see all sort of strange shops on your way through the Mage Quarter, but if you stick to the outer rim you'll be sure to find it." },
        ["text"] = "У Кварталі Магів заховалася невеличка крамниця під назвою «Алхімічні потреби». Дорогою через Квартал Магів побачиш чимало дивних крамниць, але якщо триматимешся зовнішнього кільця, точно її знайдеш.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3828775816] = {
        ["english"] = { [1] = "Warrior trainers fight good.  You find them in War Quarter on outer ring of Undercity." },
        ["text"] = "Наставники воїнів добре б'ються. Знайдеш їх у Військовому кварталі на зовнішньому кільці Підмістя.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2358018947] = {
        ["english"] = { [1] = "What is it Tarsis? I don't know what to do!" },
        ["text"] = "Що таке, Тарсісе? Я не знаю, що робити!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3575468116] = {
        ["english"] = { [1] = "Well I hope you improve quickly!" },
        ["text"] = "Що ж, сподіваюся, ти швидко покращиш навички!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2336505259] = {
        ["english"] = { [1] = "What's an \"Ologist?\" A better question might be what isn't an \"Ologist.\" It means I study everything! In fact, I'm so well versed in \"everything\" that I'm guaranteed to be the most intelligent ethereal you'll ever meet - or your money back.$B$BApologies. That's the dealer in me talking..." },
        ["text"] = "Що таке «-олог»? Краще запитати: чим «-олог» НЕ займається. Це означає, що я вивчаю все! Ба більше, я настільки добре знаюся на «всьому», що гарантовано є найрозумнішим ефірником, якого ти коли-небудь зустрінеш, — або повернемо гроші.$B$BПерепрошую. Це в мені торговець говорить...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3204877787] = {
        ["english"] = { [1] = "Welcome to The Bravery, $gsir:madame;. Now if you'll excuse me..." },
        ["text"] = "Ласкаво просимо на «Відвагу», $gпане:пані;. А тепер, якщо дозволите...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [245235465] = {
        ["english"] = { [1] = "Um, you kill king, yeah?  That means you take his place.  That make you da new boss!  Hail to da king!" },
        ["text"] = "Ем, ти короля вбив, так? Значить, ти зайняв його місце. Тепер ти новий бос! Хай живе король!",
        ["npcs"] = { [1] = 14353 },
        ["roles"] = { ["greeting"] = true },
    },
    [3916490911] = {
        ["english"] = { [1] = "We live and die, and the land remains, eternal, unmoved by our passage. Thus, land cannot belong to us, $N. Instead, we belong to it. Therefore we protect the land, for without it we cannot hope to survive." },
        ["text"] = "Ми живемо й помираємо, а земля залишається — вічна й незворушна від нашого проходження. Тож земля не може належати нам, $N. Це ми належимо їй. Саме тому ми захищаємо землю, бо без неї не зможемо вижити.",
        ["npcs"] = { [1] = 3069 },
        ["roles"] = { ["greeting"] = true },
    },
    [4205807588] = {
        ["english"] = { [1] = "Well met, $c.  You want some advice?  Befriend a mage!  We have a trick or two up our sleeves, we do..." },
        ["text"] = "Вітаю, $c. Хочеш пораду? Подружися з магом! У нас завжди є кілька козирів у рукаві...",
        ["npcs"] = { [1] = 944, [2] = 1228, [3] = 5144, [4] = 5145, [5] = 5146, [6] = 7312 },
        ["roles"] = { ["greeting"] = true },
    },
    [2773291482] = {
        ["english"] = { [1] = "What about the Winterfall furbolg?" },
        ["text"] = "А що щодо фурболґів Зимопаду?",
        ["npcs"] = { [1] = 11556 },
        ["roles"] = { ["reply"] = true },
    },
    [3775347604] = {
        ["english"] = { [1] = "We are trying to bring Agamath, the First Gate down. Please, $c, go to the Isle of Quel'Danas and help in any way that you can!" },
        ["text"] = "Ми намагаємося зруйнувати Аґамат, Першу Браму. Прошу, $c, вирушай на острів Кель'Данас і допоможи чим зможеш!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [658128880] = {
        ["english"] = { [1] = "Well done! You have that spark in your eye, I know it well, it's the same spark I had when I was but a pup! Now, let's see if I can't teach you something." },
        ["text"] = "Молодець! У твоїх очах є іскра — я її добре знаю, така сама була в мене, коли я був іще щеням! Ну, подивімося, чого я зможу тебе навчити.",
        ["npcs"] = { [1] = 3345 },
        ["roles"] = { ["greeting"] = true },
    },
    [1839838767] = {
        ["english"] = { [1] = "Welcome. May I offer you rest or sustenance?" },
        ["text"] = "Ласкаво просимо. Запропонувати тобі відпочинок чи їжу?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3830123853] = {
        ["english"] = { [1] = "Well $glad : lass;, ye can find Shelby Stoneflint right outside the Thunderbrew Distillery in Kharanos.  She'll take good care of any pets ye might have." },
        ["text"] = "Ну, $gхлопче : дівчино;, Шелбі Кам'яний Кремінь знайдеш просто біля броварні Громоварів у Караносі. Вона добре подбає про будь-яких твоїх вихованців.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [3248925107] = {
        ["english"] = { [1] = "To many of my people I am known as a traitor... as Illidan's lapdog.  It is best that they continue to think that for now." },
        ["text"] = "Для багатьох із мого народу я — зрадник... песик Іллідана. Поки що краще, щоб вони й надалі так думали.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [63920244] = {
        ["english"] = { [1] = "We work to preserve the balance as Cenarius teaches, $c.  His is the light of a beacon that shows the way for us, and we must do everything in our power to preserve that light." },
        ["text"] = "Ми працюємо, щоб зберігати рівновагу, як учить Кенарій, $c. Його світло — мов маяк, що вказує нам шлях, і ми повинні зробити все можливе, щоб це світло не згасло.",
        ["npcs"] = { [1] = 3064 },
        ["roles"] = { ["greeting"] = true },
    },
    [2815959796] = {
        ["english"] = { [1] = "Well. Another $c, come to learn the ways of the Shield-Breaker...?" },
        ["text"] = "Що ж. Ще один $c, який прийшов опановувати шлях Щитолома...?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2211876251] = {
        ["english"] = { [1] = "Us know her good.  She Mary Edras at inner ring of Rogues' Quarter." },
        ["text"] = "Ми її добре знаємо. Це Мері Едрас, на внутрішньому кільці Кварталу Розбійників.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [826068608] = {
        ["english"] = { [1] = "Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.$B$BWe are the preservers of the balance, now and forever, as Cenarius has taught us.  Never forget this." },
        ["text"] = "Ласкаво просимо, $g брате : сестро;. Якщо ти прийшов тренуватися, я із задоволенням тебе навчу.$B$BМи — хранителі рівноваги нині й навіки, як учив нас Кенарій. Ніколи цього не забувай.",
        ["npcs"] = { [1] = 3064 },
        ["roles"] = { ["greeting"] = true },
    },
    [274509700] = {
        ["english"] = { [1] = "Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.$B$BThere will be a time soon where the call of the Emerald Dream will take hold in you.  You will hibernate for many years and walk amongst the purest of forms.  It is there and then that your ultimate training will take place." },
        ["text"] = "Ласкаво просимо, $g брате : сестро;. Якщо ти прийшов тренуватися, я із задоволенням тебе навчу.$B$BНезабаром настане час, коли поклик Смарагдового Сну заволодіє тобою. Ти впадеш у сплячку на довгі роки й ходитимеш серед найчистіших форм. Саме там і тоді відбудеться твоє найвище навчання.",
        ["npcs"] = { [1] = 3597, [2] = 5504, [3] = 5505, [4] = 5506, [5] = 9465, [6] = 12042 },
        ["roles"] = { ["greeting"] = true },
    },
    [661182164] = {
        ["english"] = { [1] = "What, you don't have a token to give me? Don't you love me?" },
        ["text"] = "Що, в тебе немає знака для мене? Ти мене не любиш?",
