510, [294] = 5512, [295] = 5514, [296] = 5519, [297] = 5543, [298] = 5565, [299] = 5570, [300] = 5595, [301] = 5603, [302] = 5606, [303] = 5609, [304] = 5610, [305] = 5611, [306] = 5613, [307] = 5614, [308] = 5624, [309] = 5637, [310] = 5640, [311] = 5651, [312] = 5655, [313] = 5656, [314] = 5657, [315] = 5658, [316] = 5659, [317] = 5660, [318] = 5668, [319] = 5669, [320] = 5670, [321] = 5693, [322] = 5701, [323] = 5703, [324] = 5704, [325] = 5705, [326] = 5706, [327] = 5707, [328] = 5731, [329] = 5732, [330] = 5733, [331] = 5744, [332] = 5747, [333] = 5754, [334] = 5770, [335] = 5782, [336] = 5816, [337] = 5817, [338] = 5819, [339] = 5820, [340] = 5821, [341] = 5892, [342] = 5906, [343] = 5909, [344] = 6034, [345] = 6114, [346] = 6120, [347] = 6142, [348] = 6169, [349] = 6171, [350] = 6173, [351] = 6174, [352] = 6175, [353] = 6178, [354] = 6179, [355] = 6272, [356] = 6293, [357] = 6294, [358] = 6410, [359] = 6411, [360] = 6446, [361] = 6467, [362] = 6522, [363] = 6569, [364] = 6579, [365] = 6740, [366] = 6826, [367] = 6986, [368] = 6987, [369] = 7292, [370] = 7294, [371] = 7295, [372] = 7297, [373] = 7298, [374] = 7313, [375] = 7316, [376] = 7740, [377] = 7790, [378] = 7792, [379] = 7793, [380] = 7798, [381] = 7825, [382] = 7917, [383] = 7936, [384] = 7950, [385] = 7976, [386] = 7978, [387] = 8026, [388] = 8256, [389] = 8358, [390] = 8360, [391] = 8361, [392] = 8362, [393] = 8363, [394] = 8364, [395] = 8390, [396] = 8398, [397] = 8403, [398] = 8404, [399] = 8507, [400] = 8517, [401] = 8665, [402] = 8681, [403] = 8931, [404] = 9099, [405] = 9317, [406] = 10136, [407] = 10455, [408] = 10456, [409] = 11176, [410] = 11700, [411] = 11709, [412] = 11750, [413] = 11827, [414] = 11828, [415] = 12336, [416] = 12799, [417] = 12805, [418] = 14182, [419] = 14363, [420] = 14365, [421] = 14367, [422] = 14375, [423] = 14376, [424] = 14377, [425] = 14378, [426] = 14379, [427] = 14380, [428] = 14402, [429] = 14403, [430] = 14404, [431] = 14423, [432] = 14438, [433] = 14439, [434] = 14440, [435] = 14441, [436] = 14442, [437] = 14497, [438] = 16002, [439] = 16004, [440] = 16009, [441] = 16105, [442] = 16106, [443] = 16108 },
        ["roles"] = { ["greeting"] = true },
    },
    [1396600332] = {
        ["english"] = { [1] = "Welcome, champion! Have you gathered your forces in preparation for the challenges of the Trial of the Grand Crusader? Only the most powerful and accomplished of combatants are able to participate in these trials. To participate in these trials, you must have completed the normal Trial of the Crusader." },
        ["text"] = "Ласкаво просимо, чемпіоне! Ти вже зібрав свої сили для випробувань Великого хрестоносця? У цих випробуваннях можуть брати участь лише наймогутніші й найдосвідченіші бійці. Щоб долучитися, потрібно завершити звичайне Випробування хрестоносця.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1964679559] = {
        ["english"] = { [1] = "We've recently heard word of a creature of immense power being summoned near the Vector Coil. Fear not, should anything threaten the town, we will give our lives to protect it." },
        ["text"] = "Нещодавно ми почули, що біля Векторної Котушки викликали створіння неймовірної сили. Не бійся: якщо щось загрожуватиме місту, ми віддамо життя за його захист.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [162957638] = {
        ["english"] = { [1] = "While there's no Engineering Trainer in Brill, there is one down in the Undercity.  To get there head to the back of the Ruins of Lordaeron to the south of town and take the elevator down.  Once you get there ask an Undercity Guardian for more specific directions." },
        ["text"] = "У Бріллі немає наставника інженерії, але є в Підмісті. Щоб дістатися туди, йди до задньої частини Руїн Лордерону на південь від міста й спускайся ліфтом. Коли будеш унизу, запитай точніший шлях у Вартового Підмістя.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [1545801981] = {
        ["english"] = { [1] = "Where is Elder Rumblerock?" },
        ["text"] = "Де старійшина Гуркітливий Камінь?",
        ["npcs"] = { [1] = 15562, [2] = 15565, [3] = 15576, [4] = 15585 },
        ["roles"] = { ["reply"] = true },
    },
    [2261663596] = {
        ["english"] = { [1] = "Welcome to the Evergrove, $c. Timeon and I have been studying the arakkoa of Blade's Edge for some time now, and we've found some alarming differences between them and their cousins in Terokkar." },
        ["text"] = "Ласкаво просимо до Вічного гаю, $c. Ми з Таймеоном уже певний час вивчаємо араккоа Лезокраїх гір і виявили тривожні відмінності між ними та їхніми родичами з Тероккара.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [98760756] = {
        ["english"] = { [1] = "Welcome! Have you come to join us for a Pilgrim's Bounty feast? Please, have a seat at a Bountiful Table.$B$BTry everything! I'm certain you'll find something to your liking." },
        ["text"] = "Вітаю! Прийшов долучитися до бенкету Щедрості пілігрима? Прошу, сідай за Щедрий Стіл.$B$BСкуштуй усього! Упевнений, знайдеш щось до смаку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4186945533] = {
        ["english"] = { [1] = "Ye'll find the battlemasters around the war table in the Hall of Arms." },
        ["text"] = "Полководців знайдеш біля військового столу в Залі Зброї.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [256837303] = {
        ["english"] = { [1] = "Welcome to Tranquillien, $c. I apologize for the state that you find it in. As you can see, we've been having some trouble, but the Forsaken, and their Lady Sylvanas Windrunner, have been gracious enough to lend us a great deal of assistance in our time of need.$B$BIf you can lend a hand please do not hesitate to do so. We can use all of the help that we can get in our struggle against the myriad forces arrayed against us." },
        ["text"] = "Ласкаво просимо до Транквілієна, $c. Перепрошую за стан, у якому ти його застав. Як бачиш, у нас чимало проблем, але Відречені та їхня Пані Сильвана Вітрогін були досить милостиві, щоб надати нам значну допомогу в скрутний час.$B$BЯкщо можеш допомогти — не вагайся. У боротьбі з незліченними силами, що виступили проти нас, нам стане в пригоді будь-яка допомога.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [909965860] = {
        ["english"] = { [1] = "Welcome to Tinker Town!" },
        ["text"] = "Ласкаво просимо до Міста Механіків!",
        ["npcs"] = { [1] = 7937 },
        ["roles"] = { ["greeting"] = true },
    },
    [3868852607] = {
        ["english"] = { [1] = "Welcome to Thorium Point. As Overseer, I'm responsible for all the activities of the Thorium Brotherhood.  While that mainly involves mining, smithing, and some minor guard duty, we've lately become more of a martial organization... out of necessity." },
        ["text"] = "Ласкаво просимо до Торієвої застави. Як наглядач, я відповідаю за всю діяльність Торієвого братства. Здебільшого це гірництво, ковальство й трохи вартової служби, але останнім часом із необхідності ми стали значно більш військовою організацією.",
        ["npcs"] = { [1] = 14625 },
        ["roles"] = { ["greeting"] = true },
    },
    [3677926357] = {
        ["english"] = { [1] = "Welcome to Theramore." },
        ["text"] = "Ласкаво просимо до Терамора.",
        ["npcs"] = { [1] = 4921 },
        ["roles"] = { ["greeting"] = true },
    },
    [2599159514] = {
        ["english"] = { [1] = "Well... I hate to admit it, but my sister's the one you'll have to talk to if you want to continue training. I don't know as much as she does... yet! She's standing over by the rocket car." },
        ["text"] = "Що ж... не люблю це визнавати, але якщо хочеш продовжити навчання, доведеться поговорити з моєю сестрою. Я ще не знаю стільки, скільки вона... поки що! Вона стоїть біля ракетного автомобіля.",
        ["npcs"] = { [1] = 11028 },
        ["roles"] = { ["greeting"] = true },
    },
    [2539981011] = {
        ["english"] = { [1] = "To honor your elders is to honor your culture and your people, $c.  For this, the Coins of Ancestry serve as a tangible means to recognize those who choose to follow a venerable path of respect.$B$BDuring this Lunar Festival, you may have the opportunity to honor many elders.  As you do so, you will acquire the Coins of Ancestry.  Bring me these coins, and I will reward your diligence with a selection of unique items.\010" },
        ["text"] = "Шанувати старійшин — означає шанувати свою культуру й свій народ, $c. Монети Предків слугують відчутним знаком пошани до тих, хто обирає шлях поваги до давніх традицій.$B$BПід час Місячного фестивалю тобі випаде нагода вшанувати багатьох старійшин. За це ти отримуватимеш Монети Предків. Принеси їх мені, і я винагороджу твою старанність добіркою унікальних предметів.\010",
        ["npcs"] = { [1] = 15864 },
        ["roles"] = { ["greeting"] = true },
    },
    [2429628979] = {
        ["english"] = { [1] = "We'd be gettin' ready to take back da Echo Isles. Zalazane has been workin' his voodoo magic for some time, convincing folks dat he be dead and performing ancient dark rituals.$B$BHe knows we'd be coming, so we have ta make sure we be prepared." },
        ["text"] = "Ми готуємося відбити Острови Відлуння. Залазейн уже давно чаклує своє вуду, переконуючи всіх, ніби він мертвий, і проводить древні темні ритуали.$B$BВін знає, що ми прийдемо, тож треба добре підготуватися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1769096404] = {
        ["english"] = { [1] = "Welcome to Thelsamar, your home away from home in Loch Modan!$B$BThelsamar is a nice place, but it's not all beer and salted meat for those who answer the call to duty!  If you're willing to face danger in the name of the Alliance, then read the poster outside the Thelsamar branch of the Explorers' League." },
        ["text"] = "Ласкаво просимо до Телсамара — твого другого дому в Лох-Модані!$B$BТелсамар — чудове місце, але для тих, хто відповідає на поклик обов'язку, тут не лише пиво й солоне м'ясо! Якщо готовий зустріти небезпеку в ім'я Альянсу, прочитай оголошення біля телсамарського відділення Ліги дослідників.",
        ["npcs"] = { [1] = 1340 },
        ["roles"] = { ["greeting"] = true },
    },
    [3602575466] = {
        ["english"] = { [1] = "Welcome to the Wickerman Festival, $c!$B$BOn the observance of Hallow's End, the Forsaken burn a wickerman in honor of this, the most revered of occasions.  It was on this day that the Banshee Queen herself delivered us from the clutches of the Lich King and the Scourge.  We have remained free ever since.  Those who would have seen us fall are repayed in full... with vengeance!$B$BThe burning of the Wickerman begins at 8:00 PM!" },
        ["text"] = "Ласкаво просимо на Свято Плетеного Чоловіка, $c!$B$BУ Ніч усіх святих Відречені спалюють плетеного чоловіка на честь цієї найшанованішої події. Саме цього дня Королева Банші звільнила нас із пазурів Короля-Ліча та Скари. Відтоді ми лишаємося вільними. Ті, хто бажав нашого падіння, отримають сповна... помстою!$B$BСпалення Плетеного Чоловіка починається о 20:00!",
        ["npcs"] = { [1] = 15197 },
        ["roles"] = { ["greeting"] = true },
    },
    [2279061796] = {
        ["english"] = { [1] = "Through the milennia, Ilyenia Moonfire has mastered numerous weapons and now offers to train others in their use.  You can find her at the Warrior's Terrace if you desire training." },
        ["text"] = "Протягом тисячоліть Іленія Мунфаєр опанувала безліч видів зброї й тепер навчає інших користуватися ними. Якщо бажаєш навчитися, знайдеш її на Терасі Воїнів.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [2102164637] = {
        ["english"] = { [1] = "Want to make your demons more powerful?  It'll cost you, but you've come to the right place." },
        ["text"] = "Хочеш зробити своїх демонів сильнішими? Це коштуватиме грошей, але ти прийшов за адресою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2807559059] = {
        ["english"] = { [1] = "Welcome to the Royal Exchange Bank, $g sir : ma'am;. How may I help you?" },
        ["text"] = "Ласкаво просимо до банку Королівської Біржі, $g пане : пані;. Чим можу допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [162144370] = {
        ["english"] = { [1] = "We barely have any excess supplies.  It'll take a lot more work before we're ready to send another ground assault into the Field of Strife." },
        ["text"] = "Зайвих припасів у нас майже немає. Потрібно ще багато попрацювати, перш ніж ми зможемо відправити новий наземний наступ на Поле Чвар.",
        ["npcs"] = { [1] = 12096 },
        ["roles"] = { ["greeting"] = true },
    },
    [234223928] = {
        ["english"] = { [1] = "Tragic..." },
        ["text"] = "Трагічно...",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["reply"] = true },
    },
    [880291934] = {
        ["english"] = { [1] = "Welcome to the Registrar of Guilds.  How can I be of service to you?" },
        ["text"] = "Ласкаво просимо до Реєстратора гільдій. Чим можу прислужитися?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1803940705] = {
        ["english"] = { [1] = "Where did everyone go?" },
        ["text"] = "Куди всі поділися?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [426473252] = {
        ["english"] = { [1] = "Warlock" },
        ["text"] = "Чорнокнижник",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3296, [18] = 5595, [19] = 5624, [20] = 5725, [21] = 5953, [22] = 6272, [23] = 6740, [24] = 8931, [25] = 12996, [26] = 13076 },
        ["roles"] = { ["reply"] = true },
    },
    [2854221449] = {
        ["english"] = { [1] = "Welcome to the front lines, $c.  The Kingdom of Stormwind, with the aid of its allies, has sent me here to counter the growing threat of the Scourge.  Here at Chillwind Point, we fight for our continued survival on a daily basis.$B$BIf you've come here looking for a chance to prove yourself as a hero, then you'll find plenty of opportunities to do so... especially as we push towards Andorhal and whatever malign force that controls the Scourge there." },
        ["text"] = "Ласкаво просимо на передову, $c. Королівство Штормовію за підтримки союзників відправило мене сюди протистояти зростаючій загрозі Скари. Тут, на заставі Стужевію, ми щодня боремося за виживання.$B$BЯкщо ти прийшов сюди, щоб довести свою героїчність, нагод буде вдосталь... особливо коли ми просуваємося до Андорала й тієї зловісної сили, що керує там Скарою.",
        ["npcs"] = { [1] = 10838 },
        ["roles"] = { ["greeting"] = true },
    },
    [1720884361] = {
        ["english"] = { [1] = "Welcome back, $N. Have I mentioned how good it is to have someone to talk to?$B$BAlright then, let's get down to business. What's next that we have to do?" },
        ["text"] = "З поверненням, $N. Я вже казав, як добре мати когось, із ким можна поговорити?$B$BГаразд, до справи. Що нам тепер треба зробити?",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [1733202305] = {
        ["english"] = { [1] = "What do you think I could teach you? Roxxik would do a much better job. You can find him in Orgrimmar. Now be off!" },
        ["text"] = "Чого я можу тебе навчити? Роксік упорається значно краще. Знайдеш його в Орґріммарі. А тепер іди!",
        ["npcs"] = { [1] = 11031 },
        ["roles"] = { ["greeting"] = true },
    },
    [1423033821] = {
        ["english"] = { [1] = "Welcome to the races!  Enjoy your stay, and don't bet all your money in one place!" },
        ["text"] = "Ласкаво просимо на перегони! Приємного відпочинку й не став усі гроші на одного!",
        ["npcs"] = { [1] = 4419 },
        ["roles"] = { ["greeting"] = true },
    },
    [467386096] = {
        ["english"] = { [1] = "Welcome! Have you yet honored this land's flame?" },
        ["text"] = "Вітаю! Ти вже вшанував полум'я цієї землі?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2677705094] = {
        ["english"] = { [1] = "Welcome to the Darkmoon Faire, $c!$B$BMy name is Kerri Hicks and I'd shake your hand but I'm afraid I'd break it, because I'm the strongest woman alive!" },
        ["text"] = "Ласкаво просимо на ярмарок Темного Місяця, $c!$B$BМене звати Керрі Гікс, і я б потиснула тобі руку, але боюся зламати її, бо я найсильніша жінка у світі!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [314692303] = {
        ["english"] = { [1] = "Welcome to the Cenarion Circle, $c.  How may I assist you?" },
        ["text"] = "Ласкаво просимо до Кенарієвого Кола, $c. Чим можу допомогти?",
        ["npcs"] = { [1] = 4205, [2] = 5501 },
        ["roles"] = { ["greeting"] = true },
    },
    [1585615076] = {
        ["english"] = { [1] = "Welcome to the Cenarion Circle, $c." },
        ["text"] = "Ласкаво просимо до Кенарієвого Кола, $c.",
        ["npcs"] = { [1] = 3596, [2] = 4146 },
        ["roles"] = { ["greeting"] = true },
    },
    [3455659734] = {
        ["english"] = { [1] = "Welcome to the Booty Bay fishing contest where each week we choose the finest fisherman to be the Master Angler!\010\010Between 2pm and 4pm schools of tastyfish will appear up and down the coast of Stranglethorn.  While fishing if your fishing bobber lands in a tastyfish school then you will catch something from the school rather than the normal stranglethorn fishing fare.\010" },
        ["text"] = "Ласкаво просимо на рибальський турнір Бухти Наживи, де щотижня ми обираємо найкращого рибалку й проголошуємо його Майстром Вудки!\010\010Щонеділі між 14:00 та 16:00 вздовж узбережжя Тернистої долини з'являються косяки Смачної Риби. Якщо під час риболовлі твій поплавець упаде в такий косяк, ти витягнеш щось із нього замість звичайного улову Тернистої долини.\010",
        ["npcs"] = { [1] = 15077 },
        ["roles"] = { ["greeting"] = true },
    },
    [639672460] = {
        ["english"] = { [1] = "Welcome to the Blue Recluse, where the magically inclined gather to blow off steam. Though not literally of course. What can I get for you $g sir : ma'am;?" },
        ["text"] = "Ласкаво просимо до «Блакитного Відлюдника», де магічно обдаровані збираються випустити пару. Не буквально, звісно. Що подати, $g пане : пані;?",
        ["npcs"] = { [1] = 1311 },
        ["roles"] = { ["greeting"] = true },
    },
    [687386571] = {
        ["english"] = { [1] = "Welcome to the Bank of Stormwind. We offer financial accounts and safety deposit boxes for valuable items. Do you already have an account with us $g sir : ma'am;?" },
        ["text"] = "Ласкаво просимо до банку Штормовію. Ми пропонуємо банківські рахунки та сейфи для цінних речей. У вас уже є рахунок у нас, $g пане : пані;?",
        ["npcs"] = { [1] = 2455, [2] = 2456, [3] = 2457 },
        ["roles"] = { ["greeting"] = true },
    },
    [3162117461] = {
        ["english"] = { [1] = "While Nesingwary's advances upon the wildlife of Northrend has been halted, it is only a matter of time before he attempts another incursion. You must remain vigilant, $N!$B$BAbove all else, do not give in to whatever temptations may be set before you... The demon will attempt to charm you. When it happens, you must resist!" },
        ["text"] = "Хоч наступ Несінґварі на тварин Нортренду зупинено, це лише питання часу, коли він спробує знову. Будь пильний, $N!$B$BІ найголовніше — не піддавайся жодним спокусам, які перед тобою постануть... Демон спробує зачарувати тебе. Коли це станеться, ти мусиш опиратися!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3444072630] = {
        ["english"] = { [1] = "Until what, Eva? I must know." },
        ["text"] = "До чого, Єво? Я мушу знати.",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["reply"] = true },
    },
    [1160127946] = {
        ["english"] = { [1] = "Welcome, $N. I am Landro Longshot - manager of the Black Flame. Perhaps you've not heard of the Black Flame until now. That doesn't surprise me; we work to keep things that way. We prefer to avoid... factional entanglements.$B$BThe Black Flame specializes in providing the finest services and entertainment money can buy, whether they happen to be hard to find items, gladiatorial combat, or lucrative games of chance.$B$BAre you here seeking something specific?$B" },
        ["text"] = "Ласкаво просимо, $N. Я Ландро Довгостріл, керівник «Чорного Полум'я». Можливо, досі ти про нього не чув. Мене це не дивує — ми прагнемо, щоб так і залишалося. Ми воліємо уникати... міжфракційних ускладнень.$B$B«Чорне Полум'я» спеціалізується на найкращих послугах і розвагах, які можна купити за гроші: від рідкісних предметів і гладіаторських боїв до прибуткових азартних ігор.$B$BШукаєш щось конкретне?$B",
        ["npcs"] = { [1] = 17249 },
        ["roles"] = { ["greeting"] = true },
    },
    [1756015217] = {
        ["english"] = { [1] = "Well then, it seems we're both looking for Hogral Bakkan.  He's a dwarf to be sure, so sooner or later he'll be heading for the Thunderbrew Distillery for an ale -- he might even be there now." },
        ["text"] = "Ну що ж, схоже, ми обоє шукаємо Гоґрала Баккана. Він точно дворф, а отже рано чи пізно потягнеться до броварні Громоварів по кухоль елю — може, він уже там.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [464103300] = {
        ["english"] = { [1] = "Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?" },
        ["text"] = "Під час суворого перенавчання мені доводилося змушувати багатьох учнів забувати все, чого вони навчилися раніше, щоб я міг навчити їх наново. Послуга, яку я надаю, з кожним разом стає дедалі складнішою. Саме тому кожне наступне перенавчання коштує дорожче. Бажаєш, щоб я звільнив тебе від вивчених талантів?",
        ["npcs"] = { [1] = 198, [2] = 328, [3] = 331, [4] = 375, [5] = 376, [6] = 377, [7] = 459, [8] = 460, [9] = 461, [10] = 837, [11] = 895, [12] = 906, [13] = 911, [14] = 912, [15] = 913, [16] = 914, [17] = 915, [18] = 916, [19] = 917, [20] = 918, [21] = 925, [22] = 926, [23] = 927, [24] = 928, [25] = 944, [26] = 985, [27] = 986, [28] = 987, [29] = 988, [30] = 1226, [31] = 1228, [32] = 1229, [33] = 1231, [34] = 1232, [35] = 1234, [36] = 1404, [37] = 1411, [38] = 1901, [39] = 2119, [40] = 2122, [41] = 2123, [42] = 2124, [43] = 2126, [44] = 2127, [45] = 2128, [46] = 2129, [47] = 2130, [48] = 2131, [49] = 3030, [50] = 3031, [51] = 3032, [52] = 3033, [53] = 3034, [54] = 3036, [55] = 3038, [56] = 3039, [57] = 3040, [58] = 3041, [59] = 3042, [60] = 3043, [61] = 3044, [62] = 3045, [63] = 3046, [64] = 3047, [65] = 3048, [66] = 3049, [67] = 3059, [68] = 3060, [69] = 3061, [70] = 3062, [71] = 3063, [72] = 3064, [73] = 3065, [74] = 3066, [75] = 3153, [76] = 3154, [77] = 3155, [78] = 3156, [79] = 3157, [80] = 3169, [81] = 3170, [82] = 3171, [83] = 3172, [84] = 3173, [85] = 3324, [86] = 3325, [87] = 3326, [88] = 3327, [89] = 3328, [90] = 3344, [91] = 3352, [92] = 3353, [93] = 3354, [94] = 3401, [95] = 3403, [96] = 3406, [97] = 3407, [98] = 3408, [99] = 3593, [100] = 3594, [101] = 3595, [102] = 3596, [103] = 3597, [104] = 3598, [105] = 3599, [106] = 3600, [107] = 3601, [108] = 3602, [109] = 3706, [110] = 3707, [111] = 3963, [112] = 4087, [113] = 4089, [114] = 4090, [115] = 4091, [116] = 4092, [117] = 4138, [118] = 4163, [119] = 4205, [120] = 4214, [121] = 4215, [122] = 4218, [123] = 4219, [124] = 4563, [125] = 4564, [126] = 4565, [127] = 4566, [128] = 4567, [129] = 4568, [130] = 4582, [131] = 4583, [132] = 4584, [133] = 4593, [134] = 4594, [135] = 4595, [136] = 4606, [137] = 4607, [138] = 4608, [139] = 5113, [140] = 5114, [141] = 5115, [142] = 5116, [143] = 5117, [144] = 5141, [145] = 5142, [146] = 5143, [147] = 5144, [148] = 5145, [149] = 5146, [150] = 5147, [151] = 5148, [152] = 5149, [153] = 5165, [154] = 5166, [155] = 5167, [156] = 5171, [157] = 5172, [158] = 5173, [159] = 5479, [160] = 5480, [161] = 5484, [162] = 5489, [163] = 5491, [164] = 5492, [165] = 5495, [166] = 5496, [167] = 5497, [168] = 5498, [169] = 5501, [170] = 5504, [171] = 5505, [172] = 5506, [173] = 5515, [174] = 5516, [175] = 5517, [176] = 5612, [177] = 5880, [178] = 5882, [179] = 5883, [180] = 5884, [181] = 5885, [182] = 5994, [183] = 6014, [184] = 6018, [185] = 6707, [186] = 7311, [187] = 7312, [188] = 7315, [189] = 8140, [190] = 8141, [191] = 8142, [192] = 8308, [193] = 9465, [194] = 10930, [195] = 11397, [196] = 11401, [197] = 11406, [198] = 12042, [199] = 13283, [200] = 13417 },
        ["roles"] = { ["greeting"] = true },
    },
    [1633366726] = {
        ["english"] = { [1] = "What do you mean what do I mean? She went nutso! The girl went straight crazy on us. Now ordinarily I don't hit girls but after I recovered from the blackout, I was pretty damned angry. Brann, Rutgar, me and the monkey went positively orc on her! It's a miracle we were able to fend her off. She seemed almost possessed!" },
        ["text"] = "Що значить «що я маю на увазі»? Вона з'їхала з глузду! Дівчина просто збожеволіла. Зазвичай я дівчат не б'ю, але коли отямився після того, як мене вирубило, я був страшенно злий. Бранн, Рутґар, я та мавпа навалилися на неї по-орчому! Дивом вдалося відбитися. Здавалося, ніби в неї вселилося щось!",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["greeting"] = true },
    },
    [1416906995] = {
        ["english"] = { [1] = "Welcome to Starfall Village, traveler. Have you come to assist us?" },
        ["text"] = "Ласкаво просимо до селища Зорепад, мандрівнику. Прийшов нам допомогти?",
        ["npcs"] = { [1] = 11079 },
        ["roles"] = { ["greeting"] = true },
    },
    [1492156923] = {
        ["english"] = { [1] = "Ticket redemption here!  Get your tickets turned into prizes!  Step right up!" },
        ["text"] = "Обмін квитків тут! Міняйте квитки на призи! Підходьте, не соромтеся!",
        ["npcs"] = { [1] = 14828 },
        ["roles"] = { ["greeting"] = true },
    },
    [3767023507] = {
        ["english"] = { [1] = "Twin Spire Ruins is not yet secure! My orders are to only give out battle standards when the two beacons are lit and the area is secure. Get out there and gain control of those beacons!" },
        ["text"] = "Руїни Двох Шпилів іще не убезпечені! Мені наказано видавати бойові штандарти лише тоді, коли запалено обидва маяки й територію взято під контроль. Вирушай туди й захопи ці маяки!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1477325471] = {
        ["english"] = { [1] = "What are the stones of binding?" },
        ["text"] = "Що таке камені поневолення?",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["reply"] = true },
    },
    [600074328] = {
        ["english"] = { [1] = "Throm-Ka, $c. My mood is poor this day, so please, unless you can help me, I would prefer to be alone." },
        ["text"] = "Тром-ка, $c. Сьогодні я не в гуморі, тож прошу: якщо не можеш мені допомогти, я волів би побути на самоті.",
        ["npcs"] = { [1] = 9620 },
        ["roles"] = { ["greeting"] = true },
    },
    [3287031302] = {
        ["english"] = { [1] = "Welcome to Ogri'la, $c.$B$BThe ogres here have managed to gain a great mental acuity through the magical emanations of the surrounding crystals.  Though we do not fully understand how they work, we have come to appreciate our new home and only want to live in peace.$B$BUnfortunate then that the demons and ethereals, and especially the Black Dragonflight, will not leave us to that peace." },
        ["text"] = "Ласкаво просимо до Оґрі'ли, $c.$B$BОгри тут досягли великої гостроти розуму завдяки магічному випромінюванню навколишніх кристалів. Ми не до кінця розуміємо, як це працює, але полюбили наш новий дім і хочемо лише жити в мирі.$B$BНа жаль, демони, ефірники, а особливо Чорна драконяча зграя не хочуть залишити нас у спокої.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2021900059] = {
        ["english"] = { [1] = "Welcome to Grom'gol, $C. Before we get off on the wrong foot, I'll have you know that I won't have slackers in my Base Camp.. I expect a healthy $R like you to pull your own weight around here." },
        ["text"] = "Ласкаво просимо до Ґром'ґола, $C. Щоб одразу не почати з непорозумінь: ледарів у моєму таборі я не терплю. Від здорового $R, як ти, я очікую, що тут він нестиме свою частку роботи.",
        ["npcs"] = { [1] = 2464 },
        ["roles"] = { ["greeting"] = true },
    },
    [329093907] = {
        ["english"] = { [1] = "Walk in the Light, my child." },
        ["text"] = "Ступай у Світлі, дитя моє.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3390832617] = {
        ["english"] = { [1] = "We cannot allow the Horde to turn the hidden secrets of the Strand of the Ancients against us. Will you join our brave soldiers there?" },
        ["text"] = "Ми не можемо дозволити Орді обернути приховані таємниці Берега Древніх проти нас. Приєднаєшся до наших хоробрих солдатів там?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4082797016] = {
        ["english"] = { [1] = "What are the chances of obtaining such a hide?" },
        ["text"] = "Які шанси здобути таку шкуру?",
        ["npcs"] = { [1] = 10637 },
        ["roles"] = { ["reply"] = true },
    },
    [1991088724] = {
        ["english"] = { [1] = "Welcome to Booty Bay, $r." },
        ["text"] = "Ласкаво просимо до Бухти Наживи, $r.",
        ["npcs"] = { [1] = 2487 },
        ["roles"] = { ["greeting"] = true },
    },
    [2575179412] = {
        ["english"] = { [1] = "Very well then...$B$BYou have been tasked by your liege to guard his fields of corn from poachers and thieves.  One night on patrol, you stumble across a haggard man in thread-bare clothing stealing corn from the field.  You quickly confront him, and he immediately begs for his life.  He claims he is stealing the corn to feed his family since the lord of the land - your liege - demands too much in taxes.  Your liege is indeed known for his harsh taxes throughout the land.$B$BMake your choice.\010" },
        ["text"] = "Гаразд тоді...$B$BТвій володар доручив тобі охороняти його кукурудзяні поля від браконьєрів і злодіїв. Якось уночі під час патрулювання ти помічаєш виснаженого чоловіка в лахмітті, який краде кукурудзу з поля. Ти одразу його зупиняєш, і він починає благати про пощаду. Каже, що краде кукурудзу, аби нагодувати родину, бо землевласник — твій володар — вимагає надто високі податки. І справді, твій володар відомий у всіх цих землях своєю жорстокою податковою політикою.$B$BЗроби свій вибір.\010",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["greeting"] = true },
    },
    [1064081561] = {
        ["english"] = { [1] = "We have all been witness to terrible tragedies, but we must not let them drag us to despair.$B$BInstead, hold those memories close so that one day, we might find a reckoning." },
        ["text"] = "Усі ми були свідками страшних трагедій, але не можна дозволити їм втягнути нас у відчай.$B$BНатомість бережи ці спогади, щоб одного дня ми змогли домогтися розплати.",
        ["npcs"] = { [1] = 11063 },
        ["roles"] = { ["greeting"] = true },
    },
    [2180157171] = {
        ["english"] = { [1] = "What it is that I do, of course. I brood. I lament. I hate. I plot. When that cycle is complete, I brood again. What is it you want from me? I have much on my mind." },
        ["text"] = "Що саме я роблю? Звісно ж. Я похмуро розмірковую. Нарікаю. Ненавиджу. Плету змови. Коли цикл завершується, знову починаю похмуро розмірковувати. Чого тобі від мене? У мене багато думок.",
        ["npcs"] = { [1] = 10918 },
        ["roles"] = { ["greeting"] = true },
    },
    [2444686558] = {
        ["english"] = { [1] = "To learn to be one with Nature in the eyes of the Earth Mother, this is a matter of pride.  If your will is to learn the ways of the Hunter you must seek out Yaw Sharpmane at the north end of Bloodhoof Village." },
        ["text"] = "Навчитися жити в гармонії з Природою в очах Матері-Землі — справа честі. Якщо прагнеш опанувати шлях мисливця, знайди Ява Гострогривого на північному краю селища Криваве Копито.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [1489471920] = {
        ["english"] = { [1] = "Weary of one of your demonic charges? Hoping for one with a more pleasing name?$B$B$B$BFor a price, I can assist you in the obliteration of a current minion so that you may summon an entirely new one..." },
        ["text"] = "Набрид один із твоїх демонічних слуг? Сподіваєшся отримати нового з приємнішим ім'ям?$B$B$B$BЗа певну плату я допоможу тобі знищити поточного прислужника, щоб ти міг викликати зовсім нового...",
        ["npcs"] = { [1] = 5520, [2] = 5749, [3] = 5750, [4] = 5753, [5] = 5815, [6] = 6027, [7] = 6328, [8] = 6373, [9] = 6374, [10] = 6382, [11] = 12776 },
        ["roles"] = { ["greeting"] = true },
    },
    [190721094] = {
        ["english"] = { [1] = "We, the Zandalarian trolls, traveled here from distant islands, for we cannot ignore the threat that now faces our world." },
        ["text"] = "Ми, зандаларські тролі, прибули сюди з далеких островів, бо не можемо ігнорувати загрозу, що нині постала перед нашим світом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3225453460] = {
        ["english"] = { [1] = "What is it you ask of the Blue Flight?" },
        ["text"] = "Про що ти просиш Синю зграю?",
        ["npcs"] = { [1] = 10929 },
        ["roles"] = { ["greeting"] = true },
    },
    [2371923641] = {
        ["english"] = { [1] = "What else do you have to say?" },
        ["text"] = "Що ще ти хочеш сказати?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2572807083] = {
        ["english"] = { [1] = "We must resist!  Gird your soul!  Burn the foul plague wherever you find it!" },
        ["text"] = "Ми мусимо чинити опір! Зміцни дух! Випалюй огидну чуму всюди, де її знайдеш!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1853904064] = {
        ["english"] = { [1] = "What are Darkmoon Cards?" },
        ["text"] = "Що таке карти Темного Місяця?",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["reply"] = true },
    },
    [3965628782] = {
        ["english"] = { [1] = "We Thunderbrews take pride knowing that we are the best brewhouse in all the realms." },
        ["text"] = "Ми, Громовари, пишаємося тим, що наша броварня — найкраща в усіх землях.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3282589018] = {
        ["english"] = { [1] = "We set up this area to practice fire fighting.  You never know when the town will be imperiled!" },
        ["text"] = "Ми облаштували тут місце для тренувань із гасіння пожеж. Ніколи не знаєш, коли місто опиниться в небезпеці!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1061285713] = {
        ["english"] = { [1] = "Very well, let your journey of tailoring begin." },
        ["text"] = "Гаразд, нехай почнеться твій шлях кравецтва.",
        ["npcs"] = { [1] = 1300 },
        ["roles"] = { ["greeting"] = true },
    },
    [1727811134] = {
        ["english"] = { [1] = "What you see here on this coast is not a result of the Scourge. In fact, we believe that the Scourge also fear the mist - which might be why they do not come here.$B$BYou see, the mist is alive, friend. Inside those airy tendrils lies death...$B$BShould you step within its grasp, you will vanish. The mist will take you!$B$BWe have never seen anyone return alive from the mist." },
        ["text"] = "Те, що ти бачиш на цьому узбережжі, — не справа Скари. Насправді ми вважаємо, що й Скара боїться туману — можливо, саме тому вони сюди не приходять.$B$BРозумієш, туман живий, друже. У його повітряних щупальцях ховається смерть...$B$BЯкщо ступиш у його обійми — зникнеш. Туман забере тебе!$B$BМи ніколи не бачили, щоб хтось повернувся з туману живим.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2628764831] = {
        ["english"] = { [1] = "We're not really rude people, stranger, it's just that everyone is in a rush, trying to make sure that everything is perfect for Uther's arrival. It's not often that the Lightbringer comes to town." },
        ["text"] = "Ми насправді не грубі люди, незнайомцю. Просто всі поспішають, намагаючись зробити все ідеально до прибуття Утера. Не щодня Світлонос приходить у місто.",
        ["npcs"] = { [1] = 11277 },
        ["roles"] = { ["greeting"] = true },
    },
    [751604591] = {
        ["english"] = { [1] = "We have no such place in the village.  The soaring heights of Thunder Bluff does though.  Head north up the road out of Bloodhoof Village until you come to the base of the bluffs.  There ride the elevator to the top and speak with a Bluffwatcher.  May your ancestors watch over you." },
        ["text"] = "У селищі такого місця немає. Зате воно є на високих вершинах Громового Бескиду. Іди дорогою на північ із селища Криваве Копито, доки не дістанешся підніжжя бескидів. Там піднімися ліфтом нагору й поговори з Вартовим Бескиду. Нехай предки оберігають тебе.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [1727437072] = {
        ["english"] = { [1] = "We're currently focus testing the Battle of Mount Hyjal. You must have at least HONORED reputation with the Violet Eye to participate.$B$BThat's the reputation you gain while doing Karazhan." },
        ["text"] = "Зараз ми тестуємо Битву за гору Гіджал. Щоб узяти участь, потрібно мати щонайменше ПОВАЖНУ репутацію в Аметистовому Оці.$B$BЦе та репутація, яку здобувають у Каражані.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1816889614] = {
        ["english"] = { [1] = "We're building another road down into Stormwind Harbor as soon as this wall has been removed... but this mad dwarf brought enough powder to level the entire quarter!$B$BI don't know what Master Alexston was thinking when he hired her... she's foul-mouthed, mean, and stubborn as an ox!" },
        ["text"] = "Щойно цю стіну приберуть, ми почнемо будувати ще одну дорогу вниз до Штормовійської гавані... але ця божевільна дворфійка принесла стільки пороху, що можна зрівняти з землею весь квартал!$B$BНе знаю, про що думав майстер Алексстон, коли наймав її... вона лихословить, злюща й уперта, мов віл!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1835823571] = {
        ["english"] = { [1] = "We are the only supplier of healthy flowers in all of Stormwind. We provide beautiful blooms for any occasion." },
        ["text"] = "Ми — єдиний постачальник свіжих квітів у всьому Штормовії. У нас є прекрасні букети на будь-яку нагоду.",
        ["npcs"] = { [1] = 1302, [2] = 1303 },
        ["roles"] = { ["greeting"] = true },
    },
    [2923097639] = {
        ["english"] = { [1] = "Vrykuls is bigger and stronger than us.  But we is better looking!" },
        ["text"] = "Врікули більші й сильніші за нас. Зате ми вродливіші!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2800190328] = {
        ["english"] = { [1] = "Tomas may not be the best cook around, but he has a few dishes that hit the spot.  He's currently working in the Lion's Pride Inn if you'd like to learn the profession." },
        ["text"] = "Томас, може, й не найкращий кухар у цих краях, але кілька його страв справді смакують як слід. Зараз він працює в таверні «Гордість Лева», якщо хочеш опанувати цю професію.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3755683761] = {
        ["english"] = { [1] = "We're almost ready to depart. Just give us a little bit longer to finish our preparations." },
        ["text"] = "Ми майже готові вирушати. Дай нам іще трохи часу завершити приготування.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3564381560] = {
        ["english"] = { [1] = "Welcome. Will you take your rest here, or perhaps a meal?" },
        ["text"] = "Ласкаво просимо. Відпочинеш тут чи, може, бажаєш поїсти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3908124906] = {
        ["english"] = { [1] = "Where is the Auction House?  Why it's right by the gates of Ironforge as you enter our fine city.  Ye'll find it just across from The Vault." },
        ["text"] = "Де Аукціонний дім? Та просто біля брам Стальгорна, як входиш до нашого прекрасного міста. Знайдеш його навпроти Сховища.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [1792366537] = {
        ["english"] = { [1] = "Watch where you're stepping, $c, because I have a polymorph spell with your name on it..." },
        ["text"] = "Дивися під ноги, $c, бо в мене є закляття поліморфії саме для тебе...",
        ["npcs"] = { [1] = 6548 },
        ["roles"] = { ["greeting"] = true },
    },
    [3850759160] = {
        ["english"] = { [1] = "Well done! Your fighting against all those beasts was splendid! I hear the next challenge should be even tougher!" },
        ["text"] = "Молодець! Ти чудово бився з усіма тими звірами! Кажуть, наступне випробування буде ще важчим!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2701548582] = {
        ["english"] = { [1] = "We've a duty out here, $g boy : girl;, to see to it that we don't let anyone surprise us.$B$BThat means proactive action!" },
        ["text"] = "У нас тут є обов'язок, $g хлопче : дівчино;: не дозволити нікому застати нас зненацька.$B$BА це означає діяти на випередження!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [163058992] = {
        ["english"] = { [1] = "Welcome to the Farstrider Retreat.  We are rangers sworn to defend our people from enemies both near and far." },
        ["text"] = "Ласкаво просимо до Притулку далекоходців. Ми слідопити, що присягнули захищати наш народ від близьких і далеких ворогів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2030471837] = {
        ["english"] = { [1] = "We're putting the final preparations together even as we speak.  The rest will depend upon how quickly you can organize your forces at Ruuan Weald.$B$BDo you think that you can handle that and get it done quickly?" },
        ["text"] = "Просто зараз ми завершуємо останні приготування. Решта залежатиме від того, наскільки швидко ти зможеш організувати свої сили в гаю Рууан.$B$BДумаєш, упораєшся й зробиш усе швидко?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [318317016] = {
        ["english"] = { [1] = "We protect this airship on its way from Orgrimmar to Grom'gol base camp in Stranglethorn Vale." },
        ["text"] = "Ми охороняємо цей повітряний корабель на шляху з Орґріммара до табору Ґром'ґол у Тернистій долині.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [258315640] = {
        ["english"] = { [1] = "Welcome to Zabra'jin, $c. I am Shadow Hunter Denjai, overseer of this outpost and commander of the Darkspear forces in Zangarmarsh." },
        ["text"] = "Ласкаво просимо до Забра'джина, $c. Я мисливець за тінями Денджай, наглядач цього форпосту й командир сил Темносписів у Занґарських болотах.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2863357738] = {
        ["english"] = { [1] = "We have our duties, $c.  Duties to the Horde." },
        ["text"] = "У нас є обов'язки, $c. Обов'язки перед Ордою.",
        ["npcs"] = { [1] = 3389 },
        ["roles"] = { ["greeting"] = true },
    },
    [2046059292] = {
        ["english"] = { [1] = "We don't have a bank here in Brill, you'll have to go to the Undercity for that.  At the back of the Ruins of Lordaeron to the south are elevators that will take you down into the Undercity.  Once there ask one of the Undercity Guardians for more precise directions." },
        ["text"] = "У Бріллі банку немає, тож доведеться йти до Підмістя. У південній частині Руїн Лордерону є підіймачі, які спускаються до Підмістя. Коли дістанешся туди, запитай точніший шлях у одного з вартових Підмістя.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [220111242] = {
        ["english"] = { [1] = "We mustn't anger the Master. His is a wrath that is cruel beyond measure." },
        ["text"] = "Не можна гнівити Господаря. Його гнів незмірно жорстокий.",
        ["npcs"] = { [1] = 14369 },
        ["roles"] = { ["greeting"] = true },
    },
    [1675165744] = {
        ["english"] = { [1] = "We must search for survivors. If anyone is still alive, we must at least try and get them back..." },
        ["text"] = "Треба шукати тих, хто вижив. Якщо хтось іще живий, ми принаймні повинні спробувати повернути їх...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1720325321] = {
        ["english"] = { [1] = "We must continue to hold on for as long as we can! Fight on!" },
        ["text"] = "Ми мусимо триматися якомога довше! Бийся далі!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1334157688] = {
        ["english"] = { [1] = "Travel to Orgrimmar, to the Valley of Honor. There she lives with her husband and two daughters. All of them are smiths of great skill, but the spirits tell me that she will best guide your learning." },
        ["text"] = "Вирушай до Орґріммара, в Долину Честі. Там вона живе зі своїм чоловіком і двома доньками. Усі вони вправні ковалі, але духи кажуть мені, що саме вона найкраще спрямує твоє навчання.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4175805768] = {
        ["english"] = { [1] = "We may have been suffering a drought but there's no shortage of meat! Care to browse my goods?" },
        ["text"] = "Може, нас і мучила посуха, зате м'яса не бракує! Хочеш поглянути на мій товар?",
        ["npcs"] = { [1] = 8125 },
        ["roles"] = { ["greeting"] = true },
    },
    [544847718] = {
        ["english"] = { [1] = "To summon a Dreadsteed, you must first create a Circle of Greater Summoning.  A portal to Xoroth may only be created from within such a circle.$B$BThe Circle of Greater Summoning requires three powerful implements: a Bell of Dethmoora, a Wheel of the Black March and a Doomsday Candle." },
        ["text"] = "Щоб викликати Жахоконя, спочатку потрібно створити Коло Великого Виклику. Портал до Ксорота можна відкрити лише всередині такого кола.$B$BДля Кола Великого Виклику потрібні три могутні знаряддя: Дзвін Детмури, Колесо Чорного Походу та Свічка Судного Дня.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [498605050] = {
        ["english"] = { [1] = "What brings you to the Cenarion Circle, $N?" },
        ["text"] = "Що привело тебе до Кенарієвого Кола, $N?",
        ["npcs"] = { [1] = 4217 },
        ["roles"] = { ["greeting"] = true },
    },
    [524784644] = {
        ["english"] = { [1] = "We are free of the Headless Horseman's terror, for now.  We may breathe easy again, but until he can be defeated while joined with his head, he may return." },
        ["text"] = "Поки що ми вільні від жаху Вершника без голови. Знову можемо зітхнути спокійно, але доки його не переможуть, коли голова буде з'єднана з тілом, він може повернутися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2721633156] = {
        ["english"] = { [1] = "Treat the wind rider well as it takes you to your destination.  May your ancestors watch over you $N." },
        ["text"] = "Добре поводься з вітрокрилом, поки він нестиме тебе до місця призначення. Нехай предки оберігають тебе, $N.",
        ["npcs"] = { [1] = 10378 },
        ["roles"] = { ["greeting"] = true },
    },
    [3592251169] = {
        ["english"] = { [1] = "To get down safely, I provide wings to those in need. " },
        ["text"] = "Щоб безпечно спуститися вниз, я даю крила тим, хто їх потребує. ",
        ["npcs"] = { [1] = 7772 },
        ["roles"] = { ["greeting"] = true },
    },
    [2182634918] = {
        ["english"] = { [1] = "Who is the Headless Horseman?" },
        ["text"] = "Хто такий Вершник без голови?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [4293700788] = {
        ["english"] = { [1] = "Without delivery of the Underlight ore in such a timely fashion, our research would have failed.$B$BJust wait until Shatharia shows her head here again. I've got some interesting tasks for her, you can be sure of it!" },
        ["text"] = "Якби руда Підсвіття не прибула так вчасно, наше дослідження провалилося б.$B$BЛише дочекайся, коли Шатарія знову покаже тут носа. У мене для неї знайдуться цікаві завдання, можеш не сумніватися!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [886517449] = {
        ["english"] = { [1] = "Where is Elder Dreamseer?" },
        ["text"] = "Де старійшина Сновидець?",
        ["npcs"] = { [1] = 15573, [2] = 15578, [3] = 15583, [4] = 15584 },
        ["roles"] = { ["reply"] = true },
    },
    [2157297257] = {
        ["english"] = { [1] = "We mustn't lose our focus. The dangers inherent in getting lost in the moment could put us in peril. Alas, the soldiers need a respite from this madness.$B$BBask in the victory, $N. If not for you we might have lost the Vanguard." },
        ["text"] = "Не можна втрачати зосередженість. Якщо надто захопитися миттю, це може поставити нас під загрозу. Та солдатам потрібен перепочинок від цього божевілля.$B$BНасолоджуйся перемогою, $N. Якби не ти, ми могли б втратити Авангард.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1863279897] = {
        ["english"] = { [1] = "We're glad to have your help." },
        ["text"] = "Ми раді твоїй допомозі.",
        ["npcs"] = { [1] = 2771 },
        ["roles"] = { ["greeting"] = true },
    },
    [2922376453] = {
        ["english"] = { [1] = "To care for these fearless beasts, who stand between my clanmates and death, is an honor." },
        ["text"] = "Піклуватися про цих безстрашних звірів, які стоять між моїми одноплемінниками та смертю, — велика честь.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2023125695] = {
        ["english"] = { [1] = "Where can I find Crystal Restore?" },
        ["text"] = "Де знайти Кришталеве відновлення?",
        ["npcs"] = { [1] = 10304 },
        ["roles"] = { ["reply"] = true },
    },
    [1762506216] = {
        ["english"] = { [1] = "Welcome to Garadar, stranger. Are you looking for a place to rest?" },
        ["text"] = "Ласкаво просимо до Ґарадара, незнайомцю. Шукаєш місце для відпочинку?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2055800234] = {
        ["english"] = { [1] = "We cannot allow the Alliance to turn the hidden secrets of the Strand of the Ancients against us. Will you join our brave warriors there?" },
        ["text"] = "Ми не можемо дозволити Альянсу обернути приховані таємниці Берега Древніх проти нас. Приєднаєшся до наших хоробрих воїнів там?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4180222475] = {
        ["english"] = { [1] = "We are all drawn here for different reasons, $c.$B$B<Rayne smiles.>$B$BI am here to meet with Rimblat of the Earthen Ring. He has some interesting theories on cleansing these lands." },
        ["text"] = "Усі ми опинилися тут із різних причин, $c.$B$B<Рейн усміхається.>$B$BЯ тут, щоб зустрітися з Рімблатом із Земного Кола. У нього є цікаві теорії щодо очищення цих земель.",
        ["npcs"] = { [1] = 16135 },
        ["roles"] = { ["greeting"] = true },
    },
    [3426167510] = {
        ["english"] = { [1] = "We cannot afford to give an inch in this war. Day and night, I create new armor, and I patch whatever can be salvaged from the old. I have no time for other tasks. Would you take care of something for me?" },
        ["text"] = "У цій війні ми не можемо поступитися ані п'яддю. День і ніч я кую нові обладунки й лагоджу все, що ще можна врятувати зі старих. На інші справи часу немає. Чи не зробиш ти дещо для мене?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3413162844] = {
        ["english"] = { [1] = "We are one in the Light, $g brother : sister;, but I cannot train you." },
        ["text"] = "Ми єдині у Світлі, $g брате : сестро;, але навчати тебе я не можу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [821035288] = {
        ["english"] = { [1] = "We are dominating the Scourge - the effects of the altered plague will affect them for at least another full day!  We need to stay on top of it though, so be sure to sabotage a cauldron when you can." },
        ["text"] = "Ми беремо гору над Скарою — дія зміненої чуми триматиметься на них щонайменше ще цілий день! Але не можна послаблювати тиск, тож за нагоди обов'язково саботуй котел.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2760548764] = {
        ["english"] = { [1] = "We are all pieces of a much larger puzzle, $N. Just as you guide the piece of a puzzle to its destination, so too are we guided by another.$B$BAnd perhaps they who guide us are themselves guided by an even greater force." },
        ["text"] = "Ми всі — лише частини набагато більшої мозаїки, $N. Як ти спрямовуєш шматочок мозаїки на його місце, так само й нас спрямовує хтось інший.$B$BА можливо, ті, хто спрямовує нас, самі ведені ще величнішою силою.",
        ["npcs"] = { [1] = 13085 },
        ["roles"] = { ["greeting"] = true },
    },
    [944638183] = {
        ["english"] = { [1] = "Yap, I can teach ye to fish." },
        ["text"] = "Авжеж, я можу навчити тебе рибалити.",
        ["npcs"] = { [1] = 3332 },
        ["roles"] = { ["greeting"] = true },
    },
    [2046515486] = {
        ["english"] = { [1] = "Troggs?!  Are the troggs you mention the same as the ones in the world today?" },
        ["text"] = "Трогги?! Ті трогги, про яких ти кажеш, — це ті самі, що живуть у світі нині?",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [3176078418] = {
        ["english"] = { [1] = "Where's my spinner? I just had it here somewhere..." },
        ["text"] = "Де моя блешня? Щойно ж була десь тут...",
        ["npcs"] = { [1] = 3290 },
        ["roles"] = { ["greeting"] = true },
    },
    [2037919567] = {
        ["english"] = { [1] = "Using the fruits of the Earth Mother to create potions to aid us in our eternal struggle is an honorable endeavor.  To learn of this you must travel north to our great home of Thunder Bluff.  When you arrive at the top seek out the assistance of one of the Bluffwatchers for more specific directions." },
        ["text"] = "Створювати з плодів Матері-Землі зілля, що допомагають нам у вічній боротьбі, — почесне заняття. Щоб навчитися цього, вирушай на північ до нашої великої домівки — Громового Бескиду. Коли піднімешся нагору, попроси одного з Вартових Бескиду вказати точніший шлях.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [1158830430] = {
        ["english"] = { [1] = "Vesprystus' hippogryphs will bear you swiftly to your destination.  Seek him out in Rut'theran Village, through the portal which lies in the western section of Darnassus." },
        ["text"] = "Гіпогрифи Веспристуса швидко доправлять тебе до місця призначення. Шукай його в селищі Рут'теран, за порталом у західній частині Дарнаса.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1122768692] = {
        ["english"] = { [1] = "Varos Cloudstrider and his ring guardians protect the second ring.  Your drakes are more than a match for the Ring Guardians, but Varos stands behind an impenetrable shield created from the energy of the Oculus itself.  Ten Centrifuge Constructs power the shield from the ring and platforms above.  Destroy them and Varos will be vulnerable.$B$BI can grant you the power to call upon a drake from the Red Fight.  Speak to Eternos or Verdisa if you prefer to draw on the power of the Bronze or the Green." },
        ["text"] = "Варос Хмароступ і його вартові кільця захищають друге кільце. Твої драки більш ніж здатні впоратися з Вартовими Кільця, але Варос стоїть за непроникним щитом, створеним енергією самого Окулуса. Десять Відцентрових Конструктів живлять щит із кільця та платформ вище. Знищ їх — і Варос стане вразливим.$B$BЯ можу дати тобі силу прикликати драка Червоної зграї. Поговори з Етерносом або Вердісою, якщо волієш скористатися силою Бронзової чи Зеленої зграї.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1864740757] = {
        ["english"] = { [1] = "Um... what was that?" },
        ["text"] = "Ем... що це було?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [465341207] = {
        ["english"] = { [1] = "Transport me to the Molten Core, Lothos." },
        ["text"] = "Перенеси мене до Вогняних Надр, Лотосе.",
        ["npcs"] = { [1] = 14387 },
        ["roles"] = { ["reply"] = true },
    },
    [1903509390] = {
        ["english"] = { [1] = "Wailing Caverns" },
        ["text"] = "Печери Стогону",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [2998793548] = {
        ["english"] = { [1] = "Us need check to see if our Brain... Brain... Brain Hacker sold at auction.  You find mailbox next to inn on upper ring of Trade Quarter." },
        ["text"] = "Нам треба перевірити, чи наш Мозко... Мозко... Мозколам продали на аукціоні. Поштова скринька біля таверни на верхньому кільці Торгового кварталу.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [1056831626] = {
        ["english"] = { [1] = "We've done it, $N.  With Sun's Reach under our control we are but mere moments away from absolute victory." },
        ["text"] = "Ми це зробили, $N. Сонячний Край під нашим контролем, і до абсолютної перемоги лишилися лічені миті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2248125011] = {
        ["english"] = { [1] = "Us know where they are!  Skull building in Magic Quarter on outer ring of city." },
        ["text"] = "Ми знаємо, де вони! Будівля з черепом у Кварталі Магії, на зовнішньому кільці міста.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3961624783] = {
        ["english"] = { [1] = "Whatever you're going to ask for, do it quickly." },
        ["text"] = "Що б ти не збирався просити, роби це швидко.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1203747728] = {
        ["english"] = { [1] = "What ISN'T there to do, you mean!$B$BEach of the innkeepers throughout the world are handing out trick-or-treat goodies, and many of the towns are decorated for the season!  Also, there is the Wickerman Festival just outside the Undercity during the evenings.$B$BOne more thing - I've heard that a sick little girl at the orphanage here in Orgrimmar is looking for someone to help her gather treats for the holiday... maybe you could help her out?" },
        ["text"] = "Ти хотів сказати, чого тут НЕ робити!$B$BГосподарі таверн по всьому світу роздають ласощі за «цукерку чи капость», а багато міст прикрашені до свята! Крім того, вечорами просто біля Підмістя відбувається Свято Плетеного Чоловіка.$B$BІ ще одне — я чув, що хвора дівчинка в сиротинці тут, в Орґріммарі, шукає когось, хто допоможе їй назбирати святкових ласощів... може, допоможеш їй?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2145299538] = {
        ["english"] = { [1] = "What do they say?" },
        ["text"] = "Що вони кажуть?",
        ["npcs"] = { [1] = 15169 },
        ["roles"] = { ["reply"] = true },
    },
    [3476046583] = {
        ["english"] = { [1] = "Warlocks, eh.  Well, you didn't hear it from me, but I've heard rumors that those types gather at a bar called the Slaughtered Lamb in the Mage Quarter.  " },
        ["text"] = "Чорнокнижники, кажеш? Ну, ти цього від мене не чув, але ходять чутки, що такі типи збираються в барі «Зарізане Ягня» в Кварталі Магів.  ",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2488101725] = {
        ["english"] = { [1] = "To maintain our link to the mainland, we have hippogryphs constantly flying between Rut'theran Village and Darkshore." },
        ["text"] = "Щоб підтримувати зв'язок із материком, наші гіпогрифи безперервно літають між селищем Рут'теран і Темнобережжям.",
        ["npcs"] = { [1] = 3838 },
        ["roles"] = { ["greeting"] = true },
    },
    [1640126882] = {
        ["english"] = { [1] = "Training you further is beyond my abilities. Speak to Telonis in the Craftsmen's Terrace of Darnassus. He is always glad to help talented students." },
        ["text"] = "Далі навчати тебе мені вже не до снаги. Поговори з Телонісом на Терасі Ремісників у Дарнасі. Він завжди радий допомогти здібним учням.",
        ["npcs"] = { [1] = 3967 },
        ["roles"] = { ["greeting"] = true },
    },
}
for key, row in pairs(rows) do addonTable.gossip_hashed.rows[key] = row end
